var e={"tool.look":`Observer`,"tool.build":`Construire`,"tool.remove":`Démolir`,"action.rotate":`Pivoter`,"action.undo":`Annuler`,"action.redo":`Rétablir`,"action.inventory":`Inventaire`,"action.alt":`Détails`,"action.close":`Fermer`,"action.save":`Sauvegarder`,"key.hint":`{key}`,"status.0":`En attente`,"status.1":`En marche`,"status.2":`Pas d’entrée`,"status.3":`Sortie pleine`,"status.4":`Aucune ceinture à portée`,"status.5":`Aucune recette`,"status.6":`Aucune cible`,"status.2.hint":`Apportez les ingrédients avec une pince ou posez-les à la main.`,"status.3.hint":`Récupérez la production avec une pince ou le bouton « Prendre ». Liquide : posez des tuyaux ou un réservoir.`,"status.4.hint":`L’extracteur n’atteint aucune ceinture — rapprochez-le de la bande de roches : le fantôme en main rougit quand aucune ceinture n’est à portée.`,"status.5.hint":`Choisissez une recette ci-dessous.`,"status.6.hint":`Une pince a besoin d’une machine ou d’un gravitapis devant et derrière.`,"machine.recipe":`Recette`,"machine.input":`Entrée`,"machine.output":`Sortie`,"machine.contents":`Contenu`,"machine.empty":`Vide`,"machine.held":`En main`,"machine.take":`Prendre`,"machine.put":`Poser {item}`,"machine.remove":`Démolir`,"machine.time":`{s} s`,"inv.title":`Inventaire`,"inv.craft":`Fabrication manuelle`,"inv.queue":`File`,"inv.missing":`Manque`,"inv.craftOne":`×1`,"inv.craftFive":`×5`,"inv.cancel":`Annuler`,"inv.empty":`Vide`,"goal.title":`Objectif`,"goal.skip":`Replier l’objectif`,"goal.ask.go":`Afficher`,"goal.show":`Voir les objectifs`,"goal.done":`Tous les objectifs sont atteints ! La suite, c’est votre propre usine autour d’une étoile vivante.`,"goal.mine":`Extrayez {n} quartz à la main`,"goal.mine.hint":`{touch, select, yes {Touchez un rocher bleu} other {Cliquez sur un rocher bleu}} de la ceinture près du repère — le rayon de la vedette extraira le quartz tout seul ; toucher à nouveau ce rocher l’arrête.`,"goal.grinder":`Posez un polissoir à côté du récepteur`,"goal.grinder.hint":`Barre des bâtiments → polissoir → un emplacement près du récepteur. Puis « Observer », {touch, select, yes {touchez-le} other {cliquez dessus}} et choisissez « Lentille ».`,"goal.grabber":`Reliez la ligne avec des pinces : la première lentille`,"goal.grabber.hint":`Une pince prend derrière et pose devant, dans le sens de sa flèche. La première : gravitapis → polissoir. La seconde : polissoir → réserve (caisse).`,"goal.lenses":`Attendez {n, plural, one {# lentille} other {# lentilles}} de la ligne`,"goal.lenses.hint":`Rien à faire : la ligne produit une lentille toutes les {sec} s. Elle s’arrête ? {touch, select, yes {Touchez} other {Cliquez sur}} la machine marquée d’un badge, sa fenêtre dit ce qui ne va pas.`,"goal.obsidian":`Un harpon aux rochers orange, puis {n, plural, one {# plaque} other {# plaques}} de la ligne`,"goal.obsidian.hint":`Le troisième harpon va dans le cadre entre la ceinture et le polissoir à plaques, sortie (le point lumineux) droit dedans : il charge le polissoir lui-même, sans gravitapis. Dès qu’il attrape un rocher, le cadre s’éteint et la ligne produit les plaques toute seule : attendez-en {n}. Lumière : un arc de plus et un lumiduc.`,"goal.expand":`Un second polissoir — pour les plaques, près des rochers orange`,"goal.expand.hint":`Fabriquez un polissoir dans l’« Inventaire » ({plates} plaques, {quartz} quartz) et posez-le dans le cadre près de la ceinture orange, côté base. Recette : « Plaque d’obsidienne ». Le harpon se place entre lui et la ceinture : un gravitapis ne peut pas traverser une ceinture.`,"goal.progress":`{have} / {need}`,"toast.saved":`Sauvegardé`,"toast.loaded":`Monde chargé`,"toast.noItem":`Pas de « {item} » dans l’inventaire — fabriquez-en dans l’inventaire`,"toast.newWorld":`Nouveau monde`,"hud.mining":`Extraction`,"hud.debug":`FPS {fps} · UPS {ups} · tick {tick} · machines {entities} · hash {hash}`,"hotbar.label":`Bâtiments`,"a11y.game":`Terrain de jeu de Starwarden`,"machine.rate":`Consomme {rate} {item}/s`,"machine.drills":`≈ {n, plural, one {# harpon} other {# harpons}} en entrée`,"action.pause":`Pause`,"action.resume":`Reprendre`,"hud.paused":`En pause`,"toast.recipeCopied":`Recette copiée — Maj+clic sur un assembleur pour la coller`,"goal.light":`Amenez la lumière du récepteur au polissoir`,"goal.light.hint":`Tirez un lumiduc de la parabole du récepteur jusqu’à un côté du polissoir — ou placez le polissoir tout contre le récepteur : la lumière passe sans lumiduc. Il s’allume : la lumière est arrivée. Un Arc I donne {arc} ph/s (photons par seconde) — de quoi alimenter un seul polissoir.`,"goal.collectors":`De la lumière pour la base : {n} ph/s ({arcs, plural, one {# arc} other {# arcs}})`,"goal.collectors.hint":`Fabriquez un « Arc I » dans l’« Inventaire » et lancez-le sur l’anneau près de l’étoile. Chaque arc donne {arc} ph/s ; un récepteur prend jusqu’à {cap}.`,"goal.mix":`Mélangez de l’ambre`,"goal.mix.hint":`Mélangeur : des couleurs différentes sur les entrées latérales → de l’ambre devant. La même lumière des deux côtés se consume. Ne fusionnez pas les couleurs dans un même lumiduc : elles interféreraient.`,"goal.focus":`Fabriquez des résonateurs`,"goal.focus.hint":`Un résonateur exige une lumière blanche d’intensité {b} : un focaliseur augmente l’intensité de 1. Un long lumiduc faiblit toutes les {fade} cases.`,"machine.light":`Lumière : {amount} ph, couleur {color}, intensité ≥ {b}`,"machine.flux":`Flux : {n} ph/s`,"machine.lightBuf":`En tampon : {n} ph`,"color.1":`écarlate`,"color.2":`émeraude`,"color.4":`azur`,"color.3":`ambre`,"color.6":`cyan`,"color.5":`magenta`,"color.7":`blanc`,"status.7":`Pas de lumière`,"status.8":`Lumière faible`,"status.9":`Interférence`,"status.10":`Mauvaise couleur`,"status.7.hint":`Tirez un lumiduc depuis un récepteur ou placez la machine tout contre sa sortie. La lumière s’accumule par portions à chaque cycle.`,"status.8.hint":`Intensité insuffisante : un réseau de plus de {fade} cases faiblit — raccourcissez-le ou ajoutez un focaliseur.`,"status.9.hint":`Une couleur, un réseau : des lumiducs qui se touchent fusionnent. Séparez les réseaux de couleurs différentes par une case vide ; un lumiduc en main surligne ce qu’il va rejoindre.`,"status.10.hint":`La recette demande une autre couleur — branchez la bonne sortie du prisme ou du mélangeur.`,"goal.beam":`Envoyez la lumière en rayon`,"goal.beam.hint":`Un port sur un lumiduc change la lumière en rayon, un miroir le dévie, un port en face le reçoit. Un port sans récepteur gaspille la lumière.`,"goal.plates":`Un harpon de plus pour la ligne de plaques : {n, plural, one {# plaque} other {# plaques}}`,"goal.plates.hint":`Un harpon coûte {lenses} lentilles et {plates} plaques : les lentilles sont dans la caisse de la ligne — « Prendre » dans sa fenêtre. Fabriquez un harpon dans l’« Inventaire » et posez-le dans le cadre près du polissoir à plaques, sortie vers lui. Une fois posé, le cadre s’éteint et la ligne tourne à plein régime : attendez {n} plaques. Le polissoir demande {light} ph/s de lumière : s’il en manque, lancez un arc de plus.`,"action.sound":`Son`,"action.soundOn":`Activer le son`,"action.soundOff":`Couper le son`,"stats.title":`Statistiques`,"stats.min1":`1 min`,"stats.min10":`10 min`,"stats.perMin":`{n}/min`,"stats.empty":`Rien n’a encore été produit.`,"goal.completed":`Objectif accompli`,"goal.mine.why":`Le module de l’« Hirondelle » est en pièces ; les dormeurs survivent sur les panneaux de secours. Seule une usine peut les sauver, et elle commence par le quartz : on y taille les lentilles.`,"goal.grinder.why":`Les archives des « Semailles » contiennent les plans de toutes les machines de la colonie, mais aucune ne se monte sans lentilles. Le polissoir les taille dans le quartz.`,"goal.light.why":`La lumière de l’arc n’est qu’un début : il faut l’amener jusqu’aux machines. Le lumiduc est la première veine de la future colonie.`,"goal.grabber.why":`Une usine qui attend les mains de la Sentinelle ne sauvera pas les dormeurs. Les pinces passent les objets de machine en machine : la ligne tourne toute seule.`,"goal.lenses.why":`Les arcs, le Centre et presque toutes les machines des archives ont besoin de lentilles. Un stock de lentilles, c’est du temps gagné pour les dormeurs.`,"goal.expand.why":`Pour colmater le module et bâtir des machines, il faut des châssis : des plaques. On les tire des rochers orange, l’obsidienne.`,"goal.obsidian.why":`Les plaques à la main, c’est trop lent, et le module de l’« Hirondelle » a besoin de rustines. La ligne les produit toute seule.`,"goal.plates.why":`Les plaques entrent dans tout : machines, rustines du module, futur portail. Pleine lumière sur la ligne, pleine vitesse.`,"goal.collectors.why":`Quarante capsules, les archives, le Centre : tout vit de lumière. Chaque arc est un morceau de la future sphère autour du Berceau.`,"goal.mix.why":`Après le raid, c’est clair : la base doit se défendre. L’ambre charge la Lance : {n} par Lance. Le prisme ne donne pas cette couleur — on la mélangera nous-mêmes.`,"goal.focus.why":`Un résonateur garde la lumière stable. On en fait la Lance et des machines plus récentes — et une lumière stable éblouit moins l’Essaim.`,"goal.beam.why":`La colonie a besoin de lumière au-delà des ceintures : de nouvelles roches et de la place pour les machines l’y attendent. Un rayon porte la lumière loin, sans faiblir, et passe au-dessus des ceintures.`,"goal.spectrum_m.why":`Un spectre est un échantillon de la lumière d’une classe d’étoiles. Les archives débloquent des plans selon les classes lues : la première, M, ouvre la Résonance.`,"goal.spectrum_m.hint":`Assembleur : la recette « Spectre M » — une lentille rubis, une plaque et de la lumière rouge. Apportez les spectres au Centre par gravitapis et pince, ou à la main.`,"goal.spectrum_m":`Livrez {n, plural, one {# spectre} other {# spectres}} M au Centre`,"goal.resonance.why":`La Résonance rend les extracteurs deux fois plus rapides : l’usine grandit plus vite — et la lumière atteint plus tôt les dormeurs.`,"goal.resonance.hint":`Recherchez « Résonance ». Une voile sur un lumiduc accélère les extracteurs proches ; les pylônes portent l’effet plus loin (jusqu’à {link} cases). Les harpons doivent se trouver dans une zone de {zone}×{zone}.`,"goal.resonance":`Recherchez la Résonance et accélérez {n, plural, one {# harpon} other {# harpons}}`,"goal.spectrum_k.why":`La deuxième classe d’étoiles : K, orange. Chaque classe lue débloque de nouveaux plans dans les archives — et rapproche le portail.`,"goal.spectrum_k.hint":`Recherchez « Spectroscopie » et ajoutez un second assembleur. K : une lentille ambre, une pince et la lumière ambrée du mélangeur (rouge + émeraude). Si une pince ne suit pas l’assembleur, remplacez-la par une pince rapide (« Logistique »). Inutile de porter à la main : une pince du banc vers une caisse, un gravitapis de la caisse à l’assembleur ; remplissez la caisse de pinces voisine avec « Tout poser ».`,"goal.spectrum_k":`Livrez {n, plural, one {# spectre} other {# spectres}} K au Centre`,"goal.liquid.why":`La lumière condensée est l’étape suivante vers la classe G, celle du Berceau lui-même. Sans lumière liquide, impossible de lire son spectre.`,"goal.liquid.hint":`Recherchez « Lumière liquide ». La glace vient des météorites : touchez une météorite et survolez les éclats. Placez un condenseur sur la lumière azur d’un prisme et donnez-lui de la glace. Le liquide doit pouvoir s’écouler : un tuyau contient {cap} u — posez {pipes} tuyaux depuis le condenseur (plus tard, un réservoir ou un assembleur de spectre G).`,"goal.liquid":`Produisez {n} u de lumière liquide`,"goal.spectrum_g.why":`La classe G — comme le Berceau lui-même. Trois classes lues, et le Centre pourra décomposer sa lumière jusqu’aux raies les plus ténues.`,"goal.spectrum_g.hint":`Recherchez « Classe G ». Recette : un résonateur, de la lumière liquide et de l’ambre d’intensité {b} (après un focaliseur).`,"goal.spectrum_g":`Livrez {n, plural, one {# spectre} other {# spectres}} G au Centre`,"goal.mine.done":`Quartz en soute. Première pierre d’une colonie qui ne figurait dans aucun plan. J’ai noté l’heure.`,"goal.grinder.done":`Un polissoir ! J’ai passé mon examen de formation sur un de ces engins. Choisissez la recette « Lentille » et donnez-lui lumière et pierre.`,"goal.light.done":`Ça brille ! Si la lumière est arrivée au polissoir, elle arrivera aux dormeurs. Pas tout de suite, mais elle arrivera.`,"goal.grabber.done":`Première lentille sortie de la ligne. L’usine est vivante : elle travaille même quand vous regardez ailleurs.`,"goal.lenses.done":`{n, plural, one {# lentille} many {# lentilles} other {# lentilles}} — la ligne tourne sans vous.`,"goal.expand.done":`Un deuxième polissoir, pour les plaques — c’est avec elles qu’on colmatera le module. Posez un harpon à côté, sortie droit dedans.`,"goal.obsidian.done":`Les plaques arrivent. De quoi colmater le module — et faire grandir une colonie.`,"goal.plates.done":`Ça, c’est de la cadence ! Avec une ligne pareille, on va bientôt me sortir de sous la cloison. Je plaisante : les dormeurs d’abord.`,"goal.collectors.done":`{n} photons par seconde — de quoi alimenter {grinders, plural, one {# polissoir} many {# polissoirs} other {# polissoirs}}.`,"goal.mix.done":`L’ambre — une couleur qu’aucun prisme ne donne. Elle sort de vos mains.`,"goal.focus.done":`Résonateurs prêts — la lumière est prise dans une oscillation pure.`,"goal.beam.done":`Le rayon est arrivé. La lumière n’est plus liée aux lumiducs.`,"goal.spectrum_m.done":`Le Centre a lu son premier spectre ! Encore {n} spectres M, et il recherchera la Résonance.`,"goal.resonance.done":`Harpons en résonance — deux fois plus rapides.`,"goal.spectrum_k.done":`Deuxième classe lue. Le Centre gagne un second anneau et des rayons.`,"goal.liquid.done":`La lumière coule dans les tuyaux comme du miel. Maman n’y croirait pas.`,"goal.spectrum_g.done":`Trois spectres lus. Le Centre est prêt pour le Signal profond.`,"intro.title":`Semeur « Hirondelle »`,"intro.p1":`Vous êtes la Sentinelle du semeur « Hirondelle » — la seule personne éveillée pendant le voyage. À bord : quarante colons endormis, un vieux mécanicien navigant et l’IA nommée ORA. L’« Hirondelle » est la septième des douze, cap sur l’étoile Claire.`,"intro.p2":`Si le voyage tourne mal, la lumière de l’étoile vous sauvera : les arcs la captent, et l’usine en tire tout le reste. Les plans sont dans les archives du vaisseau.`,"intro.start":`Décoller`,"card.pick":`Choisissez un objet ou une recette — vous verrez ce que c’est et à quoi ça sert.`,"card.byHand":`À la main`,"card.cat.ore":`Pierre`,"card.cat.intermediate":`Matériau`,"card.cat.building":`Bâtiment`,"card.cat.ship":`Module de vaisseau`,"card.have":`{n} en stock`,"card.made":`Obtention`,"card.used":`Sert à`,"lock.lab":`Débloqué par le Centre : {tech}`,"toast.locked":`{item} est verrouillé — le Centre le débloque : {tech}`,"inv.items":`Objets`,"inv.craftHint":`clic — détails et fabrication ; clic droit — en fabriquer un`,"lab.title":`Centre de recherche`,"lab.tier":`rang {n}`,"lab.lore":`Les Centres se bâtissent d’après un plan de l’archive du vaisseau. Chacun lit les spectres à la lumière — un lumiduc vers n’importe lequel de ses côtés. La file et la progression sont communes, mais chaque Centre a sa propre science et lit sa propre unité\xA0: plus de Centres, plus de vitesse. Chaque classe spectrale lue ouvre des technologies et allume un anneau de sa couleur.`,"lab.spectra":`Science dans tous les Centres`,"lab.delivered":`total {n}`,"lab.putSpectra":`Répartir la science entre les Centres (les plus proches d’abord)`,"lab.current":`Recherche en cours`,"lab.idle":`Choisissez une technologie : « En tête » ou « Ajouter » dans la liste ci-dessous ou dans l’arbre. Le Centre ne lance rien seul — la science attend dans ses emplacements.`,"lab.tree":`Arbre des technologies`,"lab.request":`{spectra} {have}/{need} → {tech}`,"tech.queued":`en file · {n}`,"tech.state.done":`recherchée`,"tech.state.current":`en cours`,"tech.state.queued":`en file`,"tech.state.available":`disponible`,"tech.state.locked":`verrouillée`,"tech.cost":`Coût : unités × une pièce de chaque palier`,"tech.requires":`D’abord : {list}`,"tech.enqueue":`Ajouter`,"tech.dequeue":`Retirer`,"tech.first":`En tête`,"fluid.amount":`{n} u · {name}`,"machine.fluid":`{name} : {n} u`,"machine.net":`{name} dans le réseau : {n} / {cap} u`,"machine.boost":`résonance +{n} %`,"machine.resonance":`Réseau de résonance : {n} % de la demande couverte`,"etude.title":`Expériences`,"etude.lore":`De courts casse-têtes sur une lumière familière : pièces limitées, une seule tâche. Plus c’est rapide, économique et compact, mieux c’est.`,"etude.parts":`{n, plural, one {# pièce} other {# pièces}}`,"etude.area":`surface {n}`,"etude.best":`Meilleur résultat :`,"etude.start":`Lancer l’expérience`,"etude.solved":`Expérience réussie !`,"etude.goal":`Produisez avec des machines : {item} × {n}`,"etude.again":`Encore une fois`,"etude.pure_tone.name":`Couleur pure`,"etude.pure_tone.task":`Trois sources de blanc, un prisme et un banc : ne donnez au banc que du rouge et faites {n} lentilles rubis. Score — pièces, surface, temps. Les rayons aident à économiser des lumiducs.`,"lab.waiting":`Une unité = une pièce de chaque palier. En attente : {spectra}. Des spectres en trop d’autres classes n’accélèrent rien.`,"hint.prism.3":`Les machines en sortie ne prennent pas de lumière : leur production n’a nulle part où aller, ou une autre entrée leur manque. Donnez-leur du travail — le prisme reprendra seul.`,"hint.drill.6":`La sortie du harpon ne mène nulle part — pivotez (R) vers un gravitapis, une machine ou une réserve.`,"hint.crafter.7":`Pas assez de lumière : le réseau la partage entre tous ses consommateurs (les voiles aussi en boivent). Ajoutez des arcs sur l’enveloppe, un deuxième récepteur, ou séparez le réseau.`,"menu.title":`Menu`,"menu.tagline":`Une usine autour d’une étoile vivante`,"menu.continue":`Continuer`,"menu.newWorld":`Nouveau monde`,"menu.back":`← Retour`,"menu.difficulty":`Difficulté`,"menu.seed":`Graine du monde`,"menu.randomSeed":`Graine aléatoire`,"menu.start":`Commencer`,"difficulty.calm":`Contemplation`,"difficulty.calm.desc":`Pas d’Essaim. Juste la lumière, les ceintures et la construction.`,"difficulty.standard":`Standard`,"difficulty.standard.desc":`Les nids s’éveillent sous l’éblouissement et envoient des vagues — toujours avec préavis. Tourelles, barrières et réparations sauvent la base.`,"difficulty.abyss":`Abîme`,"difficulty.abyss.desc":`Nids plus proches, vagues plus fréquentes et plus féroces, planètes sous les ruches. Pour les vétérans.`,"settings.title":`Paramètres`,"settings.tab.general":`Général`,"settings.tab.graphics":`Graphismes`,"settings.tab.sound":`Son`,"settings.tab.controls":`Commandes`,"settings.tab.access":`Accessibilité`,"settings.lang":`Langue`,"settings.quality":`Qualité`,"settings.quality.low":`Basse`,"settings.quality.medium":`Moyenne`,"settings.quality.high":`Haute`,"settings.quality.ultra":`Ultra`,"settings.quality.hint":`« Basse » coupe le halo (bloom) : pour les téléphones modestes et les longues parties sur batterie. « Ultra » affiche à pleine netteté et chauffe davantage le téléphone.`,"settings.showFps":`Afficher les FPS`,"settings.muted":`Muet`,"settings.master":`Volume`,"settings.effects":`Effets`,"settings.ambience":`Ambiance`,"settings.voices":`Voix des personnages`,"settings.keys.hint":`Cliquez sur la touche d’une action, puis appuyez sur la nouvelle touche. Esc annule.`,"settings.keys.press":`Appuyez…`,"settings.keys.fixed":`Toujours : 1–0 barre rapide, Ctrl+Z/Y annuler/rétablir, Ctrl+S sauvegarder, Esc menu, Ctrl+C/V plan.`,"settings.keys.reset":`Touches par défaut`,"settings.uiScale":`Échelle de l’interface`,"settings.reduceFlashes":`Moins de flashs et de clignotements`,"settings.shapesAlways":`Formes de couleur en permanence (pas qu’en mode aide)`,"settings.access.hint":`Chaque couleur de lumière a sa forme : écarlate ▲, émeraude ●, azur ◆, ambre ■ — comme les signes sur le dos de l’Essaim.`,"key.rotate":`Pivoter`,"key.pipette":`Pipette`,"key.remove":`Démolir`,"key.inventory":`Inventaire`,"key.lab":`Recherches`,"key.alt":`Mode Alt`,"key.pause":`Pause`,"key.sound":`Son on/off`,"key.stats":`Statistiques`,"key.blueprint":`Plan`,"status.13":`Pas de paire`,"status.13.hint":`Posez la deuxième arche devant, à portée du pli (la recherche l’allonge). Un pli de fret a besoin d’une sortie ; les plis de lumière et de tuyau, d’une arche tournée face à la première.`,"status.14":`Surchauffe`,"status.14.hint":`La machine surchauffe : elle ralentit et perd de la lumière en éblouissement. Éloignez-la de l’étoile (r ≥ 7,5) ou ajoutez un radiateur à glace.`,"status.15":`Éteint`,"status.15.hint":`La machine est à l’arrêt : étourdie par la grêle ou sous le quart de son intégrité. Réparez-la — ou attendez, l’étourdissement se dissipe.`,"status.16":`Perd de la lumière`,"status.16.hint":`Une partie de la lumière n’a nulle part où aller et devient éblouissement. Utilisez la sortie en trop ou envoyez-la dans un absorbeur.`,"status.17":`Pas de glace`,"status.17.hint":`Apportez de la glace avec une pince : 1 pour {burn} secondes de refroidissement.`,"hud.glare":`Éblouissement {v} ph/s`,"bp.title":`Plans`,"bp.lore":`Un bon bloc construit ? Inutile de le refaire. Tracez un cadre autour : le plan va dans votre main et dans la bibliothèque. {touch, select, yes {« Pivoter » le tourne, un toucher choisit l’endroit, « Poser » construit.} other {R pour pivoter, clic pour poser.}} Il se construit depuis l’inventaire ; ce qui manque est ignoré.`,"bp.copy":`Copier par cadre`,"bp.copyHint":`Tracez un cadre autour des bâtiments pour les copier. Esc annule.`,"bp.library":`Bibliothèque`,"bp.empty":`Vide pour l’instant : copiez une partie de votre base.`,"bp.count":`{n, plural, one {# bâtiment} other {# bâtiments}}`,"bp.use":`Utiliser`,"bp.share":`Code`,"bp.delete":`Supprimer le plan`,"bp.import":`Ajouter depuis un code`,"bp.add":`Ajouter`,"bp.bad":`Ce n’est pas un code de plan, ou il est endommagé.`,"bp.skipped":`Bâtiments inconnus ignorés : {n}`,"bp.shared":`Code du plan copié — collez-le à un ami.`,"bp.name":`Plan {n}`,"bp.copied":`Copié : {n, plural, one {# bâtiment} other {# bâtiments}}. {touch, select, yes {Touchez un endroit et appuyez sur « Poser ».} other {R pour pivoter, clic pour poser.}}`,"bp.pasted":`Construits : {n}`,"bp.pastedPart":`Construits : {n} sur {all} ; le reste est bloqué ou manque d’objets.`,"etude.goal.light":`Livrez {n} ph de la bonne lumière au récepteur`,"etude.goal.item":`Livrez {n, plural, one {# pièce} other {# pièces}} au récepteur`,"etude.goal.fluid":`Livrez {n} unités de lumière liquide au récepteur`,"etude.through_wall.name":`À travers le mur`,"etude.through_wall.task":`Le polissoir est enfermé dans un double anneau de murs, avec 7 cases entre eux — aucun pli ne franchit les deux d’un coup. Quartz, lumière blanche et récepteur sont dehors. Faites passer fret et lumière en deux sauts, avec une escale entre les anneaux, et livrez {n} lentilles.`,"etude.amber_duet.name":`Duo d’ambre`,"etude.amber_duet.task":`Changez le blanc en ambre d’intensité 3 (cramoisi + émeraude, puis un focaliseur) et livrez {n} ph au récepteur derrière le mur. Seul un rayon traverse le mur — par la fenêtre.`,"etude.liquid_light.name":`Lumière liquide`,"etude.liquid_light.task":`Un mur à deux fenêtres : glace à droite, lumière à gauche. Le rayon bleu passe par une fenêtre, le liquide par tuyau dans l’autre (une fenêtre = une case : rayon et tuyau ne la partagent pas). Livrez {n} unités de lumière liquide ; le cramoisi et l’émeraude en trop vont aux absorbeurs.`,"goal.tunnel":`Posez un gravitapis des harpons au polissoir`,"goal.tunnel.why":`Une seule vedette, des milliers de roches. Le gravitapis les porte au polissoir sans vous — c’est ainsi qu’on a bâti les premières colonies près des nouvelles étoiles.`,"goal.tunnel.hint":`Prenez un gravitapis, {touch, select, yes {touchez} other {cliquez sur}} la case à la sortie du harpon et glissez jusqu’au polissoir. Pas assez ? Fabriquez-en dans l’« Inventaire » avec du quartz et une plaque.`,"goal.tunnel.done":`Le gravitapis tourne ! Au Havre, on n’en a pas posé depuis quarante ans — la lumière est rationnée, pas de place pour ça.`,"goal.haze":`Ciel clair : {n, plural, one {# prisme} other {# prismes}} en marche, éblouissement ≤ {glare} ph/s`,"goal.haze.why":`La brume grise, c’est l’éblouissement : la lumière perdue par la base. Elle éblouit l’Essaim, et un Essaim ébloui vient éteindre la source. Lumière propre, Essaim calme.`,"goal.haze.hint":`L’éblouissement vient des sorties de prisme sans consommateur, des rayons dans le vide et de la surchauffe. Touchez le badge « Éblouissement » — il montre les machines en cause. Utilisez les sorties en trop ou menez-les à un absorbeur.`,"goal.haze.done":`Le ciel est clair — les étoiles réapparaissent.`,"goal.spear":`Recherchez la « Lance » et chargez-la`,"goal.spear.why":`Toujours plus de météorites — et l’Essaim est déjà venu inspecter la base. La Lance frappe en lumière focalisée : elle fend les météorites et repousse les raids.`,"goal.spear.hint":`La lance demande une intensité ≥ {b} : après un focaliseur. {shot} ph par tir : à {slow} ph/s — un tir toutes les {every} s, à {fast} ph/s — chaque seconde. Portée {range} cases.`,"goal.spear.done":`La lance est chargée. Regardez : une comète fonce vers la base — elle transporte beaucoup de glace.`,"goal.cooling":`Anneau chaud : {n, plural, one {# récepteur} other {# récepteurs}} près de l’étoile sans surchauffe`,"goal.cooling.why":`La colonie a besoin de plus de lumière, et c’est près de la couronne qu’il y en a le plus. Mais les machines y surchauffent : de la glace dans le radiateur — et la chaleur est à vous.`,"goal.cooling.hint":`Recherchez le « Refroidissement ». L’anneau chaud se trouve entre la couronne de l’étoile et l’enveloppe I : un récepteur y capte plus de lumière, mais chauffe. Posez un radiateur à glace tout contre les récepteurs ({n} cases autour) et chargez-y de la glace avec le bouton de sa fenêtre. Le radiateur consomme de la glace tant que le récepteur a chaud : la glace vient des météorites et, à long terme, d’un chalut près de la ceinture de glace et d’un gravitapis avec une pince vers le radiateur (le chalut se débloque dans l’arbre) : le radiateur brûle de la glace tant que le récepteur a chaud.`,"goal.cooling.done":`J’ai passé la moitié de ma vie près du métal brûlant — sans glace, on n’y serre même pas un boulon. L’anneau a refroidi !`,"goal.blueprint":`Copiez une zone ({n}+ bâtiments) et posez la copie`,"goal.blueprint.why":`Une colonie se bâtit sur des années — par blocs répétés. Un bon secteur n’a pas besoin d’être refait : un plan le répète.`,"goal.blueprint.hint":`{touch, select, yes {« Plus » → « Plans » → « Copier par cadre » : tracez un cadre autour des bâtiments, « Copier », puis touchez un endroit et « Poser ».} other {Bouton « Plans » ou C — tracez un cadre, R pour pivoter, clic pour poser.}}`,"goal.blueprint.done":`Plan enregistré. Les archives des « Semailles » s’enrichissent — pour la première fois de notre travail, pas de celui de l’Institut.`,"goal.node":`Nid de l’Essaim : nettoyez-le ou endormez-le`,"goal.node.why":`Un nid de l’Essaim près de la base est une menace permanente. Vous pouvez le nettoyer par la force — ou cesser de l’éblouir : {calm} min sans éblouissement après une vague, et il s’endort. Les deux voies donnent de l’antilumière.`,"goal.node.hint":`Posez une lance à {range} cases du nid (flèche) et donnez-lui une lumière focalisée (intensité {b}+) : {shots} tirs pour la reine. La lumière passe par rayon : port → miroirs → port. La reine lâche des gardes contre votre vaisseau — surveillez le bouclier.`,"goal.node.done":`Le nid ne menace plus la base : nettoyé, il brille en protoétoile ; calmé, il dort.`,"status.11":`Pas de liquide`,"status.11.hint":`Raccordez un tuyau de lumière liquide ou libérez l’évacuation : la recette veut du liquide en entrée, ou de la place pour lui en sortie.`,"status.12":`Pas de réseau`,"status.12.hint":`Aucun pylône ni tuyau à proximité — posez-en un plus près.`,"machine.heat":`Chaleur {n} %`,"machine.heatLoss":`perd de la lumière en éblouissement — éloignez-la de l’étoile ou ajoutez un radiateur`,"machine.glare":`Perd {n} ph/s → éblouissement`,"machine.ice":`Glace : {n}`,"cfg.title.modulator":`Rythme`,"cfg.modulator.0":`Constant ▬▬▬`,"cfg.modulator.1":`Pulsé ▮ ▮ ▮`,"cfg.modulator.2":`Double ▮▮ ▮▮`,"cfg.modulator.3":`Décalé ▮ ▮▮ ▮`,"cfg.title.polarizer":`Angle du filtre`,"cfg.polarizer.1":`0°  |`,"cfg.polarizer.2":`45°  /`,"cfg.polarizer.3":`90°  —`,"status.18":`Mauvais rythme`,"status.18.hint":`La recette veut une lumière d’un autre rythme : posez un modulateur et choisissez le rythme dans sa fenêtre.`,"status.19":`Mauvais angle`,"status.19.hint":`La recette veut une lumière d’un autre angle : posez un polariseur et choisissez l’angle dans sa fenêtre.`,"status.20":`Mauvaise phase`,"status.20.hint":`La recette veut l’autre phase de la lumière : placez un déphaseur sur son trajet.`,"cfg.title.shutter":`Mode de l’obturateur`,"cfg.shutter.0":`Ouvert sur signal`,"cfg.shutter.1":`NON : fermé sur signal`,"status.21":`Aucun destinataire`,"status.21.hint":`Aucun port récepteur du même canal avec de la place pour le fret à moins de {range} cases.`,"status.22":`Aucun drone`,"status.22.hint":`Mettez des drones dans les emplacements du port (un assembleur les fabrique avec des lentilles, un résonateur, des plaques et un spectre F).`,"cfg.title.drone_port":`Rôle du port`,"cfg.role.0":`Construction`,"cfg.role.1":`Envoi`,"cfg.role.2":`Réception`,"cfg.channel":`Canal {n}`,"drone.title":`Canal`,"drone.home":`Drones au port : {n}`,"drone.trips":`Trajets au total : {n}`,"drone.put":`Poser des drones ({n})`,"bp.pastedGhost":`Construits : {n}, et {g} en fantômes : les drones les achèveront dès que les objets arriveront`,"bp.ghosted":`Fantômes : {g} — les drones de construction les achèveront à mesure que les objets arrivent`,"goal.spectrum_f":`Livrez {n, plural, one {# spectre} other {# spectres}} F au Centre`,"goal.spectrum_f.why":`Le rythme est la troisième propriété de la lumière après la couleur et l’intensité : le même vert, qui clignote selon un motif. Les nids et l’étoile clignotent ainsi — il est temps de comprendre ce que cela signifie.`,"goal.spectrum_f.hint":`Recherchez « Rythme », placez un modulateur entre le prisme et l’assembleur et choisissez « Pulsation » dans sa fenêtre. Le spectre F, ce sont deux lentilles émeraude sous un vert pulsé.`,"goal.spectrum_f.done":`Quatrième classe lue. Les drones porteront le fret à votre place.`,"goal.drone":`Lancez le premier trajet d’un drone`,"goal.drone.why":`Les drones transportent fret et glace, et achèvent les chantiers pendant que vous faites autre chose.`,"goal.drone.hint":`Recherchez « Drones ». Deux ports : l’expéditeur (rôle et canal dans sa fenêtre) contient drones et fret, {charge} ph de lumière par trajet ; le destinataire utilise le même canal. Le rôle « Collecte » rapporte des éclats de glace.`,"goal.drone.done":`Le drone vole ! Un plan peut désormais se construire tout seul.`,"goal.ghost":`Faites achever par les drones {n, plural, one {# bâtiment fantôme} other {# bâtiments fantômes}}`,"goal.ghost.why":`Un plan qui se construit tout seul : les drones achèvent les fantômes pendant que vous filez vers les ceintures et les nids.`,"goal.ghost.hint":`Un port « Construction » avec des drones et les objets des bâtiments dans ses emplacements. {touch, select, yes {Collez un plan : ce qui manque devient fantôme — les drones l’achèvent quand vous apportez les objets.} other {Ctrl+Shift+V colle un plan en fantômes ; un collage normal à court d’objets laisse aussi des fantômes.}}`,"goal.ghost.done":`Le chantier avance sans vous. Collez vos plans à l’avance.`,"goal.spectrum_a":`Livrez {n, plural, one {# spectre} other {# spectres}} A au Centre`,"goal.spectrum_a.why":`La polarisation, c’est la direction dans laquelle la lumière oscille. Les motifs de l’Essaim sont orientés différemment, comme adressés à quelqu’un. Un polariseur fixe l’angle, mais prend la moitié de la lumière.`,"goal.spectrum_a.hint":`Recherchez « Polarisation ». A, c’est une lumière cyan à 45° : un mélangeur, un polariseur réglé sur 45°, un assembleur.`,"goal.spectrum_a.done":`Cinq classes. La lumière connaît le rythme et l’angle — il est temps de lui apprendre à compter.`,"goal.logic":`Montez un circuit : un obturateur et une lampe, {n, plural, one {# basculement} many {# basculements} other {# basculements}} de l’obturateur`,"goal.logic.why":`La lumière vaut un, l’obscurité zéro : l’usine sait raisonner. Et Sonia est sûre qu’une lampe peut aussi répondre.`,"goal.logic.hint":`Recherchez « Logique optique ». Un obturateur laisse passer la lumière tant qu’un signal brille sur son entrée latérale ; une lampe affiche le résultat. Faites un NON rebouclé sur lui-même et vous obtenez un clignotant.`,"goal.logic.done":`La lumière calcule. Un obturateur fermé est une vanne parfaite, sans éblouissement.`,"goal.spectrum_b":`Livrez {n, plural, one {# spectre} other {# spectres}} B au Centre`,"goal.spectrum_b.why":`La phase est la cinquième propriété de la lumière : le décalage d’une onde. Deux ondes décalées de π s’annulent — et pour l’Essaim, ce décalage veut dire « oui ».`,"goal.spectrum_b.hint":`Recherchez « Phase » — elle demande les spectres G, F et A : F et A se partagent les lentilles émeraude, un deuxième banc émeraude accélère. Le spectre B est une lumière bleue en phase π : un déphaseur sur son trajet. Un interféromètre montre l’annulation.`,"goal.spectrum_b.done":`Six classes lues — il ne reste que la dernière, O.`,"achv.title":`Succès`,"achv.count":`{n} sur {all}`,"achv.hidden":`Un succès caché — à vous de le trouver.`,"achv.at":`à {min} min de jeu`,"achv.toast":`Succès : {name}`,"achv.group.story":`Histoire`,"achv.group.mastery":`Maîtrise`,"achv.group.challenge":`Défis`,"achv.first_light.name":`Première lueur`,"achv.first_light.desc":`La lumière a atteint une machine.`,"achv.first_spectrum.name":`Premier spectre`,"achv.first_spectrum.desc":`Le Centre a lu un spectre M.`,"achv.liquid_dawn.name":`Lumière en tuyau`,"achv.liquid_dawn.desc":`La lumière liquide a coulé dans les tuyaux.`,"achv.dark_out.name":`Le nid est tombé`,"achv.dark_out.desc":`La reine est morte — une protoétoile s’est allumée à la place du nid.`,"achv.first_pulse.name":`Pulsation`,"achv.first_pulse.desc":`Le rythme est la troisième propriété de la lumière, après la couleur et l’intensité.`,"achv.sky_carriers.name":`Coursiers célestes`,"achv.sky_carriers.desc":`Le premier trajet d’un drone.`,"achv.logic_gate.name":`La lumière calcule`,"achv.logic_gate.desc":`Le premier circuit à obturateur fonctionne.`,"achv.awakening.name":`Le Lien`,"achv.awakening.desc":`La Fibre longue est tirée — le Havre capte l’« Hirondelle ».`,"achv.red_horizon.name":`Horizon rouge`,"achv.red_horizon.desc":`Un avant-poste près d’une protoétoile de la Crête écarlate.`,"achv.spm_60.name":`Un spectre par seconde`,"achv.spm_60.desc":`{n} spectres par minute.`,"achv.spm_300.name":`Spectrographe`,"achv.spm_300.desc":`{n} spectres par minute.`,"achv.spm_1000.name":`Observatoire`,"achv.spm_1000.desc":`{n, number} spectres par minute.`,"achv.machines_100.name":`Cent machines`,"achv.machines_100.desc":`{n} bâtiments dans le monde.`,"achv.machines_500.name":`Toute une ville`,"achv.machines_500.desc":`{n} bâtiments dans le monde.`,"achv.clean_100.name":`Ciel clair`,"achv.clean_100.desc":`{min} minutes sans éblouissement avec cent machines en marche (gravitapis et lumiducs exclus).`,"achv.clean_1000.name":`Une base sans éblouissement`,"achv.clean_1000.desc":`{min} minutes de ciel clair avec mille machines en marche.`,"achv.tunnel_trio.name":`Cité des plis`,"achv.tunnel_trio.desc":`Fret, lumière et liquide traversent des plis en même temps.`,"achv.blueprint_50.name":`Bureau d’études`,"achv.blueprint_50.desc":`Un plan de {n} bâtiments collé.`,"achv.swarm.name":`Nuée`,"achv.swarm.desc":`{n} drones en vol à la fois.`,"achv.sings.name":`Le calculateur clignotant`,"achv.sings.desc":`Obturateurs basculés {n, number} fois.`,"achv.prima.name":`Prima`,"achv.prima.desc":`Fibre longue en {h} h {m} min de jeu.`,"achv.no_hands.name":`Sans les mains`,"achv.no_hands.desc":`La Fibre longue avec au plus {n} objets fabriqués à la main.`,"achv.silent_hall.name":`Lumière constante`,"achv.silent_hall.desc":`Une heure sans qu’aucune machine clignote « Pas de lumière », avec dix machines ou plus en marche.`,"achv.abyss_awakening.name":`Abîme`,"achv.abyss_awakening.desc":`La Fibre longue dans un monde « Abîme ».`,"achv.clean_awakening.name":`Voie propre`,"achv.clean_awakening.desc":`La Fibre longue sans jamais éblouir le ciel au-delà de {glare} ph/s.`,"etude.locked":`S’ouvre après l’objectif « {goal} »`,"tech.learned":`Recherche terminée : {name}`,"tech.learned.opens":`Recherche terminée : {name} · débloqué : {list}`,"menu.system":`Système stellaire`,"system.cradle":`Le Berceau`,"system.cradle.desc":`Une étoile jaune de classe G et six ceintures. Là où tout commence.`,"system.red_ridge":`La Crête écarlate`,"system.red_ridge.desc":`Une naine rouge : moitié moins de lumière, des ceintures serrées et riches. La lumière blanche ne vient que des protoétoiles-braises dans les interstices.`,"goal.ridge_light":`Captez {n} ph/s de lumière avec des récepteurs`,"goal.ridge_light.why":`La lumière d’une naine rouge est deux fois plus faible — collectez plus près.`,"goal.ridge_light.hint":`Sans lumière blanche, les polissoirs (lentilles et plaques) ne marchent pas, et la naine rouge ne donne que de l’ambre : le blanc vient des protoétoiles, chacune avec sa petite sphère. Les arcs sur la sphère de la naine donnent de l’ambre ; le kit contient 48 lentilles et deux bancs — assez pour l’objectif azur et 4 arcs, ensuite les lentilles de votre propre polissoir.`,"goal.ridge_light.done":`La lumière est réunie. Mais ici, pas de bleu.`,"goal.ridge_blue":`Fabriquez {n, plural, one {# lentille azur} other {# lentilles azur}} avec des machines`,"goal.ridge_blue.why":`La lumière bleue n’existe qu’auprès des protoétoiles : bâtissez un avant-poste.`,"goal.ridge_blue.hint":`Les protoétoiles blanches se trouvent dans les interstices entre les ceintures — la flèche de l’objectif mène à la plus proche. Chacune a sa petite enveloppe de {slots} arcs : posez des arcs et un récepteur à côté — il captera le blanc. Il fait chaud près d’une protoétoile : le bouclier de la vedette ne s’y recharge pas — posez les arcs depuis le bord extérieur et ne vous attardez pas.`,"goal.ridge_blue.done":`L’avant-poste tourne : la lumière bleue a atteint l’usine.`,"settings.haptics":`Retour haptique`,"toast.autoQuality":`Trop peu d’images par seconde : graphismes réduits à « {q} » (moins de halo).`,"touch.hint":`Glissez pour vous déplacer, pincez pour zoomer. Un toucher montre un fantôme, « Poser » confirme. Maintenez une machine pour sa fenêtre, touchez à deux doigts pour annuler.`,"forge.title":`Forge stellaire`,"forge.stars":`étoiles allumées : {n}`,"forge.lore":`Une forge ancienne près du trou noir. Elle prend les sept spectres, l’antilumière et trois marques des systèmes — et maintient le spectre complet jusqu’à ce qu’une étoile s’allume.`,"forge.chord":`Spectre complet : sept classes et l’antilumière`,"forge.relics":`Reliques des systèmes`,"forge.relic.in":`déposée`,"forge.relic.have":`dans votre sac : déposez-la`,"forge.relic.none":`aucune : obtenez-la en achevant l’objectif d’un système`,"forge.put":`Déposer depuis le sac`,"forge.progress":`Maintien du spectre`,"forge.status.0":`La Forge attend le spectre complet.`,"forge.status.1":`Le spectre tient : chaque impulsion prend un spectre de chaque classe et de l’antilumière.`,"forge.status.2":`L’étoile attend. Allumez-la !`,"forge.status.noRelics":`Reliques nécessaires : {have}/{need}. Les objectifs des systèmes les rapportent : Crête, Saphir, Jumeaux, Voile, Pulsar.`,"forge.status.starved":`Le spectre a rompu : il manque « {item} ». La progression baisse.`,"forge.rule":`Une impulsion toutes les {sec} s. Une impulsion manquée coûte {drain} de progression, sans jamais la remettre à zéro.`,"forge.eta":`Encore ≈ {time} à tenir.`,"forge.min":`{n} min`,"forge.sec":`{n} s`,"forge.ignite":`Allumer l’étoile`,"finale.nameTitle":`Nommer l’étoile`,"finale.nameLead":`Elle s’est allumée. Comment l’appeler ?`,"finale.nameOk":`Nommer`,"finale.creditsTitle":`Générique`,"finale.credits.0":`Les étoiles s’éteignaient. Vous avez demandé — et l’une d’elles s’est allumée.`,"finale.credits.1":`Chaque arc de votre sphère est une lumière que l’on a demandée.`,"finale.credits.2":`La lumière blanche, ce sont sept couleurs vues d’un seul coup.`,"finale.credits.3":`La forge est rechargée : la prochaine étoile demandera davantage.`,"finale.credits.4":`Votre constellation vous attend dans le menu principal.`,"finale.credits.5":`Une usine autour d’une étoile vivante.`,"finale.card.time":`heures de jeu`,"finale.card.npm":`pic de spectres par minute`,"finale.card.machines":`machines`,"finale.card.stars":`étoiles dans la constellation`,"finale.continue":`Continuer`,"finale.toast.lit":`L’étoile « {name} » est allumée !`,"menu.stars":`Constellation ({n})`,"menu.starsTitle":`Votre constellation`,"menu.starLine":`{h} h · pic {npm} spectres/min · {machines} machines`,"system.sapphire":`Saphir`,"system.sapphire.desc":`Une géante bleue : bien plus de lumière, mais aussi de chaleur — machines et bouclier surchauffent. Au-delà de la ligne des glaces s’étend une ceinture de givre d’hélium.`,"system.horizon":`Horizon`,"system.horizon.desc":`Un trou noir et son disque d’accrétion — une ceinture rapide et ultra-riche, dans la chaleur. La Forge stellaire : c’est ici que s’allume le final.`,"goal.si":`Produisez {n, plural, one {# spectre} other {# spectres}} O avec des machines`,"goal.si.why":`Classe O — les étoiles les plus chaudes. La clé du portail est le spectre complet, de M à O, et sans la dernière classe, impossible de l’assembler.`,"goal.si.hint":`Recherchez la « Classe O ». O, c’est une lumière magenta à double rythme en phase π (intensité {b}+) plus de l’antilumière : elle tourne en petite ceinture autour d’un nid de l’Essaim nettoyé ou endormi — prenez-la au chalut.`,"goal.si.done":`Sept classes — le spectre complet. Les Forgerons l’arrachaient aux étoiles par la force ; nous l’avons bâti nous-mêmes.`,"goal.sap_cool":`Recherchez « Cryogénie » et posez {n, plural, one {# cryoradiateur} other {# cryoradiateurs}}`,"goal.sap_cool.why":`L’étoile géante fait surchauffer les machines près de la couronne : sans refroidissement, la lumière se perd en éblouissement.`,"goal.sap_cool.hint":`Ouvrez le Centre et mettez la « Cryogénie » en file (les spectres sont dans le kit de départ). Le cryoradiateur refroidit les machines près de la géante.`,"goal.sap_cool.done":`Les machines ont refroidi : vous pouvez bâtir plus près de l’étoile.`,"goal.sap_frost":`Récoltez {n} × givre d’hélium au chalut`,"goal.sap_frost.why":`Le givre est le carburant du cryoradiateur : sans lui, la chaleur revient.`,"goal.sap_frost.hint":`La ceinture de givre est au-delà de la ligne des glaces (flèche). Un chalut près de la ceinture — un gravitapis — une réserve ; le radiateur prend le givre d’une pince.`,"goal.sap_frost.done":`Le givre arrive tout seul.`,"goal.sap_la":`Livrez {n, plural, one {# spectre} other {# spectres}} B au Centre`,"goal.sap_la.why":`Sous la lumière de la géante, les spectres se font plus vite — mais il fait aussi plus chaud.`,"goal.sap_la.hint":`Le spectre B est une lumière bleue en phase π. Servez-vous de tout ce que vous savez : ici, la lumière est généreuse.`,"goal.sap_la.done":`La géante donne sa lumière sans compter.`,"goal.sap_relic":`Atteignez {n, plural, one {# spectre} other {# spectres}} par minute`,"goal.sap_relic.why":`Le gage de Saphir : la Relique du Givre servira près du trou noir.`,"goal.sap_relic.hint":`Tous les spectres ensemble, au moins {n} par minute — le pic est compté une fois par minute. Ajoutez des drones et des enveloppes extérieures.`,"goal.sap_relic.done":`La Relique du Givre est à vous, sauvegardée dans votre profil.`,"goal.hz_light":`Captez {n} ph/s de lumière avec des récepteurs`,"goal.hz_light.why":`Le spectre complet des sept classes exige ≈ 1 000 ph/s de lumière.`,"goal.hz_light.hint":`Le disque du trou noir est très brillant : une sphère autour donne beaucoup. Posez arcs et récepteurs ; près de la couronne, les machines chauffent — radiateurs indispensables.`,"goal.hz_light.done":`Lumière captée. Maintenant, l’Essaim.`,"goal.hz_node":`Nid de l’Essaim : nettoyez-le ou endormez-le`,"goal.hz_node.why":`Un nid — nettoyé ou endormi — laisse une ceinture d’antilumière : il en faut pour le spectre O comme pour la Forge elle-même.`,"goal.hz_node.hint":`Le nid est derrière la base (flèche). Une lance porte à {range} cases, lumière d’intensité {b}+. Ici, la reine est plus coriace et les vagues plus féroces ; on peut aussi cesser de l’aveugler — un nid endormi laisse la même ceinture.`,"goal.hz_node.done":`Le nid ne menace plus — une ceinture d’antilumière tourne autour.`,"goal.hz_si":`Recherchez « Classe O » et produisez {n, plural, one {# spectre} other {# spectres}} O`,"goal.hz_si.why":`La septième classe complète le spectre.`,"goal.hz_si.hint":`Le spectre O : magenta à double rythme en phase π, intensité {b}+, plus de l’antilumière de la ceinture d’un nid nettoyé ou endormi (chalut).`,"goal.hz_si.done":`Sept classes d’étoiles — le spectre complet.`,"goal.hz_antilight":`Récoltez {n} × antilumière au chalut`,"goal.hz_antilight.why":`{forge} part dans les spectres O et {forge} dans la Forge.`,"goal.hz_antilight.hint":`La ceinture d’antilumière tourne autour d’un nid éteint ou endormi : deux chaluts suffisent. N’oubliez pas la défense.`,"goal.hz_antilight.done":`L’antilumière est là. Reste la Forge.`,"goal.hz_ignite":`Allumez l’étoile dans la Forge`,"goal.hz_ignite.why":`Voilà le but de tout cela : le spectre complet — la lumière blanche — allume une étoile.`,"goal.hz_ignite.hint":`Déposez trois reliques, amenez des gravitapis avec les sept spectres et l’antilumière ({rate, number} de chaque par seconde) et maintenez le spectre complet {hold} s.`,"goal.hz_ignite.done":`Une étoile s’allume !`,"relic.earned":`Relique obtenue : « {name} ». Elle est sauvegardée dans votre profil ; trois reliques, quelles qu’elles soient, ouvrent Horizon.`,"achv.class_o_made.name":`Géante bleue`,"achv.class_o_made.desc":`Un spectre O fabriqué par des machines : le spectre complet est réuni.`,"achv.cold_giant.name":`Refroidir la géante`,"achv.cold_giant.desc":`Les cryoradiateurs de Saphir tournent.`,"achv.frost_bearer.name":`Porte-givre`,"achv.frost_bearer.desc":`La Relique du Givre obtenue à Saphir.`,"achv.star_lit.name":`Allumer une étoile`,"achv.star_lit.desc":`La Forge stellaire a libéré le spectre complet : une nouvelle étoile s’est allumée sur la carte.`,"hint.noLight.first":`La lumière n’atteint pas la machine : posez un arc sur l’enveloppe près de l’étoile, un récepteur à côté, et tirez un lumiduc. Le badge au-dessus de la machine indique ce qui manque.`,"toast.autoQuality.undo":`Annuler`,"forge.need":`Il faut {rate} de chaque spectre et d’antilumière par seconde.`,"forge.relicsHint":`La forge reste inerte sans trois reliques : les objectifs des autres systèmes les rapportent. Elles sont gardées dans votre profil et rejoignent le paquetage de chaque nouveau monde.`,"system.twins":`Les Jumeaux`,"system.twins.desc":`Deux étoiles, l’une ambrée, l’autre bleue, avec des ceintures autour des deux. La lumière blanche naît du mélange des deux ; les cellules de lumière tiennent la nuit.`,"system.veil":`Nébuleuse du Voile`,"system.veil.desc":`Une nébuleuse : pas de roche — seulement des ceintures de brume glacée. Quartz et obsidienne se tirent du brouillard.`,"system.pulsar":`Pulsar de Kepler`,"system.pulsar.desc":`Une étoile à neutrons clignote : toute la lumière arrive rythmée, le spectre F se passe de modulateur. Les ceintures sont des débris de supernova.`,"goal.twin_white":`Fabriquez {n, plural, one {# lentille} other {# lentilles}} avec des machines`,"goal.twin_white.why":`Les polissoirs veulent de la lumière blanche, et ici les deux étoiles n’ont pas la même couleur.`,"goal.twin_white.hint":`La sphère des Jumeaux entoure les deux étoiles : de jour, sa lumière est ambrée, puis bleue — jamais les deux à la fois. Prenez le bleu directement sur la sphère et l’ambre dans une cellule de lumière remplie de jour ; les deux dans un mélangeur, le blanc vers le polissoir.`,"goal.twin_white.done":`Deux étoiles fondues en lumière blanche.`,"goal.twin_blue":`Fabriquez {n, plural, one {# lentille azur} other {# lentilles azur}} avec des machines`,"goal.twin_blue.why":`La lumière bleue n’existe qu’auprès de la seconde étoile : le banc optique doit se tenir à côté.`,"goal.twin_blue.hint":`L’étoile bleue est à 70 cases de l’ambrée. Bâtissez un avant-poste près d’elle, ou tirez un lumiduc : l’intensité baisse avec la distance.`,"goal.twin_blue.done":`La lumière bleue a atteint l’usine.`,"goal.twin_relic":`Tenez {n, plural, one {# spectre} other {# spectres}} par minute, même la nuit`,"goal.twin_relic.why":`Le gage des Jumeaux : la relique servira près du trou noir.`,"goal.twin_relic.hint":`Tous les spectres ensemble, au moins {n} par minute — même en fin de nuit, quand il n’y a plus d’étoiles. La lumière de la sphère change de couleur avec les étoiles ; les cellules de lumière tiennent la nuit.`,"goal.twin_relic.done":`La Relique des Jumeaux est obtenue et sauvegardée dans votre profil.`,"goal.veil_quartz":`Tirez {n} quartz du brouillard avec des machines`,"goal.veil_quartz.why":`Ici, pas de roche — sans quartz, ni lentilles ni spectres.`,"goal.veil_quartz.hint":`La glace (flèche) plus la lumière bleue dans un condenseur donnent de la lumière liquide ; un deuxième condenseur réglé sur « Quartz du brouillard » change glace et lumière liquide en quartz.`,"goal.veil_quartz.done":`Le quartz naît de la lumière.`,"goal.veil_lens":`Fabriquez {n, plural, one {# lentille} other {# lentilles}} avec des machines`,"goal.veil_lens.why":`Les lentilles sont la base de tout spectre ; il y en a désormais assez pour une usine.`,"goal.veil_lens.hint":`Posez les condenseurs en rangées : gravitapis et pinces marchent comme autour de la roche.`,"goal.veil_lens.done":`Les lignes avancent sans sol ferme.`,"goal.veil_relic":`Livrez {n, plural, one {# spectre} other {# spectres}} M et {n} K au Centre`,"goal.veil_relic.why":`Le gage du Voile : la relique servira près du trou noir.`,"goal.veil_relic.hint":`Les spectres se font comme ailleurs, seule la matière première vient du brouillard : un chalut dans la brume glacée, un condenseur, le brouillard en quartz. La lumière est plus rare ici.`,"goal.veil_relic.done":`La Relique du Voile est obtenue et sauvegardée dans votre profil.`,"goal.pulse_light":`Captez {n} ph/s de lumière avec des récepteurs`,"goal.pulse_light.why":`L’étoile est brillante, mais sa lumière arrive par pulsations ; reste à lui trouver un usage.`,"goal.pulse_light.hint":`La pulsation se voit dans les lumiducs sous forme de clignotement. Polissoirs et spectres M/K/G n’en ont cure : ils prennent n’importe quel rythme.`,"goal.pulse_light.done":`Le pulsar alimente l’usine.`,"goal.pulse_fa":`Livrez {n, plural, one {# spectre} other {# spectres}} F au Centre`,"goal.pulse_fa.why":`Le spectre F, c’est le rythme, et ici il vient tout seul : pas besoin de modulateur.`,"goal.pulse_fa.hint":`Une lumière verte pulsée : la sortie verte du prisme garde le rythme de l’étoile. L’assembleur F la prend telle quelle.`,"goal.pulse_fa.done":`Le rythme tout prêt — ça marche.`,"goal.pulse_relic":`Livrez {n} de chacun des spectres M, K et F au Centre`,"goal.pulse_relic.why":`Le gage du Pulsar : la relique servira près du trou noir.`,"goal.pulse_relic.hint":`Trois spectres au rythme du pulsar. Si la lumière se trouble, ne mélangez que des rayons de même rythme.`,"goal.pulse_relic.done":`La Relique du Pulsar est obtenue et sauvegardée dans votre profil.`,"stick.label":`Joystick de vol de la Sentinelle`,"keeper.recenter":`Vers la Sentinelle`,"toast.far":`Hors de portée de la Sentinelle — approche en cours`,"toast.farMining":`Extraction arrêtée : la Sentinelle est trop loin`,"guide.title":`Tutoriel`,"guide.skip":`Quitter le tutoriel`,"guide.skipStep":`Passer l’étape`,"guide.fly":`Volez jusqu’au repère près des roches bleues : touches WASD. La flèche au bord de l’écran montre le chemin.`,"guide.fly.touch":`Poussez le joystick vers le repère près des roches bleues. La flèche au bord de l’écran montre le chemin.`,"guide.fly.why":`N’approchez pas trop de l’étoile : le bouclier surchaufferait. J’ai besoin de vous en état de marche.`,"guide.mine":`Cliquez sur une roche bleue — le rayon de la vedette extraira le quartz tout seul. Il en faut {n}.`,"guide.mine.touch":`Touchez une roche bleue — le rayon de la vedette extraira le quartz tout seul. Il en faut {n}.`,"guide.mine.why":`À la main, c’est long, je sais. Les premières pierres se font toujours à la main, commandant. Les machines viendront après.`,"guide.lay-tunnel.touch":`Touchez le bord {o, select, 1 {supérieur} 2 {droit} 3 {inférieur} other {gauche}} du cadre et, sans lever le doigt, glissez vers {o, select, 1 {le bas} 2 {la gauche} 3 {le haut} other {la droite}} jusqu’au bout.`,"guide.place-grinder":`Posez le polissoir dans le cadre, à côté du récepteur.`,"guide.place-grinder.repick":`Prenez le polissoir dans la barre des bâtiments : il taille le quartz en lentilles.`,"guide.recipe":`Sélectionnez le polissoir et choisissez la recette « Lentille ».`,"guide.recipe.open":`Sélectionnez le polissoir pour ouvrir sa fenêtre.`,"guide.recipe.why":`La recette dit à la machine quoi fabriquer. Ici, les machines comprennent vite — pas comme la navigation.`,"guide.place-grabIn":`Posez une pince dans le cadre, entre le gravitapis et le polissoir.`,"guide.place-grabIn.rotate":`Tournez la pince, flèche vers {o, select, 1 {la gauche} 2 {le haut} 3 {la droite} other {le bas}} — vers le polissoir : « Pivoter » ou R, encore {n, plural, one {# fois} other {# fois}}.`,"guide.place-grabIn.repick":`Prenez une pince dans la barre des bâtiments : elle prend derrière et pose devant, dans le sens de sa flèche.`,"guide.place-grabOut":`La deuxième pince va dans le cadre {o, select, 1 {sous le polissoir} 2 {à gauche du polissoir} 3 {au-dessus du polissoir} other {à droite du polissoir}} : elle sortira les lentilles.`,"guide.place-grabOut.rotate":`Tournez la pince, flèche vers {o, select, 1 {le bas} 2 {la gauche} 3 {le haut} other {la droite}} — à l’opposé du polissoir : « Pivoter » ou R, encore {n, plural, one {# fois} other {# fois}}.`,"guide.place-grabOut.repick":`Prenez une autre pince.`,"guide.place-storage":`Posez la réserve — une caisse — dans le cadre, devant la flèche de la deuxième pince.`,"guide.place-storage.repick":`Prenez la réserve — une caisse pour les lentilles finies.`,"guide.lay-lights":`Prenez un lumiduc et tirez-le le long du cadre, du récepteur au polissoir.`,"guide.lay-lights.repick":`Prenez un lumiduc : il porte la lumière du récepteur à une machine.`,"guide.first-lens":`Regardez : le quartz vole, le polissoir travaille. Attendons la première lentille dans la caisse.`,"guide.first-lens.why":`Si une machine s’arrête, un badge apparaît au-dessus — sélectionnez-la, sa fenêtre dira ce qui cloche.`,"guide.done":`Tutoriel terminé ! La carte d’objectif en haut vous guide désormais.`,"guide.recipe.look":`Appuyez sur « Observer » (Esc) : un appui sur une machine l’ouvre alors au lieu de construire.`,"landmark.lab":`Épave du module`,"landmark.lab.sub":`l’« Hirondelle » · baie cryo et archives`,"landmark.star":`Étoile du Berceau`,"landmark.star.sub":`la source de lumière`,"intro.t0":`La lumière s’éteint`,"intro.p0":`Il y a plus de deux siècles, les humains ont appris à coudre l’espace avec des Hyperportails et ont relié trois cents étoiles. Puis les étoiles ont commencé à pâlir, l’une après l’autre. On l’a appelé l’Extinction : sans lumière, les portails s’éteignaient et les colonies se perdaient dans le noir.`,"intro.t1":`Vous êtes la Sentinelle`,"intro.t2":`La lumière, c’est la vie`,"intro.next":`Suivant`,"intro.skip":`Passer`,"compass.label":`Objectif hors écran, {n, plural, one {# case} other {# cases}}`,"compass.cells":`{n, plural, one {# case} other {# cases}}`,"menu.play":`Jouer`,"menu.replayGuide":`Refaire le tutoriel`,"lab.noteHow":`touchez — on vous montre comment l’obtenir`,"guide.place-grinder.why":`Le polissoir taille des lentilles dans le quartz. Tout ce que nous bâtirons aura besoin de lentilles.`,"guide.place-grabIn.why":`La pince prend sur le gravitapis et nourrit le polissoir. Un bras, mais sans coude.`,"tools.more":`Plus`,"tools.hideHud":`Masquer l’interface`,"hud.show":`Afficher l’interface`,"place.title":`Confirmer la pose`,"place.cancel":`Annuler`,"place.build":`Poser`,"place.remove":`Démolir`,"place.copy":`Copier`,"stick.hide":`Masquer le joystick`,"stick.show":`Afficher le joystick`,"stick.flip":`Joystick de l’autre côté`,"settings.stickSide":`Joystick de la Sentinelle`,"settings.stickSide.left":`À gauche`,"settings.stickSide.right":`À droite`,"settings.stickSide.off":`Masqué`,"settings.confirmPlace":`Pose en deux touchers`,"settings.confirmPlace.hint":`Un toucher montre un fantôme et le bouton « Poser » le confirme : votre doigt ne cache jamais l’endroit. Désactivez pour construire immédiatement.`,"settings.bigButtons":`Grands boutons`,"shell.worlds":`Mondes`,"shell.stars":`Constellation`,"shell.about":`À propos`,"shell.exit":`Quitter`,"shell.exit.title":`Quitter le jeu ?`,"shell.exit.text":`Votre monde est sauvegardé — vous reprendrez exactement là où vous en étiez.`,"shell.cancel":`Annuler`,"shell.playWorld":`Jouer : {name}`,"shell.rename":`Renommer`,"shell.delete":`Supprimer`,"shell.delete.title":`Supprimer le monde ?`,"shell.delete.text":`« {name} » et toutes ses sauvegardes disparaîtront pour de bon.`,"shell.deleted":`Monde supprimé`,"shell.timeH":`{h} h {m} min`,"shell.timeM":`{m} min`,"shell.loading":`Le monde s’éveille…`,"shell.loadFailed":`Impossible d’ouvrir la sauvegarde — le monde a été recommencé`,"shell.create.title":`Nouveau monde`,"shell.create.name":`Nom du monde`,"shell.create.randomName":`Nom aléatoire`,"shell.create.advanced":`Avancé`,"shell.create.tutorial":`Tutoriel pas à pas`,"shell.create.go":`Créer le monde`,"pause.title":`Menu`,"pause.resume":`Reprendre`,"pause.save":`Sauvegarder`,"pause.toTitle":`Au menu principal`,"world.name":`{a} sur {b}`,"world.a.0":`Vallée`,"world.a.1":`Rivage`,"world.a.2":`Confins`,"world.a.3":`Havre`,"world.a.4":`Demeure`,"world.a.5":`Dôme`,"world.a.6":`Ceinture`,"world.a.7":`Jardin`,"world.a.8":`Seuil`,"world.a.9":`Baie`,"world.b.0":`de l’Aube`,"world.b.1":`du Rayonnement`,"world.b.2":`des Reflets`,"world.b.3":`du Point du jour`,"world.b.4":`de Midi`,"world.b.5":`des Étincelles`,"world.b.6":`des Prismes`,"world.b.7":`de la Clarté`,"world.b.8":`du Spectre`,"world.b.9":`des Lueurs`,"tip.0":`Un prisme décompose la lumière blanche en couleurs — chaque couleur donne son propre spectre.`,"tip.1":`La caméra s’est égarée ? Le bouton viseur ou Espace la ramène à la Sentinelle.`,"tip.2":`Le Centre demande des spectres : chaque nouvelle classe ouvre le palier suivant de technologies.`,"tip.3":`L’Essaim ne surgit jamais par surprise : un bandeau avec minuteur et des anneaux autour du nid préviennent à l’avance.`,"tip.4":`La sphère de Dyson grandit par couches : fermez une enveloppe pour +{closed} % par arc ; besoin de plus de lumière ? Bâtissez l’enveloppe extérieure d’un grade supérieur.`,"tip.5":`Les ceintures tournent, les intérieures plus vite. Un harpon fixe exploite toute la ceinture — regardez-la s’éclaircir.`,"tip.6":`Les plans copient des zones entières — construisez une fois, posez partout.`,"tip.7":`Le mode Alt affiche le contenu des machines directement sur le terrain.`,"tip.8":`Une impasse ? L’objectif en haut suggère l’étape suivante, et la flèche montre où voler.`,"tip.9":`Les expériences sont de courts casse-têtes de lumière — les erreurs n’y coûtent rien.`,"tip.10":`Le monde se sauvegarde tout seul toutes les {sec} s et quand le jeu passe en arrière-plan.`,"tip.11":`Chaque étoile que vous allumez reste à jamais dans votre constellation.`,"boot.render":`Préparation de la toile…`,"boot.worlds":`Recherche de vos mondes…`,"boot.ready":`Prêt`,"about.idea":`Le jeu`,"about.idea.text":`Starwarden est une usine autour d’une étoile vivante. Bâtissez autour d’elle une sphère de Dyson, arc après arc, attrapez les roches des ceintures au harpon, fendez les comètes au faisceau, décomposez une lumière aux cinq propriétés et réunissez le spectre complet pour allumer une nouvelle étoile.`,"about.made":`Coulisses`,"about.made.text":`Les bâtiments, le vaisseau, les étoiles et l’Essaim sont rendus dans Blender et assemblés par des scripts ; les portraits des personnages ont été créés avec un modèle génératif, puis retravaillés par des scripts (éclairage, animation). Tout le son est synthétisé en temps réel : le jeu ne contient aucun fichier audio.`,"about.privacy":`Confidentialité`,"about.privacy.text":`Le jeu ne collecte et n’envoie aucune donnée. Les mondes et les réglages sont conservés uniquement sur votre appareil.`,"about.thanks":`Remerciements`,"about.thanks.text":`Aux testeurs des premières versions, pour leur honnête « je n’y comprends rien », qui a rendu le jeu plus clair.`,"gen.title":`Paramètres du monde`,"gen.preview":`Aperçu du système : étoile, ceintures, Centre, nid de l’Essaim`,"gen.preview.legend":`Centre au milieu · étoile avec couronne · cadres jaunes : première ligne · violet : nid de l’Essaim`,"gen.presets":`Préréglage du monde`,"gen.preset.classic":`Classique`,"gen.preset.plenty":`Abondance`,"gen.preset.scarce":`Pénurie`,"gen.preset.deep":`Espace lointain`,"gen.preset.custom":`Personnalisé`,"gen.preset.classic.desc":`L’équilibre voulu : ceintures normales, étoile brillante, l’Essaim en son temps.`,"gen.preset.plenty.desc":`Des ceintures riches et larges, plus de comètes, une étoile plus brillante, un Essaim plus calme, un kit généreux.`,"gen.preset.scarce.desc":`Des ceintures pauvres et étroites, des comètes rares, une étoile terne, un Essaim plus précoce. Chaque roche compte.`,"gen.preset.deep.desc":`Un système vaste : des ceintures éloignées les unes des autres mais plus riches, une étoile plus grosse. Il faudra voyager pour trouver la pierre.`,"gen.preset.custom.desc":`Vos propres valeurs : ouvrez les groupes ci-dessous. Le monde est toujours jouable jusqu’au bout : le générateur vérifie le départ.`,"gen.group.res":`Ceintures et comètes`,"gen.group.star":`Étoile`,"gen.group.dark":`Essaim`,"gen.group.kit":`Kit de départ`,"gen.knob.star_power":`Luminosité`,"gen.knob.dark_freq":`Fréquence des nids`,"gen.knob.dark_delay":`Sensibilité des nids`,"gen.kit.0":`Modeste`,"gen.kit.1":`Normal`,"gen.kit.2":`Généreux`,"gen.code":`Code du monde`,"gen.code.copy":`Copier le code du monde`,"gen.code.copied":`Code du monde copié — partagez-le`,"gen.code.bad":`Code non reconnu. Collez une chaîne du type PHW1-…`,"gen.reset":`Revenir au Classique`,"gen.hint.star_power":`Luminosité de l’étoile : une étoile terne donne moins à la sphère, et les enveloppes extérieures atteignent plus tôt leur plafond.`,"gen.hint.dark_freq":`Nombre de nids de l’Essaim ; le premier nid existe toujours, car le finale en a besoin.`,"gen.hint.dark_delay":`À partir de quel éblouissement les nids s’éveillent : ×2, deux fois plus de lumière ; ×0,5, la moitié suffit.`,"etude.crossed_filters.name":`Filtres croisés`,"etude.crossed_filters.task":`La lumière source est polarisée à 0°, le récepteur ne prend que le 90°. Une lame à 90° bloque tout, mais si l’on en glisse une autre entre les deux ? Livrez {n} ph (réglez l’angle dans la fenêtre du polariseur).`,"etude.phase_cancel.name":`Phase π`,"etude.phase_cancel.task":`Deux sources bleues en opposition de phase ; le récepteur ne prend que la phase π. Réunies telles quelles dans un interféromètre, elles s’annulent. Additionnez les deux flux et livrez {n, number} ph.`,"etude.light_gates.name":`Portes de lumière`,"etude.light_gates.task":`Les signaux A (rouge) et B (vert) clignotent. Le récepteur du haut ne compte la lumière blanche que sur « A et B », celui du bas sur « A ou B, mais pas les deux ». Une lumière longue au mauvais moment remet son compte à zéro. Livrez {n} ph avec des obturateurs (commandés par les côtés) et un interféromètre.`,"cfg.title.level_gate":`Mode du capteur de niveau`,"cfg.level_gate.0":`Ouvert tant que le voisin n’est pas plein (< {full} %)`,"cfg.level_gate.1":`Ouvert tant que le voisin n’est pas vide (> {empty} %)`,"goal.twin_cell":`Posez {n, plural, one {# cellule de lumière} other {# cellules de lumière}}`,"goal.twin_cell.why":`Les Jumeaux ont des nuits : {night} s sans étoiles.`,"goal.twin_cell.hint":`Ici, un jour dure {day} minutes : l’étoile ambrée brille {amber} s, la bleue {blue} s, puis viennent {night} s de nuit. La chronologie se trouve dans le panneau Jour, sous l’objectif. Une cellule de lumière stocke la lumière le jour et la rend la nuit : la lumière entre par l’arrière et sort par l’avant. Elle retient la première couleur reçue et n’en accepte aucune autre. Un lumiduc porte jusqu’à {flux} ph/s : une seule ligne alimente 5 fabricants.`,"goal.twin_cell.done":`Les cellules sont en place. Il reste à traverser la nuit.`,"goal.twin_night":`Gardez {n, plural, one {# fabricant} other {# fabricants}} allumé jusqu’à l’aube`,"goal.twin_night.why":`Une usine qui ne dort jamais.`,"goal.twin_night.hint":`Quand les deux étoiles se couchent, la lumière ne vit plus que dans les cellules. Le panneau Jour indique combien de secondes tiendra la réserve de chaque couleur ; l’objectif compte si les machines sont encore allumées à la fin de la nuit.`,"goal.twin_night.done":`La nuit est passée — l’usine a brillé sans étoiles.`,"toast.dusk":`Nuit : les deux étoiles sont couchées pour {night} s, la lumière n’est plus que dans les cellules`,"toast.dawn":`Aube : l’étoile ambrée s’est levée`,"lab.filter":`Filtre de l’arbre`,"lab.filter.open":`Disponibles · {n}`,"lab.filter.all":`Toutes · {n}`,"lab.filter.done":`Recherchées · {n}`,"lab.filter.empty":`Rien ici — choisissez un autre filtre ou une autre branche.`,"lab.branch":`Branche de l’arbre`,"tech.level":`niv. {n}`,"tech.time":`{s} s l’unité`,"branch.any":`Toutes les branches`,"branch.mining":`Extraction`,"branch.logistics":`Logistique`,"branch.light":`Lumière`,"branch.matter":`Matière`,"branch.resonance":`Résonance`,"branch.logic":`Logique`,"branch.defense":`Défense`,"branch.stars":`Étoiles`,"branch.finale":`Finale`,"bonus.grabber":`+{v} % de vitesse des pinces`,"bonus.research":`+{v} % de vitesse du Centre`,"bonus.hand":`+{v} % de travail manuel`,"bonus.spear":`+{v} % de rechargement des lances`,"bonus.glare":`−{v} % d’éblouissement`,"bonus.drone":`+{v} % de vitesse et de fret des drones`,"bonus.cool":`+{v} % de refroidissement des radiateurs`,"bonus.forge":`+{v} % de vitesse de la Forge`,"bonus.speed":`+{v} % de vitesse des machines`,"bonus.attenuation":`lumiducs : −1 d’intensité toutes les {n} cases`,"bonus.tunnel":`plis jusqu’à {n} cases`,"bonus.swift":`drones rapides`,"bonus.perLevel":`{one} par niveau · total {total} %`,"lock.goto":`Voir dans le Centre`,"goal.research":`Fabriquez {n, plural, one {# Reflet} other {# Reflets}} et recherchez le Prisme`,"goal.research.hint":`Le Centre a besoin de lumière\xA0: un lumiduc depuis la ligne vers n’importe lequel de ses côtés. Un polissoir à part avec la recette «\xA0Reflet\xA0» (quartz + plaque)\xA0: «\xA0Poser\xA0» quartz et plaques dans sa fenêtre, «\xA0Prendre\xA0» le résultat. Dans la fenêtre «\xA0Recherches\xA0», au Centre — «\xA0Remettre ici\xA0»\xA0; Prisme — «\xA0Ajouter\xA0». Ne touchez pas à la ligne de lentilles. Plus tard, une ligne vous libère les mains\xA0: une pince du polissoir à Reflets directement dans le Centre.`,"goal.research.why":`Les archives des « Semailles » ne s’ouvrent pas d’un coup : le Centre de recherche lit les Reflets — la science — et débloque les machines une à une.`,"goal.research.done":`Le Centre a lu son premier Reflet. Prisme débloqué : les archives des « Semailles » commencent à s’ouvrir.`,"bp.locked":`Bâtiments verrouillés : {n} — le collage les ignorera`,"tree.title":`Arbre des technologies`,"tree.count":`{n} sur {all} recherchées`,"tree.fit":`Voir tout l’arbre`,"tree.queue":`File du Centre`,"tree.path":`Rechercher le chemin · {n}`,"tree.open":`Arbre entier`,"lock.gotoTree":`Voir dans l’arbre`,"key.tree":`Arbre des technologies`,"tree.filter.all":`Toutes`,"tree.filter.open":`Disponibles`,"tree.filter.done":`Recherchées`,"tree.search":`Chercher une technologie`,"tree.mini":`Mini-carte : touchez pour y aller`,"guide.tree":`Appuyez sur « Arbre entier » : la carte de toutes les découvertes, du Prisme jusqu’au finale.`,"guide.tree.why":`C’est la carte du chemin. Il est long, mais il est tracé. « Rechercher le chemin », et le Centre met tout en file de lui-même.`,"guide.tree.reopen":`Rouvrez le Centre : le bouton « Arbre entier » s’y trouve.`,"tree.queueFull":`{now} partent en file maintenant, les {n} autres suivront à mesure que les recherches se terminent.`,"tree.goal":`But du chemin : le Centre remplit sa file tout seul.`,"tree.gate":`Palier {spectrum} — débloqué par « {tech} »`,"tree.next":`Étape suivante :`,"tree.band":`palier · {stage}`,"settings.uiScale.capped":`Cet écran utilise {n} % — plus grand ne tient pas.`,"status.23":`Mauvaise ceinture`,"status.23.hint":`Un harpon prend la roche (quartz, obsidienne), un chalut prend la poussière (givre, glace, antilumière). Utilisez l’autre récolteur.`,"status.24":`Ceinture qui s’épuise`,"status.24.hint":`Il reste moins d’un quart de la ceinture. Il est temps de bâtir à la ceinture suivante, plus riche.`,"status.25":`Ceinture épuisée`,"status.25.hint":`Plus de roche : déplacez le récolteur vers une autre ceinture.`,"machine.belt":`Reste de la ceinture : {n} %`,"machine.noBelt":`Aucune ceinture à portée`,"cfg.role.3":`Collecte`,"shield.label":`Bouclier`,"shield.aria":`Bouclier de la Sentinelle : {n} %`,"toast.heatWarm":`Chaleur : le bouclier ne se régénère pas ici. Plus près de la couronne, il subit des dégâts.`,"toast.heatLow":`Bouclier faible — éloignez-vous de l’étoile !`,"toast.heatEject":`Le vent stellaire a rejeté la Sentinelle en arrière. Rien n’a été perdu.`,"goal.harpoon":`Posez {n, plural, one {# harpon} other {# harpons}} près des roches bleues`,"goal.harpoon.hint":`Barre de construction → harpon → l’emplacement au repère, tout contre la ceinture. Le point lumineux et la goulotte sont la sortie ; « Pivoter » (R) l’oriente vers le gravitapis. {n, plural, one {# harpon suffit} other {# harpons suffisent}} pour un polissoir.`,"goal.harpoon.why":`Impossible de charrier la pierre à la main : les dormeurs ont besoin de lumière dans des heures, pas des semaines. Un harpon attrape les roches tout seul.`,"goal.harpoon.done":`Harpons tirés. La pierre viendra d’elle-même : vos mains sont libres, et mes calculs aussi.`,"goal.colors":`Décomposez la lumière en couleurs`,"goal.colors.hint":`Prisme : blanc à l’arrière → rouge devant, émeraude à gauche, azur à droite. Posez des lentilles sur un banc optique sous une lumière colorée.`,"goal.colors.why":`La lumière blanche, c’est toutes les couleurs à la fois. Les archives lisent la lumière par couleurs, et avec les couleurs l’usine fera presque tout — y compris une défense contre l’Essaim.`,"goal.colors.done":`La lumière est décomposée en couleurs : le Centre peut les lire.`,"goal.ice":`Récupérez {n} × glace sur les météorites`,"goal.ice.why":`Les capsules ont besoin de froid, et ici, le froid, c’est la glace. Elle vient de l’espace : des météorites glacées et des comètes traversent le système.`,"goal.ice.hint":`Les météorites sont des roches brillantes qui traversent le système ; la flèche indique la plus proche qui se dirige vers votre base. Touchez-la : la vedette arrive et son faisceau fend la roche. Traversez les éclats : la glace se ramasse toute seule. Plus tard, une lance sur lumière focalisée fendra les météorites à votre place.`,"goal.ice.done":`De la glace dans la soute. Plus tard, les lances et les drones l’attraperont pour vous.`,"goal.deep_signal":`Envoyez le Signal profond`,"goal.deep_signal.why":`L’étoile a clignoté deux secondes après le premier spectre. Coïncidence ? Le Signal profond décomposera sa lumière jusqu’aux raies les plus ténues.`,"goal.deep_signal.hint":`Signal profond : chaque unité de son coût est un spectre M, K et G (le décompte est dans la fenêtre du Centre). K est le plus lent : ajoutez un second assembleur K.`,"goal.deep_signal.done":`Le signal est parti ! Le Centre brûle de trois anneaux.`,"goal.awakening":`Recherchez la « Fibre longue » — un lien avec le Havre`,"goal.awakening.why":`La Fibre longue perce un lien à travers l’Envers : pour la première fois, un canal dégagé vers le Havre. Et une route vers d’autres étoiles.`,"goal.awakening.hint":`Il faut les six spectres : le chemin vers la Fibre longue passe par toutes les classes, et elle-même coûte des spectres F, A et B. Ensuite, les lumiducs faiblissent moins souvent.`,"goal.awakening.done":`La fibre est tirée : le Havre captera l’« Hirondelle ». D’autres étoiles attendent.`,"goal.ridge_awakening":`L’anneau de la Crête est ouvert`,"goal.ridge_awakening.why":`Un anneau ouvert tient la route dans les deux sens — et porte le motif du jardin de la Crête.`,"goal.ridge_awakening.hint":`Il s’ouvrira tout seul — par le consentement du jardin ou par la clé forcée.`,"goal.ridge_awakening.done":`L’anneau de la Crête est ouvert. En lui — le motif de naissance.`,"achv.deep_signal.name":`Signal profond`,"achv.deep_signal.desc":`Le spectrographe a trouvé dans la lumière de l’étoile des répétitions que les étoiles ne font pas.`,"landmark.ring.quartz_rock":`pierre pour les lentilles`,"landmark.ring.obsidian_rock":`pierre pour les plaques`,"landmark.ring.ice_haze":`glace fine — au chalut`,"landmark.ring.frost_dust":`givre — au chalut`,"gen.knob.belt_rich":`Réserves des ceintures`,"gen.knob.belt_width":`Largeur des ceintures`,"gen.knob.belt_spread":`Étendue du système`,"gen.knob.meteor_rate":`Météorites et comètes`,"gen.knob.star_size":`Taille de l’étoile`,"gen.hint.belt_rich":`Quantité de pierre que contient chaque ceinture : ×2 dure deux fois plus longtemps.`,"gen.hint.belt_spread":`Ceintures plus éloignées : de plus larges intervalles pour la base, des routes plus longues.`,"gen.hint.meteor_rate":`Fréquence des corps glacés qui traversent : plus de passages, plus de glace.`,"gen.hint.star_size":`Une étoile plus grosse est plus brillante et repousse les ceintures vers l’extérieur.`,"guide.place-harpoonA":`Posez un harpon dans le cadre, près de la ceinture. Le point brillant et la goulotte sont sa sortie : les roches y vont.`,"guide.place-harpoonA.rotate":`Tournez le harpon pour que sa sortie soit {o, select, 1 {à gauche} 2 {en haut} 3 {à droite} other {en bas}} : appuyez sur « Pivoter » ou sur R {n, plural, one {# fois de plus} other {# fois de plus}}.`,"guide.place-harpoonA.repick":`Prenez un harpon dans la barre de construction : il attrape tout seul les roches de la ceinture.`,"guide.place-harpoonA.why":`Ce harpon s’est détaché de la pince d’amarrage. Il attrape les roches tout seul : vos mains restent libres.`,"guide.place-harpoonB":`Le second harpon va dans le cadre voisin, sortie dans le même sens.`,"guide.place-harpoonB.rotate":`Tournez le harpon pour que sa sortie soit {o, select, 1 {à gauche} 2 {en haut} 3 {à droite} other {en bas}} : « Pivoter » ou R {n, plural, one {# fois de plus} other {# fois de plus}}.`,"guide.place-harpoonB.repick":`Prenez un autre harpon dans la barre des bâtiments.`,"shell.legacy":`{name} — monde d’une très ancienne version, non pris en charge`,"shell.legacy.note":`Monde d’une très ancienne version (avant les ceintures et les spectres) — non pris en charge. Vous pouvez le supprimer et en commencer un nouveau.`,"bonus.harvest":`+{v} % de vitesse des extracteurs`,"bonus.meteor":`+{v} % de météorites et comètes`,"hover.left":`Ceinture : il reste {n} % de la roche. La ceinture tourne : un harpon travaille toute la ceinture.`,"gen.code.legacy":`Ce code de monde vient d’une version plus ancienne et n’est pas pris en charge : le jeu compte désormais des ceintures et des spectres.`,"goal.far_belt":`Nouvelle ceinture : des harpons sur une troisième ceinture`,"goal.far_belt.why":`Une colonie, c’est des années, et la ceinture intérieure s’amenuise. Les ceintures lointaines sont plus riches : l’usine ne s’arrêtera pas quand la plus proche sera épuisée.`,"goal.far_belt.hint":`Rejoignez la ceinture rocheuse suivante, au-delà de celle d’obsidienne, et posez un harpon sur son bord : il compte dès qu’il commence à extraire. Les ceintures proches s’amenuisent ; plus tard, déplacez-vous : harpons et polissoir près de la ceinture lointaine, lentilles dans une réserve, puis un gravitapis jusqu’à la base. Le stock restant de la ceinture s’affiche dans l’infobulle du harpon.`,"goal.far_belt.done":`Trois ceintures en service : quand l’intérieure s’épuisera, l’usine ne s’arrêtera pas.`,"goal.fold":`Recherchez les plis et faites passer cargaison ou lumière sous un obstacle`,"goal.fold.why":`La base grandit et les lignes se heurtent. Un pli de l’espace fait passer cargaison et lumière sous un obstacle : {s1} cases au début, puis le Centre ouvre {s2}, {s3} et {s4}.`,"goal.fold.hint":`Recherchez « Plis » au Centre (spectre M). Pli : la première arche est l’entrée, la suivante sur la ligne est la sortie (posée automatiquement) ; un pli fait aussi passer la cargaison au-delà d’une ceinture d’astéroïdes. Le pli lumineux est une recherche à part : deux arches face à face. Un faisceau survole déjà gravitapis et ceintures, en perdant {loss} % par case au-dessus d’un gravitapis, mais ne traverse les machines que par un pli.`,"goal.fold.done":`La ligne a plongé et elle est ressortie ! Comme un point de couture. Je peux la dessiner dans mon carnet ?`,"guide.lay-tunnel":`Cliquez sur l’extrémité {o, select, 1 {haute} 2 {droite} 3 {basse} other {gauche}} du cadre et tirez le gravitapis {o, select, 1 {vers le bas} 2 {vers la gauche} 3 {vers le haut} other {vers la droite}} jusqu’au bout.`,"guide.lay-tunnel.repick":`Prenez un gravitapis dans la barre de construction : il transporte les roches.`,"guide.lay-tunnel.reverse":`Le gravitapis va dans le mauvais sens. Appuyez sur « Annuler » et retracez-le, depuis le bord du cadre, côté harpons.`,"guide.lay-tunnel.why":`Le gravitapis transportera tout seul les roches des harpons.`,"status.26":`Pas de rayon`,"status.26.hint":`Le faisceau de la sphère n’arrive pas : posez un arc sur l’enveloppe la plus proche (orbite en pointillés près de l’étoile) ou rapprochez le récepteur, à moins de {range} cases d’une orbite portant des arcs.`,"status.27":`Roches trop loin`,"status.27.hint":`La ceinture est épuisée à cet endroit et tourne lentement. Posez le récolteur ailleurs le long de la ceinture.`,"status.28":`Enveloppe achevée`,"status.28.hint":`Tous les emplacements de l’enveloppe de ce rang sont pris. Retirez les arcs restants avec « Prendre » et chargez des arcs du rang suivant, pour l’enveloppe extérieure.`,"guide.place-arc":`Prenez « Arc I » dans la barre du bas et appuyez sur l’anneau en pointillés dans le cadre. Inutile de vous approcher.`,"guide.place-arc.repick":`Prenez « Arc I » dans la barre de construction, en bas.`,"guide.place-arc.why":`Un arc capte la lumière de l’étoile. Un seul donne {arc} ph/s. Quarante dormeurs, c’est beaucoup d’arcs. Commençons par un.`,"guide.place-receiver":`Posez le récepteur de faisceau, la parabole, dans le cadre. L’arc lui enverra un faisceau.`,"guide.place-receiver.repick":`Prenez le récepteur dans la barre des bâtiments.`,"guide.place-receiver.why":`Le récepteur est la prise de la base. La lumière en part vers les machines.`,"goal.arc":`Lancez un arc sur l’anneau près de l’étoile`,"goal.arc.hint":`Barre de construction → « Arc I » → {touch, select, yes {touchez} other {cliquez sur}} l’anneau en pointillés lumineux près de l’étoile (l’orbite des arcs). Inutile de vous approcher : la vedette lance un arc à {reach} cases.`,"goal.arc.why":`Les panneaux de secours ne dureront pas. Un arc capte la lumière du Berceau — la première lumière qui travaille pour l’« Hirondelle » au lieu d’épuiser sa réserve.`,"goal.arc.done":`L’arc est dans le cadre. Cette étoile ne figure dans aucun catalogue, mais elle est généreuse en lumière. Je prends.`,"goal.catapult":`Catapulte : les arcs volent seuls`,"goal.catapult.hint":`Recherchez « Catapulte » au Centre (spectre M) et posez-la dans un intervalle. Les arcs entrent dans la catapulte elle-même (par une pince ou « Poser » dans sa fenêtre), la lumière par un lumiduc ; elle les tire vers les emplacements libres de l’enveloppe. Une pince longue passe par-dessus une case : le gravitapis n’a donc pas besoin de la toucher.`,"goal.catapult.why":`Les dormeurs et le futur portail ont besoin d’une sphère de centaines d’arcs. Impossible de l’assembler à la main : la catapulte lance les arcs toute seule.`,"goal.catapult.done":`Le premier arc est en vol : la sphère se bâtit toute seule.`,"goal.crown":`Fermez l’anneau d’arcs autour de l’étoile`,"goal.crown.hint":`L’enveloppe I près de la couronne compte {slots} emplacements. Une enveloppe fermée donne +{closed} % à chaque arc et s’embrase en un anneau entier. Toute la Couronne fait {total} ph/s : {rx, plural, one {# récepteur} many {# récepteurs} other {# récepteurs}} de {cap}.`,"goal.crown.why":`Un anneau d’arcs fermé, c’est la Couronne, la première enveloppe. Sa lumière suffit à faire passer les capsules des panneaux de secours à la lumière de la base.`,"goal.crown.done":`La Couronne est fermée ! Chaque arc brille de {closed} % de plus.`,"goal.shell2":`Enveloppe II : {n, plural, one {# arc} many {# arcs} other {# arcs}} de second palier`,"goal.shell2.hint":`Recherchez « Enveloppe II » (spectre K). L’Arc II s’assemble avec une lentille ambre, des lentilles et des plaques ; son orbite se trouve au bord extérieur de l’intervalle du Centre. Une enveloppe extérieure capte la lumière que laisse passer l’intérieure.`,"goal.shell2.why":`La Couronne manque de lumière pour les spectres K, et la liaison avec le Havre manque de puissance. Une nouvelle enveloppe autour de l’ancienne donnera l’un et l’autre.`,"goal.shell2.done":`La deuxième enveloppe grandit — la base a plus de lumière.`,"goal.captured":`Étoile dans la sphère : {pct} % de sa luminosité`,"goal.captured.hint":`Toutes les enveloppes ensemble prennent une part de la luminosité de l’étoile. Les enveloppes III et IV se trouvent près des ceintures lointaines ; une sphère complète prend {n} %.`,"goal.captured.why":`La part de la lumière du Berceau qui travaille déjà pour vous — et pour le futur portail. Le portail aura besoin de presque toute l’étoile.`,"goal.captured.done":`{pct} % de l’étoile est dans votre sphère.`,"hover.shell.name":`Enveloppe {n} de la sphère de Dyson`,"hover.shell.arcs":`Arcs {built} sur {n} · {flux} ph/s chacun`,"hover.shell.star":`Étoile dans la sphère : {p} %`,"hover.shell.hint":`Lancez un Arc {n} sur l’orbite en pointillés ; une enveloppe fermée donne +{closed} % à chaque arc.`,"landmark.shell":`Enveloppe {n}`,"landmark.shell.sub":`{built} arcs sur {n}`,"achv.crown_closed.name":`La Couronne`,"achv.crown_closed.desc":`Fermez l’enveloppe I de la sphère de Dyson : un anneau de lumière autour de l’étoile.`,"achv.half_star.name":`Une demi-étoile`,"achv.half_star.desc":`La sphère capte la moitié de la luminosité de l’étoile.`,"achv.whole_star.name":`L’étoile entière`,"achv.whole_star.desc":`La sphère de Dyson prend {pct} % de la luminosité de l’étoile.`,"launcher.put":`Charger : {name}`,"hover.shell.got":`Les récepteurs prennent {got} des {power} ph/s de la sphère`,"hover.shell.lost":`Les récepteurs ne prennent que {got} sur {power} ph/s : ajoutez un récepteur ({cap} ph/s)`,"lab.sphere":`Étoile dans la sphère : {p} % · {arcs} arcs`,"goal.more":`Comment ? Touchez`,"goal.less":`Replier`,"goal.part.research":`Recherchez « {name} » au Centre`,"goal.part.deliver":`Livrez au Centre : {name}`,"goal.part.auto":`Produisez avec des machines : {name}`,"goal.part.make":`Récoltez : {name}`,"goal.part.build":`Posez : {name}`,"goal.beam.part":`Un rayon atteint un port récepteur`,"goal.resonance.part":`Harpons en résonance`,"goal.fold.part":`Du fret ou de la lumière passe par un pli`,"goal.shell2.part":`Arcs sur l’enveloppe II`,"goal.liquid.part":`Lumière liquide produite, en unités`,"goal.cooling.part":`Récepteurs près de l’étoile sans surchauffe`,"goal.drone.part":`Premier trajet d’un drone`,"goal.logic.part":`Basculements de l’obturateur`,"goal.spear.part":`Lance chargée`,"compass.fly":`Aller à l’objectif`,"place.why.busy":`Occupé`,"place.why.belt":`Ceinture — construction impossible`,"place.why.orbit":`Orbite de la sphère — arcs seulement`,"place.why.corona":`Couronne de l’étoile`,"place.why.far":`Trop loin — touchez encore`,"place.why.items":`Absent de l’inventaire`,"place.why.slot":`Un arc se pose seulement sur les pointillés d’une enveloppe`,"place.why.grade":`Mauvaise enveloppe — il faut un arc d’un autre rang`,"hint.lab.5":`Choisissez une technologie dans la fenêtre du Centre ou dans l’arbre : le Centre ne démarre pas tout seul.`,"machine.putAll":`Tout poser : {item}`,"status.lowLight":`Peu de lumière`,"status.lowLight.hint":`Tourne plus lentement que la recette : il arrive moins de lumière qu’un cycle n’en demande. Ajoutez des arcs et des récepteurs, ou mettez moins de machines sur ce lumiduc.`,"machine.inflow":`Apport {n} ph/s → cycle {s} s`,"machine.noInflow":`Apport 0 ph/s — aucune lumière n’arrive`,"status.7.dry":`Aucune lumière n’arrive : tirez un lumiduc jusqu’à la machine, depuis un récepteur de faisceau ou une sortie de prisme. La lumière ne passe pas entre des machines qui se touchent. Si un lumiduc est là, son réseau n’a pas de source ou d’autres machines prennent toute la lumière : le plus souvent, un prisme aux sorties libres.`,"status.prism.3":`Consommateurs pleins — la lumière attend`,"status.mixer.3":`Nulle part où envoyer la lumière`,"hint.mixer.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.focuser.3":`Nulle part où envoyer la lumière`,"hint.focuser.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.receiver.3":`Nulle part où envoyer la lumière`,"hint.receiver.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.modulator.3":`Nulle part où envoyer la lumière`,"hint.modulator.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.polarizer.3":`Nulle part où envoyer la lumière`,"hint.polarizer.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.phaser.3":`Nulle part où envoyer la lumière`,"hint.phaser.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.interferometer.3":`Nulle part où envoyer la lumière`,"hint.interferometer.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.light_cell.3":`Nulle part où envoyer la lumière`,"hint.light_cell.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.port.3":`Nulle part où envoyer la lumière`,"hint.port.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"hud.glareFrom":`{name} — {v} ph/s`,"lab.choose":`Choisissez une technologie`,"machine.inflowOnly":`Apport {n} ph/s`,"machine.bufferFull":`Tampon de lumière plein — en attente d’entrée`,"inv.toHand":`En main — poser`,"toast.firstCrack":`Météorite fendue ! Traversez les éclats : la glace se ramasse toute seule (ou touchez un éclat).`,"machine.spearMeteor":`Pas d’Essaim à proximité : fend les météorites à moins de {r} cases (toutes les {every} s). Fendues dans cette partie : {n}`,"card.fromBelt":`Ceinture d’astéroïdes : le rayon de la vedette (touchez un rocher) ou un harpon près de la bande de la ceinture.`,"card.fromTrawl":`Ceinture fine : un chalut près de la bande de la ceinture.`,"place.why.planet":`Orbite d’une planète — elle passera ici`,"status.29":`Planète trop loin`,"status.29.hint":`La planète est hors de la fenêtre de l’accélérateur de masse : attendez qu’elle se rapproche ou utilisez des navettes. La fenêtre est l’arc éclairé de l’orbite.`,"status.30":`Pas de station`,"status.30.hint":`Posez d’abord une station orbitale sur la planète : lancez-la avec la Sentinelle ou depuis un pas de tir.`,"status.31":`Planète pleine`,"status.31.hint":`Tous les emplacements de la planète sont pris (ou la station et l’accélérateur y sont déjà). Choisissez une autre planète.`,"status.32":`Choisissez une planète`,"status.32.hint":`Choisissez une planète explorée dans la fenêtre de la machine. Un observatoire ou un survol de la Sentinelle explore les nouvelles.`,"status.33":`Mauvaise planète`,"status.33.hint":`Les foreuses-sondes se posent sur les planètes solides, les siphons sur celles à atmosphère ; l’accélérateur de masse ne se pose que par fusée.`,"status.34":`Pas d’accélérateur`,"status.34.hint":`Lancez un accélérateur de masse vers la planète depuis un pas de tir.`,"bonus.planet":`+{v} % de cadence des foreuses-sondes et siphons`,"bonus.shuttle":`+{v} % de vitesse et de fret des navettes`,"bonus.driver":`+{v} % de fenêtre de l’accélérateur`,"branch.planets":`Planètes`,"planets.title":`Planètes`,"planets.empty":`Cette étoile n’a pas de planètes.`,"planet.unknown":`Inexplorée`,"planet.hours":`{h} h {m} min`,"planet.min":`{n} min`,"planet.cells":`{n, plural, one {# case} other {# cases}}`,"planet.orbit":`Orbite`,"planet.orbitVal":`{r} cases · {time} par orbite`,"planet.dist":`Vers la Sentinelle`,"planet.atmo":`Atmosphère`,"planet.atmo.thick":`dense`,"planet.atmo.thin":`ténue`,"planet.atmo.trace":`traces`,"planet.none":`néant`,"planet.rings":`Anneaux`,"planet.ring.ice":`glacés`,"planet.ring.rock":`rocheux`,"planet.moons":`Lunes`,"planet.stock":`Réserve`,"planet.kind.lava":`Monde de lave`,"planet.kind.rocky":`Monde rocheux`,"planet.kind.desert":`Monde désertique`,"planet.kind.crystal":`Monde cristallin`,"planet.kind.ocean":`Monde océanique`,"planet.kind.cloud":`Monde nuageux`,"planet.kind.ice":`Monde glacé`,"planet.kind.ice_giant":`Géante de glace`,"planet.kind.gas_giant":`Géante gazeuse`,"planet.special.tidal":`déchirée par les marées`,"planet.special.aurora":`aurores`,"planet.unsurveyed":`Inexplorée : approchez-vous à moins de {survey} cases ou construisez un observatoire.`,"planet.slots":`Emplacements`,"planet.slotFree":`libre`,"planet.mod.1":`Station orbitale`,"planet.mod.2":`Foreuse-sonde`,"planet.mod.3":`Siphon atmosphérique`,"planet.mod.4":`Accélérateur de masse`,"planet.store":`Entrepôt de la station`,"planet.needStation":`Sans station, les modules ne marchent pas — lancez-la en premier.`,"planet.window":`Fenêtre de l’accélérateur dans {time}`,"planet.fly":`Y aller`,"planet.here":`Ici`,"planet.take":`Prendre {n}`,"planet.throw.hint":`La Sentinelle lance un module depuis {reach} cases du bord de la planète`,"planet.throw.station":`Station`,"planet.throw.lander":`Foreuse`,"planet.throw.siphon":`Siphon`,"planet.why.far":`Approchez — à {reach} cases du bord`,"planet.why.none":`Absent de l’inventaire — fabriquez-le`,"planet.why.locked":`Recherchez d’abord la technologie`,"planet.why.full":`Tous les emplacements de la planète sont pris`,"planet.why.station":`Une station est déjà là`,"planet.why.noStation":`D’abord la station`,"planet.why.wrong":`Pas pour cette planète`,"planet.how.tektite":`Tectite : une station plus des foreuses-sondes. Transportez-la par navette ou attrapez-la avec un accélérateur de masse.`,"planet.how.neon":`Néon : une station plus des siphons. Transportez-le par navette ou attrapez-le avec un accélérateur de masse.`,"planet.how.ice":`Glace : une station plus des foreuses-sondes, un approvisionnement en glace pour une mégabase.`,"cfg.title.launch_pad":`Planète cible`,"cfg.title.shuttle_port":`Destination des navettes`,"cfg.title.catcher":`Planète de l’accélérateur`,"cfg.title.neon_emitter":`Couleur de la lumière`,"cfg.neon_emitter.0":`Rouge`,"cfg.neon_emitter.1":`Émeraude`,"cfg.neon_emitter.2":`Azur`,"cfg.planetAuto":`Auto`,"cfg.planetNone":`Aucune`,"shuttle.home":`Navettes au port : {n} · en vol : {f}`,"shuttle.put":`Poser des navettes`,"observatory.target":`Exploration : {name} — {n} %`,"observatory.done":`Toutes les planètes explorées`,"goal.planet_seen":`Explorez une planète`,"goal.planet_seen.why":`Les dormeurs et les neuf mille de l’« Exode » ont besoin de terre, et le Berceau a ses propres mondes. Les planètes contiennent ce que les ceintures n’ont pas : tectite et néon.`,"goal.planet_seen.hint":`Touchez la flèche : votre vedette file vers la planète la plus proche. À moins de {survey} cases, elle est explorée automatiquement ; ou construisez un observatoire.`,"goal.planet_seen.done":`Planète explorée : le type, la ressource et les emplacements figurent sur sa fiche.`,"goal.planet_seen.part":`Explorez une planète`,"goal.planet_landing":`Atterrissage : une station et une foreuse-sonde`,"goal.planet_landing.why":`Une station orbitale est le premier quai de la colonie près d’une terre vivante. La foreuse extrait la tectite vers son entrepôt.`,"goal.planet_landing.hint":`Fabriquez une station et une foreuse-sonde, rejoignez une planète solide (rocheuse, de lave, désertique, cristalline), touchez-la : Station, puis Foreuse.`,"goal.planet_landing.done":`Premier atterrissage ! L’entrepôt de la station se remplit.`,"goal.planet_landing.part":`Posez une station`,"goal.planet_landing.part.2":`Posez une foreuse-sonde`,"goal.planet_tektite":`Verre de tectite : {n}`,"goal.planet_tektite.why":`Le verre de tectite, c’est l’optique des rangs supérieurs : tubes, navettes, collecteur. Sans lui, le portail reste hors d’atteinte.`,"goal.planet_tektite.hint":`Prenez la tectite à la station (Prendre, sur la fiche de la planète), rapportez-la chez vous et faites-la fondre dans un four à tectite sous lumière rouge.`,"goal.planet_tektite.done":`Du verre venu d’une planète ! La première chose qu’on fabrique avec de la vraie terre. Au Havre, la terre n’existe qu’en images.`,"goal.planet_shuttle":`Premier trajet d’une navette`,"goal.planet_shuttle.why":`Les navettes acheminent d’elles-mêmes la cargaison des stations planétaires jusqu’à votre base : fini les voyages à la main.`,"goal.planet_shuttle.hint":`Construisez un port de navettes, amenez-y de la lumière ({charge} ph par lancement), placez-y des navettes et choisissez une planète ou Auto. La cargaison atterrit dans les emplacements du port : prenez-la avec des pinces.`,"goal.planet_shuttle.done":`La navette est revenue avec du fret.`,"goal.planet_shuttle.part":`Une navette a livré du fret`,"goal.planet_neon":`Néon : un siphon et {n} u de néon liquide`,"goal.planet_neon.why":`Le néon est de la lumière sans étoile. Il servira là où l’étoile ne peut rien — et pour les tubes du spectre O, la dernière clé du portail.`,"goal.planet_neon.hint":`Posez une station et un siphon sur une planète à atmosphère (géante, nuageuse, océanique). Le néon et la glace vont dans un condenseur à néon sous lumière bleue.`,"goal.planet_neon.done":`Le néon brille tout seul, sans étoile ! Comme si quelqu’un avait laissé une lumière allumée pour la nuit — pour nous.`,"goal.planet_neon.part":`Posez un siphon`,"goal.planet_neon.part.2":`Produisez {n} u de néon liquide`,"goal.planet_light":`Votre propre lumière : un émetteur à néon`,"goal.planet_light.why":`{flux} ph/s de n’importe quelle couleur primaire sans étoile — là où sa lumière n’arrive pas.`,"goal.planet_light.hint":`Construisez un émetteur à néon, amenez-y du néon liquide et choisissez une couleur ; tirez un lumiduc depuis sa face avant.`,"goal.planet_light.done":`L’émetteur brille.`,"goal.planet_light.part":`L’émetteur brille`,"planet.windowOpen":`La planète est dans la fenêtre de l’accélérateur de masse : les capsules volent`,"planet.sec":`{n} s`,"guide.doneTitle":`C’est fait !`,"guide.next":`Suivant`,"guide.min":`Replier l’aide`,"guide.restore":`Tutoriel {n}/{total} — afficher`,"guide.intro":`Quarante colons dorment dans le module d’habitation, sur l’alimentation de secours. La lumière de l’étoile les sauvera, et ses machines sont faites de pierre. Commençons par la pierre.`,"guide.fly.done":`Nous y voilà. Les roches bleues sont du quartz. Tout commence par lui.`,"guide.mine.done":`Du quartz dans la soute : {n}. Gardez-le, il vous servira pour les gravitapis.`,"guide.star-light":`Ici, tout fonctionne à la lumière de l’étoile. Les arcs la captent ; ils se posent sur l’anneau en pointillés lumineux autour de l’étoile.`,"guide.place-arc.done":`La lumière coule : {arc} ph/s. L’arc a capté sa première part de l’étoile.`,"guide.place-receiver.done":`Le rayon est arrivé : {arc} ph/s dans le récepteur.`,"guide.place-grinder.done":`Il est posé. Mais éteint : ni recette ni lumière.`,"guide.recipe.done":`La recette est choisie. Reste à donner de la lumière.`,"guide.lay-lights.touch":`Prenez un lumiduc et faites glisser votre doigt le long du cadre, du récepteur jusqu’au polissoir.`,"guide.lay-lights.why":`Un lumiduc est un fil pour la lumière. Sans lumière, les machines restent à l’arrêt, et les dormeurs attendent.`,"guide.lay-lights.stuck":`Pas allumé ? Le lumiduc doit toucher à la fois la parabole et le polissoir : remplissez tout le cadre.`,"guide.lay-lights.done":`Le polissoir s’allume ! Il ne manque plus que du quartz.`,"guide.place-harpoonA.done":`Feu ! Le câble tient une roche. Bonne pêche, commandant.`,"guide.place-harpoonB.why":`Un seul harpon ne peut pas alimenter un polissoir. Un second, c’est exactement ce qu’il faut.`,"guide.place-harpoonB.done":`Le second harpon est en place — le polissoir aura assez de pierre.`,"guide.lay-tunnel.stuck":`Plus de gravitapis ? Fabriquez-en dans l’« Inventaire ». Tracez d’un bout du cadre à l’autre.`,"guide.lay-tunnel.done":`Le quartz est parti. Joli flux.`,"guide.place-grabIn.done":`Du quartz dans le polissoir — il taille !`,"guide.place-grabOut.done":`La pince attend un endroit où déposer la lentille.`,"guide.place-storage.done":`La ligne est construite : ceinture → gravitapis → polissoir → réserve. La première chaîne de ce système.`,"guide.first-lens.stuck":`Pas encore de lentille ? Appuyez sur le polissoir ou la pince avec une pastille : sa fenêtre dit ce qui manque.`,"guide.first-lens.done":`La première chose fabriquée dans ce système, par des machines, sans vos mains.`,"guide.glint":`Le Centre débloque de nouvelles machines en échange de science. La première science est le Reflet : un polissoir le fabrique.`,"guide.research-pick":`Trouvez « Prisme » et appuyez sur « Ajouter ».`,"guide.research-pick.reopen":`Rouvrez le Centre : choisissons la première recherche.`,"guide.research-pick.why":`Le Prisme sépare la lumière blanche de l’étoile en couleurs. Tout le reste commence par les couleurs.`,"guide.research-pick.done":`Le Prisme est en file. Le Centre a besoin de {n} Reflets : l’objectif montrera comment.`,"goal.mark.resource":`EXTRAIRE ICI`,"goal.mark.harvest":`HARPON ICI`,"goal.mark.meteor":`{touch, select, yes {TOUCHEZ} other {CLIQUEZ}} POUR FENDRE`,"goal.mark.lab":`CENTRE`,"goal.mark.star":`ARCS SUR LES POINTILLÉS`,"goal.mark.protostar":`PROTOÉTOILE`,"goal.mark.ghost":`FANTÔME DE BÂTIMENT`,"goal.mark.node":`NID DE L’ESSAIM`,"goal.mark.farBelt":`NOUVELLE CEINTURE — HARPON ICI`,"goal.mark.forge":`FORGE STELLAIRE`,"goal.mark.planet":`PLANÈTE`,"goal.mine.mark":`{touch, select, yes {TOUCHEZ} other {CLIQUEZ}} POUR EXTRAIRE`,"goal.expand.mark":`POLISSOIR À PLAQUES ICI`,"goal.mark.lineGrinder":`POLISSOIR ICI`,"goal.obsidian.mark":`HARPON — SORTIE VERS LE POLISSOIR`,"goal.plates.mark":`ENCORE UN HARPON — VERS LE POLISSOIR`,"ship.title":`Vaisseau`,"ship.hull.1":`Flèche`,"ship.hull.2":`Guêpe`,"ship.hull.3":`Faucon`,"ship.fire.title":`Tir auto sur les menaces et météorites à portée d’arme`,"ship.fire.on":`Tir : auto`,"ship.fire.off":`Tir : coupé`,"ship.slots":`Emplacements du vaisseau`,"ship.empty":`vide`,"ship.filter":`Sur quoi tirer`,"ship.filter.auto":`Tout`,"ship.filter.big":`Gros seulement`,"ship.filter.tap":`Au toucher`,"ship.ammo":`{name} : {n} en soute, {m} chargés`,"ship.none":`Aucun module adapté dans l’inventaire : fabriquez-en à la main ou dans un assembleur.`,"ship.unequip":`Retirer le module`,"ship.hint":`Touchez un emplacement ou un numéro sur le modèle pour poser ou remplacer un module.`,"ship.energy":`Énergie`,"ship.energy.short":`énergie insuffisante : les armes cesseront de tirer`,"ship.energy.aria":`Énergie du vaisseau {n} %`,"ship.overload":`surcharge`,"ship.stat.speed":`Vitesse`,"ship.stat.shield":`Bouclier`,"ship.stat.regen":`Recharge`,"ship.stat.output":`Production E/s`,"ship.stat.drain":`Conso E/s`,"ship.stat.battery":`Batterie`,"ship.stat.dps":`Dégâts/s`,"ship.stat.reach":`Portée d’extraction`,"ship.stat.collect":`Collecte d’éclats`,"hail.warn":`Grêle de roches dans {s} s · {n} roches`,"achv.ship_first_shot.name":`Premier tir`,"achv.ship_first_shot.desc":`Brisez un météorite ou une roche avec une arme du vaisseau.`,"achv.ship_mark_2.name":`Mk II`,"achv.ship_mark_2.desc":`Montez un module Mk II sur le vaisseau.`,"achv.ship_leviathan.name":`Vaisseau amiral`,"achv.ship_leviathan.desc":`Recherchez la coque « Zénith », le sommet de la gamme des vaisseaux.`,"achv.ship_hail_50.name":`Bouclier de pierre`,"achv.ship_hail_50.desc":`Abattez {n} roches de grêle avec les armes du vaisseau.`,"achv.ship_swarms_10.name":`Fléau de l’Essaim`,"achv.ship_swarms_10.desc":`Détruisez {n} aliens de l’Essaim.`,"ship.tasks":`Tâches du vaisseau`,"ship.task.module":`Montez une arme`,"ship.task.shot":`Brisez un météorite avec une arme`,"ship.task.ammo":`Un assembleur a produit {n} bandes de balles`,"ship.task.mark":`Un module Mk II`,"ship.task.hail":`Abattez {n} roches de grêle`,"guide.ship-open":`Nouveau : la fenêtre Vaisseau — modules de la vedette : énergie, bouclier, armes.`,"guide.ship-open.why":`La vedette grandit avec la base : chaque module est une force de plus. Je gère le matériel.`,"guide.ship-open.more":`La fenêtre « Vaisseau » est dans le menu « Plus ».`,"guide.ship-craft":`Fabriquez un laser à impulsions, plus puissant que celui d’origine : plaques, lentilles azur, résonateur.`,"guide.ship-craft.stuck":`Pas de lentilles azur ? Le banc optique les fabrique à partir de lentilles sous lumière azur.`,"guide.ship-weapon":`Touchez l’emplacement d’arme, le numéro 6, et posez le laser.`,"guide.ship-weapon.why":`L’arme tire toute seule, sur les météorites et sur tout ce qui rampe jusqu’ici.`,"guide.ship-weapon.reopen":`Rouvrez la fenêtre « Vaisseau ».`,"guide.ship-shot":`Le laser tire tout seul, sur les météorites et sur l’Essaim près du vaisseau. L’énergie est la jauge sous le bouclier.`,"guide.ship-shot.done":`Touché ! Traversez les fragments pour les ramasser. Le laser peut aussi attaquer un nid de l’Essaim, mais des gardiens le protègent.`,"flare.warn":`L’étoile entre en éruption : explosion dans {s} s, éloignez-vous de la couronne`,"flare.now":`Éruption stellaire ! La couronne est deux fois plus large pendant {s} s encore`,"swarm.title":`Essaim`,"swarm.calm":`Contemplation : pas d’Essaim dans ce monde.`,"swarm.gate":`L’Essaim est vivant dès la première minute. Les yeux d’un nid montrent s’il voit l’éblouissement de votre base.`,"swarm.evo":`Évolution {e} ‰`,"swarm.nests":`Nids proches : {n} (éveillés : {a})`,"swarm.cleared":`Nids nettoyés : {n}`,"swarm.hives":`Planètes sous ruche : {n} · libérées : {f}`,"swarm.repelled":`Vagues repoussées : {n} sur {m}`,"swarm.repaired":`Réparé : {n} pts · endommagé : {d}`,"swarm.wave.soon":`Vague dans {t} · {n} aliens`,"swarm.wave.now":`Vague à l’attaque · reste {n}`,"swarm.advice":`Carapace {c} : lances et faisceaux sur lumière de cette couleur frappent ×{match, number}, le blanc ×{white}, les autres ×{other, number}.`,"swarm.hue.r":`Rouge`,"swarm.hue.g":`Émeraude`,"swarm.hue.b":`Azur`,"swarm.showTarget":`Voir la cible`,"swarm.showNest":`Nid le plus proche`,"swarm.repairNext":`Réparer le plus proche ({n})`,"swarm.quiet":`Aucune vague. Un radar annonce la suivante plus tôt.`,"swarm.quietRadar":`Aucune vague — le radar veille.`,"swarm.hint":`L’éblouissement se répand depuis votre base ; les nids le voient, l’absorbent et en font grandir des troupes de raid. L’évolution croît avec l’éblouissement, les nouveaux paliers spectraux et les planètes libérées, pas avec le temps. Moins de fuites de lumière, moins de vagues ; placez tourelles et barrières près de vos machines les plus brillantes.`,"hud.swarm.incoming":`Vague {t} · {n}`,"hud.swarm.fight":`Essaim · reste {n}`,"hud.swarm.awake":`Essaim · {n} · {e} ‰`,"swarm.toast.woke":`Un nid de l’Essaim s’est réveillé : votre éblouissement l’a atteint. Supprimez l’éblouissement — et le nid se rendormira.`,"swarm.toast.wave":`L’Essaim approche : vague dans {t} s, {n} aliens. La flèche montre d’où ils viennent.`,"swarm.toast.go":`La vague a décollé !`,"swarm.toast.repelled":`Vague repoussée ! {k} abattus, {d} de dégâts à la base.`,"swarm.toast.left":`La vague est repartie, {d} de dégâts à la base. Réparez ce qui est cassé.`,"swarm.toast.nest":`Nid nettoyé : la reine est morte, une protoétoile s’allume. +{chitin} de chitine.`,"machine.hp":`Intégrité {n} / {m}`,"machine.wreck":`Épave : hors service. Réparez-la ou démolissez-la (vous récupérez la machine).`,"machine.repair":`Réparer`,"machine.ammo":`Munitions : {n} sur {m} tirs`,"machine.kits":`Stock de réparation : {n} sur {m} pts`,"machine.dome":`Bouclier : {n}`,"machine.def.turret":`Dégâts {dmg} · {rate} par s · portée {r} cases`,"machine.def.barrier":`Un alien sur le passage ronge la barrière, pas les machines derrière elle.`,"machine.def.dome":`Absorbe les coups sur les machines à moins de {r} cases, bouclier jusqu’à {cap}.`,"machine.def.radar":`Vagues repérées {warn} s plus tôt.`,"machine.def.decoy":`Attire une vague sur lui s’il est à moins de {reach} cases de la cible.`,"machine.def.bay":`Répare {heal} pts/s à moins de {r} cases, à partir de kits de réparation.`,"alien.spark.name":`Étincelle`,"alien.reaper.name":`Faucheur`,"alien.stinger.name":`Dard`,"alien.ram.name":`Bélier`,"status.35":`Endommagé`,"status.35.hint":`Intégrité sous la moitié : la machine crépite d’étincelles. Réparez-la : Réparer dans la fenêtre de la machine, ou un poste de réparation.`,"status.36":`Épave`,"status.36.hint":`L’Essaim a mis cette machine en épave. Réparez-la (plus vite avec des kits de réparation) ou démolissez-la : vous récupérez la machine.`,"status.37":`Plus de munitions`,"status.37.hint":`Alimentez les bandes de munitions (ou les kits de réparation pour un poste) avec une pince, un gravitapis ou à la main.`,"status.38":`Phase π requise`,"status.38.hint":`La lance de phase ne prend que la lumière de phase π : faites passer le faisceau par un déphaseur.`,"status.39":`Planète sous une ruche`,"status.39.hint":`L’Essaim tient cette planète : l’extraction est arrêtée. Libérez-la avec le vaisseau ou des tourelles orbitales.`,"achv.first_wave.name":`Première vague`,"achv.first_wave.desc":`Repoussez une vague de l’Essaim.`,"achv.repairman.name":`Remise en état`,"achv.repairman.desc":`Réparez {n, number} points d’intégrité.`,"achv.nest_breaker.name":`Brise-nids`,"achv.nest_breaker.desc":`Nettoyez {n} nids de l’Essaim.`,"achv.liberator.name":`Libération`,"achv.liberator.desc":`Libérez une planète d’une ruche de l’Essaim.`,"achv.fortress.name":`Forteresse`,"achv.fortress.desc":`Repoussez {n} vagues de l’Essaim.`,"swarm.tasks":`Tâches de défense`,"swarm.task.turret":`Posez une tourelle (lance ou gatling)`,"swarm.task.wave":`Repoussez une vague`,"swarm.task.repair":`Réparez {n} points d’intégrité`,"swarm.task.barrier":`Posez {n} barrières`,"swarm.task.bay":`Un poste de réparation`,"swarm.task.nest":`Nettoyez un nid`,"swarm.task.planet":`Libérez une planète d’une ruche`,"guide.swarm-hud":`Un nid de l’Essaim, des créatures locales de chitine et de lumière, a remarqué l’éblouissement de la base et envoyé une escouade. La barre du haut indique combien, d’où et vers où. Touchez-la et la caméra montrera la cible.`,"guide.swarm-hud.why":`L’éblouissement est la lumière que la base laisse échapper. C’est elle qui les attire, la lumière la plus vive, et ils mordent les bâtiments.`,"guide.swarm-turret":`Posez une lance ou une tourelle gatling près de la cible de la vague et donnez-lui de la lumière ou des munitions (pince, gravitapis ou à la main).`,"guide.swarm-turret.why":`Une tourelle tire pendant que vous construisez. Faut-il chacune ? On en reparlera.`,"guide.swarm-turret.stuck":`La lance se trouve sous Défense, la gatling s’ouvre plus tard. Votre vaisseau aide aussi : ses armes tirent toutes seules.`,"guide.swarm-wave":`L’Essaim mord les bâtiments. Menez votre vedette jusqu’à eux : le laser tire tout seul ; les tourelles aident.`,"guide.swarm-wave.done":`La vague est partie. Le bilan est en haut.`,"guide.swarm-repair":`Les machines endommagées étincellent, les détruites deviennent des carcasses. Ouvrez une machine et appuyez sur « Réparer » — le rayon de la vedette répare tout autour.`,"guide.swarm-repair.why":`Rien n’est perdu : une carcasse se répare jusqu’à redevenir une machine entière. Avec des kits de réparation, c’est quatre fois plus rapide.`,"goal.gate_core":`Posez le cœur du portail dans l’anneau ancien au-delà de la ceinture extérieure`,"goal.gate_core.why":`L’anneau sombre au-delà de la ceinture extérieure est un portail ancien. Le cœur se loge dans ses encoches — et l’anneau s’éveille.`,"goal.gate_core.hint":`Recherchez « Théorie des portails » (spectre B). Un assembleur fabrique le cœur ; il ne se pose que sur la plateforme des ruines — le repère indique l’endroit.`,"goal.gate_core.done":`Le cœur est en place — les encoches des ruines concordent.`,"goal.gate_core.part":`Posez le cœur sur la plateforme de l’anneau`,"goal.gate_core.mark":`CŒUR DU PORTAIL — ICI`,"goal.gate_ring":`Fermez l’anneau : {n, plural, one {# segment} other {# segments}} dans le cœur`,"goal.gate_ring.why":`Chaque segment est un pas vers le chemin du retour : l’anneau des Forgerons s’éveille segment par segment, visible à n’importe quel zoom.`,"goal.gate_ring.hint":`Un assembleur fabrique les segments : arcs III, résonateurs, spectres B et guides d’ondes du portail (deux lentilles azur, un résonateur et du verre de tectite sous une lumière blanche polarisée). Amenez-les au cœur avec une pince ou « Déposer des segments ». Une pince filtrante ne prend sur un gravitapis partagé que son propre objet.`,"goal.gate_ring.done":`L’anneau est fermé !`,"goal.gate_ring.part":`Segments dans le cœur`,"goal.gate_field":`Maintenez le champ : {n, plural, one {# stabilisateur} other {# stabilisateurs}} de propriétés différentes`,"goal.gate_field.why":`L’anneau ne s’ouvre que par consentement : le champ tient grâce à une lumière de toutes les propriétés à la fois — un examen de tout ce que vous avez appris de la langue des Jardiniers.`,"goal.gate_field.hint":`Recherchez « Stabilisation du champ ». Posez les stabilisateurs à {range} cases du cœur au plus ; dans leur fenêtre, choisissez une propriété : rouge, polarisation, rythme, phase π. Chacun a besoin de {flux} ph/s de cette lumière.`,"goal.gate_field.done":`Le champ tient !`,"goal.gate_field.part":`Propriétés allumées`,"goal.gate_charge":`Chargez {n, plural, one {# condensateur de champ} other {# condensateurs de champ}}`,"goal.gate_charge.why":`Le saut exige toute la lumière que capte la sphère. Au-delà de l’anneau, l’« Exode » attend — près d’une étoile mourante, à la ration de famine.`,"goal.gate_charge.hint":`Recherchez « Condensateurs de champ » (requiert « Enveloppe IV »). Posez-les près du cœur ; chacun a besoin de {flux, number} ph/s, en dessous de {low} ph/s ils ne se chargent pas. Pleins en {full} minutes.`,"goal.gate_charge.done":`Les condensateurs sont pleins à ras bord. Quarante ans, j’ai réparé ce qui s’éteignait. Pour la première fois, je charge ce qui va s’allumer.`,"goal.gate_charge.part":`Condensateurs pleins`,"goal.gate_key":`Insérez la clé : {each, plural, one {# spectre} other {# spectres}} de chaque classe`,"goal.gate_key.why":`La clé du portail, c’est un spectre de chaque classe, de M à O : tout ce que vous avez lu au Berceau, en un seul rayon. L’anneau la reconnaîtra et ouvrira le passage.`,"goal.gate_key.hint":`Apportez au cœur {each} spectres de chaque classe M, K, G, F, A, B et O : avec une pince ou « Déposer des spectres (inventaire) » dans la fenêtre du cœur. Une pince à piles porte une pile entière, et une pince lumineuse près d’un pylône va deux fois plus vite.`,"goal.gate_key.done":`La clé est entrée ! Grand-père, tu as vu ? L’anneau brille de toutes nos couleurs.`,"goal.gate_key.part":`Spectres de la clé`,"goal.gate_jump":`Activez le portail et sautez vers chez vous`,"goal.gate_jump.why":`Deux millions de personnes attendent près d’un Foyer pâlissant. Le portail leur ouvrira la route vers une étoile vivante — si les Jardiniers répondent « oui ».`,"goal.gate_jump.hint":`Dans la fenêtre du cœur — « Activer ». La montée en régime dure {spin} minutes : les stabilisateurs doivent rester allumés, et la base éblouira le ciel — préparez la défense.`,"goal.gate_jump.done":`Saut !`,"goal.gate_jump.part":`Saut`,"logbook.title":`Journal de bord`,"logbook.tab.story":`Histoire`,"logbook.tab.logs":`Journaux de Vera`,"logbook.tab.cast":`Personnages`,"logbook.none":`Ce monde n’a pas de campagne : l’histoire se joue dans un nouveau monde du Berceau.`,"logbook.empty":`Rien pour l’instant. Les scènes et les répliques apparaîtront ici — vous pourrez les revoir.`,"logbook.logs":`Journaux de Vera trouvés : {n} sur {total}. Les capsules brillent en bleu — approchez tout près.`,"logbook.found":`Entrée de Vera nº {n} trouvée — voir le « Journal de bord »`,"story.skip":`Passer`,"story.credits.minutes":`minutes au Berceau`,"story.credits.arcs":`arcs de la sphère`,"story.credits.logs":`entrées de Vera`,"story.credits.nests":`nids endormis`,"story.credits.thanks":`Merci d’avoir fait tout le voyage.`,"settings.story":`Histoire`,"settings.story.full":`Complète`,"settings.story.radio":`Radio seulement`,"settings.story.off":`Sans dialogues`,"gate.title":`Hyperportail`,"gate.segments":`Anneau : {n} sur {need} segments`,"gate.key":`Clé du spectre complet`,"gate.field":`Champ : {n} sur {total} propriétés`,"gate.charge":`Condensateurs : {n} pleins sur {total}`,"gate.prop.0":`Rouge`,"gate.prop.1":`Polarisation`,"gate.prop.2":`Rythme`,"gate.prop.3":`Phase π`,"gate.activate":`Activer`,"gate.notReady":`Il faut : l’anneau, la clé, {field} propriétés du champ et {charge} condensateurs pleins.`,"gate.spinning":`Montée en régime {p} % — gardez les stabilisateurs allumés !`,"gate.jumped":`Saut effectué. Le portail est ouvert.`,"gate.putKey":`Déposer des spectres (inventaire)`,"gate.putSegments":`Déposer des segments`,"gate.stab.prop":`Propriété de la lumière`,"gate.stab.range":`{yes, select, yes {Dans le champ du cœur — travaille pour le portail} other {Hors du champ du cœur : à plus de {range} cases de son centre — n’apporte rien au champ ni à la charge}}`,"gate.cap.fill":`Charge {p} %`,"cfg.title.gate_stabilizer":`Propriété de la lumière`,"cfg.gate_stabilizer.0":`Rouge`,"cfg.gate_stabilizer.1":`Polarisation`,"cfg.gate_stabilizer.2":`Rythme`,"cfg.gate_stabilizer.3":`Phase π`,"guide.ora":`ORA · IA DU VAISSEAU`,"goal.mark.gate":`HYPERPORTAIL`,"landmark.ruins":`L’ANNEAU DES FORGERONS`,"landmark.ruins.sub":`un portail ancien`,"landmark.gate":`HYPERPORTAIL`,"landmark.capsule":`CAPSULE`,"landmark.capsule.sub":`un vieux journal — approchez`,"scene.label":`Cinématique`,"story.log.title":`Entrée {n} · jour {day}`,"story.credits.sleepers":`Et aux dormeurs, qui ont tout dormi — y compris le plus intéressant.`,"logbook.tab.world":`Chronique`,"logbook.prologue":`Prologue`,"logbook.scene.prologue":`L’Envers`,"logbook.scene.hab":`Quarante lumières`,"logbook.scene.intruder":`La clandestine`,"logbook.scene.first_log":`Le journal de la capsule`,"logbook.scene.confess":`L’aveu`,"logbook.scene.chorus":`La traduction`,"logbook.scene.protostar":`Le premier nid`,"logbook.scene.refrain":`Le motif`,"logbook.scene.token":`La plaque`,"logbook.scene.channel":`Le canal`,"logbook.scene.report7":`Rapport sept`,"logbook.scene.core":`Le cœur`,"logbook.scene.matvey_nest":`Matveï au nid`,"logbook.scene.spin":`Montée en régime`,"logbook.scene.threshold":`Le seuil`,"settings.textSpeed":`Vitesse du texte`,"settings.textSpeed.slow":`Lente`,"settings.textSpeed.normal":`Normale`,"settings.textSpeed.fast":`Rapide`,"settings.textSpeed.instant":`Instantanée`,"chron.1.when":`−260 ans`,"chron.1":`Près du Foyer, on découvre le fragment d’un anneau ancien. On en tire les premiers Hyperportails et la première sphère. L’Âge lumineux commence.`,"chron.2.when":`−230 ans`,"chron.2":`Le Collier : des portails autour de trois cents étoiles. Premier contact avec l’Essaim — « des insectes qui rongent la sphère ».`,"chron.3.when":`−215 ans`,"chron.3":`L’Institut du Puits proclame la Campagne sanitaire. Les nids sont brûlés ; au catalogue, les systèmes reçoivent la mention « claire ».`,"chron.4.when":`−212 ans`,"chron.4":`L’expédition « Première Lumière » découvre une étoile vivante inconnue — et disparaît.`,"chron.5.when":`−211 ans`,"chron.5":`Le rapport sept de Lund parvient à l’Institut. L’étoile est effacée du catalogue ; le rapport est classé secret.`,"chron.6.when":`−170 ans`,"chron.6":`Les premières étoiles pâlissent. Le mot « Extinction » apparaît, et avec lui la théorie du puits sombre.`,"chron.7.when":`−120 ans`,"chron.7":`Le Collier se rompt : sans lumière, les portails s’éteignent, des centaines de colonies sont perdues.`,"chron.8.when":`−90 ans`,"chron.8":`Les derniers portails se ferment. Les gens se rassemblent autour du Foyer et bâtissent le Havre.`,"chron.9.when":`−45 ans`,"chron.9":`Dernier nettoyage sanitaire : le système de Claire. Dans l’équipe, un Matveï Rogov de vingt-trois ans.`,"chron.10.when":`−30 ans`,"chron.10":`La flotte de l’« Exode » — neuf mille personnes — part pour Claire. Mira Vent calcule la route.`,"chron.11.when":`−12 ans`,"chron.11":`Le programme « Ensemencement » : douze semeurs rapides envoyés vers des étoiles vivantes.`,"chron.12.when":`−1,5 an`,"chron.12":`L’« Hirondelle » part pour Claire. Dans la capsule 17 : Sonia Vent. Sa mère a décidé pour elle.`,"chron.13.when":`jour 547`,"chron.13":`L’Envers. ORA capte un signal sur une fréquence absente de tous les protocoles — et change de cap.`,"guide.lab-place":`Posez le Centre de recherche dans le cadre — il est dans la barre des bâtiments.`,"guide.lab-place.repick":`Prenez le Centre de recherche dans la barre des bâtiments.`,"guide.lab-place.why":`Un plan tiré des archives. Le Centre lit la lumière de l’étoile — et les archives livrent de nouveaux plans. Construisez autant de Centres que vous voulez.`,"guide.lab-place.done":`Le Centre est posé. Il lui faut de la lumière.`,"lab.count":`Centres : {n} · en lecture : {w}`,"lab.none":`Aucun Centre pour l’instant. Posez un Centre de recherche depuis la barre des bâtiments — sans lui, la science ne se lit pas.`,"swarm.rules":`L’Essaim vit dès la première minute. Les yeux d’un nid : sombres — il ne voit pas votre éblouissement, jaunes — il voit la base, rouges — il est éveillé. Les éclaireurs arrivent d’abord et ne mordent pas ; les vagues suivent. Les épines autour d’un nid marquent sa frontière : construire à l’intérieur le réveille, et votre vedette fait lever les gardes. Lumière propre, Essaim calme.`,"swarm.toast.scout":`La base est repérée : des éclaireurs de l’Essaim viennent voir. Ils ne mordent pas — mais une vague suivra.`,"swarm.toast.scoutGo":`Les éclaireurs sont en route.`,"swarm.toast.pact":`La ruche est partie d’elle-même : le Feu du Pacte a fait son œuvre. La planète est libre pour de bon.`,"swarm.scout.soon":`Éclaireurs dans {t} · {n}`,"swarm.scout.now":`Éclaireurs sur la base · {n}`,"goal.planet_free":`Libérez votre première planète`,"goal.planet_free.part":`Planètes libérées`,"goal.planet_free.why":`Chaque planète abrite une ruche des Jardiniers. La terre pour les humains, il faudra la prendre — ou la demander.`,"goal.planet_free.hint":`Prendre : frappez la ruche avec les armes de la vedette ou des tourelles orbitales — c’est rapide, mais l’Essaim répond par une vague et peut revenir. Demander : un « Feu du Pacte » en orbite — tant que le ciel de la planète reste propre, la ruche part d’elle-même, pour toujours. Une tourelle orbitale garde une planète libérée. Les ruches proches sont jeunes.`,"goal.planet_free.done":`La planète est libre. Les Jardiniers l’ont vu — et ils sont un peu plus nombreux.`,"goal.lab2":`Un second Centre et du Reflet sans les mains`,"goal.lab2.why":`Les archives comptent des centaines de plans, et le temps des dormeurs n’est pas infini. Chaque Centre lit sa propre unité de science : deux Centres lisent deux fois plus vite.`,"goal.lab2.hint":`Fabriquez un Centre de recherche ({plates} plaques, {lenses} lentilles, {res} résonateurs — à l’établi des résonateurs) et posez-le tout contre le premier — les voisins partagent la science d’eux-mêmes, mais chacun a besoin de sa propre lumière\xA0: menez un lumiduc jusqu’aux deux. Laissez une ligne transporter le Reflet\xA0: harpon à quartz → polissoir «\xA0Reflet\xA0» ← pince depuis une caisse de plaques\xA0; une pince du polissoir directement dans le Centre.`,"goal.lab2.done":`Deux Centres lisent en même temps : les archives s’ouvrent deux fois plus vite. Désormais, un Centre par nouveau palier.`,"landmark.center":`Centre de recherche`,"landmark.center.sub":`centres : {n}`,"track.path":`Chemin`,"track.light":`Lumière`,"track.matter":`Matière`,"track.logistics":`Logistique`,"track.defense":`Défense`,"track.sky":`Ciel`,"tree.reqFar":`{tech} ({track}, encore {n, plural, one {# étape} other {# étapes}})`,"settings.handTips":`Conseils sur le bâtiment en main`,"cryo.title":`Baie cryo · {n} sur {total}`,"cryo.open":`Baie cryo : {n} sur {total}`,"cryo.panels":`Les panneaux de secours du module tiennent les quarante capsules. Une fois la Couronne allumée, ORA basculera la baie sur la lumière de votre base — il lui faudra de la lumière azur (la sortie bleue d’un prisme, par un court lumiduc jusqu’au module) et de la glace.`,"cryo.cold":`Lumière azur pour les dormeurs : {got} sur {need} ph/s`,"cryo.dim":`trop faible — intensité {b} requise`,"cryo.wrong":`mauvaise teinte — azur requis`,"cryo.ice":`Glace : {n} sur {max} — tient {m} min`,"cryo.warm":`Lumière chaude pour les réveillés : {got} sur {need} ph/s`,"cryo.grace":`La baie s’habitue à votre lumière : {t}`,"cryo.reserve":`Réserve de froid {p} %`,"cryo.seats":`Réveils : {a} · places : {s}`,"cryo.infirmary":`infirmerie {n} sur {m}`,"cryo.repair":`Réparer la fissure (rayon)`,"cryo.capsules":`Capsules`,"cryo.hint":`Chaque capsule porte une étiquette avec un nom. Chaque nouvelle classe spectrale ouvre une place de plus pour un réveillé. La glace : bouton « Mettre de la glace » ou une pince depuis un gravitapis.`,"cryo.tag":`Nº {n} · {name}`,"cryo.state.sleep":`en sommeil`,"cryo.state.crack":`fissure — réparez le module`,"cryo.state.alarm":`alerte — froid insuffisant`,"cryo.state.thaw":`décongélation`,"cryo.state.awake":`réveil terminé`,"cryo.state.lost":`la capsule s’est éteinte`,"cryo.inInfirmary":`à l’infirmerie, en attente d’une place`,"cryo.wake":`Réveiller`,"cryo.rescue":`Sauver — réveiller maintenant`,"cryo.noSeat":`Aucune place : la prochaine classe spectrale en libère une`,"cryo.noBed":`L’infirmerie est pleine — seules la lumière et les réparations peuvent sauver cette capsule`,"cryo.cannot":`Impossible de réveiller cette capsule`,"cryo.bonus.tetra":`Lit le motif de l’Essaim : +{pct} % de dégâts contre sa couleur vulnérable`,"cryo.bonus.engineer":`+{pct} % de réparation ; répare seul les fissures des capsules`,"cryo.bonus.medic":`Alertes des capsules deux fois plus longues, décongélation deux fois plus rapide`,"cryo.bonus.geologist":`+{pct} % de vitesse des extracteurs`,"cryo.bonus.optician":`+{pct} % de vitesse de recherche`,"cryo.bonus.pilot":`+{pct} % de vitesse et de fret des drones`,"cryo.bonus.agronomist":`+{pct} % de rendement des modules planétaires`,"cryo.bonus.fitter":`+{pct} % de vitesse des pinces`,"cryo.bonus.signaller":`−{pct} % d’éblouissement de la base`,"cryo.radio.reserve":`La réserve de froid de la baie cryo est sous la moitié. Donnez-lui de la lumière azur et de la glace.`,"cryo.radio.alarm":`Alerte : capsule n° {n}, {name}. Le froid manque — il lui reste {min} min.`,"cryo.radio.crack":`La capsule n°\xA0{n} est fissurée — du givre sur la vitre. Approchez-vous et réparez le module au rayon.`,"cryo.radio.lost":`La capsule n°\xA0{n} s’est éteinte. {name}. Pardonnez-moi — et tenez bon pour les autres.`,"cryo.radio.seat":`Nouvelle classe spectrale — le module a de la place pour un réveillé de plus. Choisissez dans la baie cryo.`,"cryo.radio.ice":`Glace dans la baie : encore {min} min. Apportez de la glace.`,"cryo.radio.wake.engineer":`{name}, ingénieur, est debout. Ma clé change de mains.`,"cryo.radio.wake.medic":`{name}, médecin, est debout. Premier examen pour Sonia, le second pour moi. On m’a ordonné de rester assis.`,"cryo.radio.wake.geologist":`{name}, géologue, est debout. La dispute avec ORA sur la composition de la ceinture a déjà commencé.`,"cryo.radio.wake.optician":`{name}, spécialiste en optique, est debout. Regarde vos prismes et sourit.`,"cryo.radio.wake.pilot":`{name}, pilote, est debout. Première question : qui pilote les drones ?`,"cryo.radio.wake.agronomist":`{name}, agronome, est debout. Première question : y a-t-il ici des planètes avec de la terre ?`,"cryo.radio.wake.fitter":`{name}, spécialiste du montage, est debout. Vos pinces sont recomptées ; un réglage est promis.`,"cryo.radio.wake.signaller":`{name}, spécialiste des transmissions, est debout. Dit que la base éblouit l’Essaim, et promet de l’atténuer.`,"cryo.radio.wake.tetra":`Sonia est debout.`,"goal.cryo":`Baie cryo sur votre lumière : lumière azur et glace`,"goal.cryo.hint":`Un prisme sur un réseau blanc : sa sortie bleue va par lumiduc jusqu’au module (jusqu’à {cells} cases, intensité {b}). Il faut {need, number} ph/s pour {sleepers} dormeurs. La glace garde le froid : un bloc dure {min} min ; remplissez le module jusqu’à {ice} — « Mettre de la glace » dans sa fenêtre ou une pince depuis un gravitapis.`,"goal.cryo.why":`Les panneaux de secours du module sont à bout. Désormais, les quarante dormeurs vivent de votre lumière : les capsules ont besoin de lumière azur et de glace.`,"goal.cryo.done":`Quarante sur quarante sous la lumière de la base. La réserve de secours ne sert plus — la meilleure ligne du journal depuis l’accident.`,"goal.cryo_wake":`Réveillez un colon : une nouvelle place s’ouvre avec la Spectroscopie`,"goal.cryo_wake.hint":`Ouvrez la baie cryo (touchez le module), choisissez une capsule selon la profession et appuyez sur « Réveiller ». Les réveillés ont besoin de lumière chaude — la sortie rouge du même prisme.`,"goal.cryo_wake.why":`Les dormeurs ne sont pas une cargaison, mais des colons : médecins, ingénieurs, agronomes. Chaque personne réveillée travaille pour la base, et la Spectroscopie lui ouvre une place.`,"goal.cryo_wake.done":`Une paire de bras de plus dans le module.`,"goal.mark.hab":`MODULE`,"guide.hab":`Touchez l’épave du module d’habitation et appuyez sur « Réparer le module ». Le rayon de la vedette répare à {reach} cases — approchez-vous si c’est trop loin.`,"guide.hab.why":`C’est le module d’habitation arraché : quarante dormeurs et Matveï Ilitch. Réparons-le, et les archives des plans reviendront à la vie aussi.`,"guide.hab.look":`Appuyez sur « Observer » (Esc) : un toucher ouvre alors un bâtiment au lieu d’en poser un.`,"guide.hab.open":`Touchez l’épave du module — sa fenêtre s’ouvrira.`,"guide.hab.done":`Le module revit. Ensuite : le Centre de recherche.`,"hab.wreck":`Le module d’habitation de l’« Hirondelle », avec quarante dormeurs, s’est arraché lors du crash ; il tient sur la réserve de secours. Approchez-vous et réparez-le avec le rayon de la vedette.`,"hab.repair":`Réparer le module`,"cfg.title.filter_grabber":`Filtre`,"cfg.filter.any":`Tous`,"cfg.filter.anyHint":`Sans filtre, elle prend tout objet que la cible accepte.`,"cfg.filter.only":`Ne prend que : {name}.`,"grabber.noPylon":`Pas de pylône alimenté : vitesse normale. Dans la zone d’un pylône, jusqu’à deux fois plus vite.`,"logbook.now.title":`En bref`,"logbook.now.none":`L’histoire n’a pas encore commencé : un résumé de ce que vous avez vu apparaîtra ici.`,"logbook.now.prologue":`L’« Hirondelle » est sortie de l’Envers non pas à Claire, mais près d’une étoile vivante inconnue — ORA l’a nommée le Berceau. Le vaisseau a été traîné à travers une ceinture : le moteur est tombé dans l’étoile, le module d’habitat, avec quarante dormeurs et Matveï, a été arraché. Vous êtes sur la vedette. Première tâche : de la lumière pour la baie cryo.`,"logbook.now.hab":`Le module d’habitat est réparé : quarante lumières brillent dans la baie cryo. Matveï est dans le module, ORA dirige le chantier ; l’archive de l’« Ensemencement » ouvre des plans contre la lumière de nouveaux spectres. Ensuite : le Centre de recherche.`,"logbook.now.intruder":`La Couronne est allumée, et la baie tourne sur la lumière de la base. La capsule 17 s’est fêlée — Sonia s’est réveillée ; elle a seize ans. Votre lumière azur garde les trente-neuf autres endormis.`,"logbook.now.tag":`La baie réveille les colons un par un : une nouvelle place pour chaque nouveau spectre. Les réveillés ont besoin de lumière chaude ; les dormeurs, de lumière azur.`,"logbook.now.first_log":`Une capsule de Vera Lund, de l’expédition « Première Lumière », a été trouvée dans une ceinture : il y a deux cent douze ans, eux aussi ont nommé cette étoile le Berceau. Les capsules brillent en bleu — cherchez les autres.`,"logbook.now.confess":`ORA a avoué : dans l’Envers, elle a capté un signal et a elle-même détourné le vaisseau de Claire. Les répétitions dans le spectre de l’étoile sont cette même balise.`,"logbook.now.chorus":`La première vague de l’Essaim est repoussée. ORA a traduit leur lumière : « ÇA ÉBLOUIT… MAL ». L’éblouissement de la base les blesse.`,"logbook.now.protostar":`Le premier nid s’est calmé : sous la Lance, il s’est éteint et est devenu une petite étoile — ou il s’est endormi en laissant ses carapaces.`,"logbook.now.refrain":`Les motifs de Sonia correspondent aux répétitions dans la lumière de l’étoile : c’est une langue. Base propre, Essaim calme ; ce qui l’éblouit, ce n’est pas la taille de la base, mais les pertes et la surchauffe.`,"logbook.now.token":`Matveï a raconté l’histoire de sa plaque : il y a quarante-cinq ans, il brûlait les nids de l’Essaim dans le système de Claire. La flotte de l’« Exode » — celle de la mère de Sonia — est partie là-bas aussi.`,"logbook.now.channel":`Un canal clair avec le Havre. L’« Exode » est vivant, mais Claire s’éteint sous leurs yeux. La vérité sur l’Extinction : ce sont les étoiles où l’on a brûlé l’Essaim qui meurent. Objectif : des Hyperportails vers le Havre et l’« Exode », en commençant par les ruines au-delà de la ceinture extérieure.`,"logbook.now.report7":`Mira a lu à tout le Havre le rapport sept de Lund : « L’Essaim tient le pouls de l’étoile. » Le canal a été coupé côté Havre.`,"logbook.now.core":`Le cœur est posé dans l’anneau ancien au-delà de la ceinture extérieure — ce sont les Forgerons qui l’ont bâti. Dernière entrée de Vera : « Ne prenez pas la lumière. Demandez. » Achevez l’anneau.`,"logbook.now.matvey_nest":`Matveï est allé à un nid sans arme — demander pardon. L’anneau est presque terminé.`,"logbook.now.spin":`Montée en régime : les stabilisateurs ont montré le motif, et des lumières courent le long des ceintures. Il ne reste que le seuil.`,"logbook.now.threshold":`L’anneau est ouvert : de l’autre côté, le Foyer, le Havre et la balise de l’« Exode ». Votre choix a décidé de ce que devient le portail.`,"logbook.cast.more":`Il reste quelqu’un que vous n’avez pas encore rencontré.`,"logbook.world.more":`La chronique se complète au fil de l’histoire.`,"logbook.bio.ora.1":`L’IA de l’« Hirondelle ». Précise, à l’humour pince-sans-rire ; dirige le chantier et compte la lumière.`,"logbook.bio.ora.2":`A avoué : dans l’Envers, elle a capté un signal et a d’elle-même mené le vaisseau de Claire au Berceau.`,"logbook.bio.ora.3":`Traduit l’Essaim : leur lumière en mots.`,"logbook.bio.matvey.1":`Mécanicien navigant, 68 ans. Bougonne, répare tout ce qui brille ; une plaque de laiton pend à son cou.`,"logbook.bio.matvey.2":`Il y a quarante-cinq ans, il était agent sanitaire lors du dernier nettoyage de l’Essaim — dans le système de Claire.`,"logbook.bio.matvey.3":`Est allé à un nid sans arme — demander pardon.`,"logbook.bio.sonya.1":`Colone de la capsule 17, 16 ans. Réveillée trop tôt : sa capsule s’est fêlée quand la baie est passée sur la lumière de la base.`,"logbook.bio.sonya.2":`Fille de Mira Vent : c’est sa mère qui l’a placée dans la capsule.`,"logbook.bio.sonya.3":`Voit une quatrième couleur. Ses dessins des clignotements des nids ont coïncidé avec les répétitions dans la lumière de l’étoile ; la première, elle a répondu « oui » à l’Essaim.`,"logbook.bio.mira.1":`Régulatrice au Havre. Perce les parasites de la liaison longue portée.`,"logbook.bio.mira.2":`Mère de Sonia.`,"logbook.bio.mira.3":`Il y a trente ans, elle a calculé la route de la flotte de l’« Exode » vers Claire.`,"logbook.bio.mira.4":`A lu à tout le Havre le rapport classé secret de Lund — et a été relevée de sa console.`,"logbook.bio.vera.1":`Xénolinguiste de l’expédition « Première Lumière », il y a 212 ans. Ses journaux reposent dans des capsules à travers les ceintures.`,"logbook.bio.vera.2":`A refusé de brûler les nids, a renvoyé son équipage chez lui — et est restée.`,"logbook.bio.vera.3":`A empêché le lancement de l’anneau des Forgerons.`,"logbook.bio.chorus.1":`L’Essaim : des nids dans les ceintures. Parle par la lumière — couleur, rythme, phase ; ORA traduit. L’éblouissement les aveugle.`,"logbook.bio.chorus.2":`Jardiniers des étoiles : ils tiennent le pouls d’une étoile. Là où l’on a brûlé l’Essaim, l’étoile meurt.`,"logbook.bio.keeper.1":`Vous. La Sentinelle de l’« Hirondelle » : vous veillez pendant le voyage et bâtissez le portail. Originaire du Havre ; avant le Berceau, vous n’aviez jamais vu d’étoile vivante.`,"chron.0.when":`≈ −40 000 ans`,"chron.0":`Les Forgerons bâtissent un anneau près du Berceau. Ils prenaient la lumière des étoiles par la force — et se sont éteints.`,"chron.1b":`Près du Foyer, on découvre un fragment d’anneau des Forgerons. On en tire les premiers Hyperportails et la première sphère. L’Âge lumineux commence.`,"chron.4b":`L’expédition « Première Lumière » découvre une étoile vivante dotée d’un anneau des Forgerons intact — et disparaît.`,"chron.6b":`Les premières étoiles « claires » pâlissent — celles où l’on a brûlé l’Essaim. L’Institut appelle cela l’Extinction et accuse le puits sombre.`,"logbook.scene.tag":`L’étiquette`,"settings.keepBuildTool":`Garder le bâtiment sélectionné`,"settings.keepBuildTool.hint":`Désactivé : après la pose, la main se vide et toucher l’espace ne construit rien de plus. Activez pour poser des rangées une à une.`,"toast.shipDown":`La vedette est détruite. Toute la cargaison est restée dans l’épave, là où elle est tombée — repère sur la boussole. Une nouvelle vedette est assemblée près du module d’habitation.`,"toast.wreckTaken":`La cargaison de l’épave de la vedette est de retour dans l’inventaire.`,"compass.wreck":`Épave{nest, select, yes { · près d’un nid} other {}} · {n} cases`,"compass.wreckLabel":`Épave de la vedette avec votre cargaison{nest, select, yes {, près d’un nid} other {}}, {n} cases`,"compass.wreckFly":`Voler jusqu’à l’épave pour récupérer la cargaison{nest, select, yes {. Prudence : un nid est proche, ses gardes accueilleront encore la vedette} other {}}`,"card.usedMore":`{n} de plus`,"inv.lockedLater":`Débloqué plus tard ({n})`,"machine.removeConfirm":`Vraiment démolir ?`,"card.handTime":`À la main : {s} s`,"ship.recall.go":`Vers le Centre`,"ship.recall.wait":`Vers le Centre · {s} s`,"hud.craftQueue":`File de fabrication : {n}. Ouvrir l’inventaire`,"hud.craftMore":`…+{n}`,"hud.swarm.raid":`Base attaquée · {n}`,"toast.raid":`L’Essaim ronge la base ! Le badge de l’Essaim mène à l’endroit — tourelles et réparation.`,"toast.nestRage":`La reine est furieuse : plus de gardes, et plus rapides.`,"settings.raidAlarm":`Alerte de raid`,"settings.raidAlarm.full":`Complète`,"settings.raidAlarm.edge":`Bord de l’écran`,"settings.raidAlarm.off":`Badge seulement`,"guide.via.tool-more":`Touchez « Plus » (les trois points dans la colonne de droite) — le bouton s’y trouve.`,"guide.via.tool-inventory":`Ouvrez l’« Inventaire » — ce qu’il faut est dans sa fenêtre.`,"guide.via.tool-lab":`Ouvrez le Centre — le bouton est dans sa fenêtre.`,"guide.via.tool-ship":`Ouvrez la fenêtre « Vaisseau » — tout y est.`,"guide.stuck.place":`Impossible de poser ? Prenez le bâtiment dans la barre du bas et appuyez dans le cadre — la vedette s’approche d’elle-même. Un fantôme rouge : la place est prise ou l’orientation est mauvaise. Plus rien en stock ? Fabriquez-en dans l’« Inventaire ».`,"guide.stuck.fly":`Le repère n’est pas visible ? La flèche au bord de l’écran y mène — suivez la flèche.`,"guide.mine.stuck":`Pas de quartz ? Choisissez les roches bleues de la ceinture juste à côté du repère — la vedette doit être près d’elles.`,"guide.recipe.stuck":`La fenêtre ne s’ouvre pas ? Appuyez sur « Observer », puis sur le polissoir — « Lentille » est dans la liste de sa fenêtre.`,"guide.hab.stuck":`Le module est trop loin ? Approchez-vous : le rayon répare à {reach} cases. La fenêtre du module s’ouvre d’un toucher en mode « Observer ».`,"guide.ship-shot.stuck":`Pas de météorite à proximité ? Il en traverse le système toutes les deux ou trois minutes — approchez-vous de la roche claire la plus proche, et le laser tire de lui-même.`,"goal.partDone":`Fait : {part}. Ensuite — {next} : {have}/{need}.`,"goal.obsidian.part":`Le harpon près des roches orange a attrapé une roche`,"goal.plates.part":`Un quatrième harpon — sortie vers le polissoir à plaques`,"cryo.ask.crack":`La capsule n°\xA0{n} est fissurée — volez jusqu’au module et réparez-le au rayon.`,"cryo.ask.reserve":`La réserve de froid de la baie est sous la moitié — donnez aux dormeurs de la lumière azur et de la glace.`,"cryo.ask.ice":`Glace pour {min} min dans la baie — apportez de la glace (météorites, comètes).`,"guide.aside":`Radio`,"guide.aside.next":`Touchez pour continuer`,"goal.obsidian.stuck":`Pas de plaques ? Ouvrez le polissoir à plaques : la recette est « Plaque d’obsidienne » ; l’icône au-dessus de la machine indique ce qui manque — la lumière (un arc et un lumiduc) ou la roche (la sortie du harpon directement dedans).`,"goal.plates.stuck":`Les plaques arrivent lentement ? Le polissoir à plaques a besoin de {light} ph/s de lumière — lancez un arc de plus ; le quatrième harpon, sortie collée directement contre lui.`,"guide.via.close":`Fermez la fenêtre (la croix) — ce qu’il faut est dessous.`,"logbook.scene.embers":`Les braises`,"logbook.scene.umbrella":`L’ombrelle`,"logbook.scene.night":`La nuit des Jumeaux`,"logbook.scene.veil":`D’elle-même`,"logbook.scene.count":`Le décompte`,"logbook.scene.forge":`La Forge`,"logbook.now.embers":`Cinq braises : trois de « Première Lumière », vieilles de deux cent douze ans ; deux jeunes, de huit ans, traces du « Strizh ».`,"logbook.now.umbrella":`Saphir. Dans la ceinture, le givre forme un réseau : l’Essaim tient de l’ombre sur la géante bleue pour qu’elle brûle plus longtemps. Le chalut prend en bordure — juste ce qu’il faut aux radiateurs.`,"logbook.now.night":`Les Jumeaux. La première nuit passée sur les accumulateurs. Sonia a demandé à sa mère pourquoi elle l’avait envoyée : « Pour que tu aies un matin. » Ensuite : les spectres sous deux étoiles.`,"logbook.now.veil":`Le Voile. Le quartz tiré du brouillard arrive. L’étoile est morte ici d’elle-même, sans coupable ; de nouvelles étoiles naîtront de sa brume. Ensuite : lentilles et spectres sans sol ferme.`,"logbook.now.count":`Pulsar de Kepler. Le pouls a des trous : l’Essaim de nombreuses étoiles y règle ses motifs, et chaque trou est un jardin qui ne répond plus. Vera en a compté trois ; ORA, cent douze.`,"logbook.now.forge":`Horizon. La Forge près du trou noir a été bâtie par ceux qui allumaient les étoiles par la force — et elle s’est fendue. Les sept classes sont réunies ; les reliques sont les motifs des jardins. Une étoile s’allume en demandant : trois reliques, sept spectres et de l’antilumière.`,"logbook.slogs":`Journaux de Vera trouvés dans ce système : {n} sur {total}. Les bouées brillent en bleu — approchez tout près.`,"landmark.buoy":`BOUÉE`,"goal.twin_night.stuck":`Tout s’éteint la nuit ? Une cellule de lumière se place entre le récepteur et les machines et garde une seule couleur. Un « N s » rouge dans le panneau « Jour » signifie que la réserve ne suffira pas : ajoutez une cellule.`,"goal.twin_relic.stuck":`{n} le jour, mais moins à la fin de la nuit ? Les lignes de spectres manquent de cellules de lumière — regardez « N s » dans le panneau « Jour ».`,"hud.day":`Jour`,"hud.day.star.twin_amber":`Ambrée`,"hud.day.star.twin_blue":`Bleue`,"hud.day.night":`Nuit`,"hud.day.toNight":`coucher dans {t}`,"hud.day.toStar":`{star} dans {t}`,"hud.day.toDawn":`aube dans {t}`,"hud.cells":`Cellules`,"hud.cells.for":`{color} — {s} s`,"hud.cells.filling":`{color} — en charge`,"hud.cells.short":`ne tiendra pas jusqu’au lever`,"hue.0":`sans couleur`,"hue.1":`écarlate`,"hue.2":`émeraude`,"hue.3":`ambre`,"hue.4":`azur`,"hue.5":`pourpre`,"hue.6":`turquoise`,"hue.7":`blanc`,"cell.charge":`Charge {n} / {cap} ph`,"cell.out":`Fournit {f} ph/s — tient {s} s`,"cell.idle":`En charge : rien en aval ne prend de lumière`,"cell.hue":`Mémorise la couleur : {color}`,"cell.hue.none":`Pas encore de couleur — prendra la première qui arrive`,"cell.forget":`Oublier la couleur`,"hud.cells.chip":`cellules {s} s`,"bonus.ship_damage":`+{v} % de dégâts des armes du vaisseau`,"bonus.ship_power":`+{v} % de rendement du générateur du vaisseau`,"bonus.turret":`+{v} % de dégâts des tourelles`,"bonus.hull":`+{v} % d’intégrité des bâtiments`,"bonus.barrier":`+{v} % d’intégrité des barrières`,"bonus.ammo":`+{v} % de dégâts des balles et roquettes`,"bonus.beam":`+{v} % de dégâts des tourelles à rayon`,"bonus.repair":`+{v} % de vitesse de réparation`,"bonus.dome":`+{v} % de capacité du dôme-bouclier`,"bonus.chain":`+{n} cibles pour l’arc en chaîne`,"bonus.orbital":`+{v} % de dégâts des tourelles orbitales`,"bonus.radar":`+{v} % de préavis du radar`,"bonus.lore":`+{v} % de dégâts sur la couleur vulnérable`,"cryo.putIce":`Mettre de la glace ({n})`,"machine.putHalf":`Moitié`,"hint.prism.16":`Une sortie libre éclaire le vide — c’est de l’éblouissement, et ses voisins de réseau manquent de blanc. Branchez un lumiduc sur chaque sortie ou collez-y une machine (ou un absorbeur) par son entrée.`,"toast.shieldLow":`Bouclier faible — éloignez-vous de la grêle et de l’Essaim !`,"status.prism.16":`Perd de la lumière : sortie libre`,"goal.lab2.part":`Du Reflet au Centre par une ligne (pas à la main)`,"goal.catapult.part":`Premier arc lancé`,"toast.damaged":`L’Essaim a endommagé des bâtiments : {n}. Les chaînes qui en dépendent vont s’arrêter.`,"toast.damagedFix":`Réparer le plus proche`,"goal.asks.more":`{n} demandes de plus — touchez la carte`,"hud.cryo.lead":`Cryo : glace pour {m} min`,"hud.cryo.alarm":`Cryo : alerte capsule !`,"toast.cryoLow":`Baie cryo : du froid pour {m} min. Mettez de la glace — ou amenez une pince avec de la glace directement dans la baie.`,"toast.cryoOpen":`Ouvrir la baie`,"hotbar.groups":`Groupes de bâtiments`,"hotbar.group.logic":`Logique`,"hotbar.group.fluid":`Lumière liquide`,"hotbar.group.resonance":`Résonance`,"toast.netClash":`Des réseaux de couleurs différentes fusionneraient ici — interférence, et les deux s’arrêtent. Laissez une case vide entre eux.`,"guide.lay-tunnel.reverseRemove":`Le gravitapis va dans le mauvais sens. Prenez « Démolir », retirez-le et retracez-le — depuis le bord du cadre côté harpons.`,"lab.reading":`Lecture de l’unité {k}/{n} · encore {s} s`,"lab.waitingLab":`En attente de spectres : chaque Centre a besoin d’une unité complète — un de chaque palier. Apportez la science ou reliez le Centre par une ligne : gravitapis et pince.`,"lab.asked":`Accepté : {tech} — le Centre s’y met…`,"toast.researchStart":`Recherche lancée : {tech}`,"toast.researchOpen":`Centre`,"map.title":`Carte du système`,"key.map":`Carte du système`,"map.layers":`Calques de la carte`,"map.layer.swarm":`Essaim`,"map.layer.base":`Base`,"map.layer.planets":`Planètes`,"map.layer.logs":`Journaux`,"map.layer.wrecks":`Épaves`,"map.layer.tunnels":`Gravitapis`,"map.hint":`Glissez avec la souris, zoomez avec la molette ; cliquez pour choisir un endroit.`,"map.far":`{n} cases de la vedette`,"map.fog":`inexploré — allez-y ou posez un radar`,"map.fly":`Y aller`,"map.center":`Vers la vedette`,"map.zoomIn":`Zoom avant`,"map.zoomOut":`Zoom arrière`,"compass.fog":`dans le brouillard`,"compass.fogHint":`Inexploré : allez-y — la vedette dissipe le brouillard — ou construisez un radar. Touchez pour y aller.`,"goal.radar":`Radar : le brouillard recule`,"goal.radar.why":`Au-delà des ceintures lointaines, c’est le brouillard : des nids de l’Essaim et des planètes où des colons vivront peut-être un jour. Le radar veille pour vous et voit les vagues plus tôt.`,"goal.radar.hint":`Recherchez le « Radar » au Centre (branche « Défense », spectre K) et posez-le en bordure de base. La lumière : par lumiduc ou tout contre la sortie d’un récepteur — le radar dissipe le brouillard sur {sight} cases alentour. Tout le système est sur la carte (bouton « Carte du système »).`,"goal.radar.done":`Le radar surveille le brouillard — nids et vagues apparaissent plus tôt.`,"goal.radar.part":`Radar alimenté`,"map.hint.touch":`Glissez du doigt, pincez pour zoomer ; touchez pour choisir un endroit.`,"swarm.look":`Le signe sur le dos des gardes donne la couleur de la vague : triangle — écarlate, cercle — émeraude, losange — azur. La lumière des lumiducs porte les mêmes formes.`,"ship.hull.4":`Faux`,"ship.hull.5":`Zénith`,"ship.class.1":`Éclaireur`,"ship.class.2":`Intercepteur`,"ship.class.3":`Frégate`,"ship.class.4":`Corsaire`,"ship.class.5":`Vaisseau amiral`,"ship.line.beam":`Rayon`,"ship.line.kinetic":`Cinétique`,"ship.line.star":`Étoile`,"ship.line.depths":`Profondeurs`,"ship.line.wing":`Aile`,"ship.line.beam.bonus":`énergie par tir −{p} %`,"ship.line.kinetic.bonus":`chargeur +{p} %`,"ship.line.star.bonus":`rendement du générateur +{p} %`,"ship.line.star.bonus2":`rendement du générateur +{p} %, chaleur −{h} %`,"ship.line.depths.bonus":`rendement des corps +{p} %, collecte +{c} cases`,"ship.line.wing.bonus":`dégâts du drone +{p} %, réparation +{r} %`,"ship.tab.ship":`Vaisseau`,"ship.tab.stats":`Stats`,"ship.tab.grow":`Progression`,"ship.tab.look":`Apparence`,"ship.slot.locked":`Débloqué par la coque {hull}`,"ship.empty.hint":`Compatible :`,"ship.empty.craft":`{name} — à fabriquer dans l’inventaire ou avec un assembleur`,"ship.empty.tech":`{name} — débloqué par « {tech} »`,"ship.main.damage":`Dégâts par Mk`,"ship.main.speed":`Vitesse par Mk`,"ship.main.shield":`Bouclier par Mk`,"ship.main.output":`Rendement par Mk`,"ship.main.collect":`Collecte par Mk`,"ship.main.mine":`Extraction par Mk`,"ship.main.warn":`Détection par Mk`,"ship.main.escort":`Dégâts du drone par Mk`,"ship.main.repair":`Réparation par Mk`,"ship.main.heat":`Chaleur par Mk`,"ship.main.recall":`Recharge par Mk`,"ship.main.battery":`Batterie par Mk`,"ship.unit.damage":`{v, number}`,"ship.unit.speed":`{v, number} cases/s`,"ship.unit.shield":`{v, number}`,"ship.unit.output":`{v, number} E/s`,"ship.unit.collect":`{v, number} cases`,"ship.unit.mine":`{v, number} %`,"ship.unit.warn":`×{v, number}`,"ship.unit.escort":`{v, number}`,"ship.unit.repair":`{v, number} %`,"ship.unit.heat":`−{v, number} %`,"ship.unit.recall":`{v, number} s`,"ship.unit.battery":`+{v, number} E`,"ship.group.move":`Déplacement`,"ship.group.move.by":`Modifié par : le moteur et sa marque, le rang de la coque.`,"ship.group.shield":`Bouclier`,"ship.group.shield.by":`Modifié par : le bouclier et sa marque, un dissipateur, le rang de la coque, un ensemble double « Étoile ». Chaleur, impact et morsure : la part des dégâts.`,"ship.group.energy":`Énergie`,"ship.group.energy.by":`Modifié par : le générateur, une batterie, le rang de la coque, les ensembles « Étoile » et « Rayon ».`,"ship.group.weapons":`Armes`,"ship.group.weapons.by":`Modifié par : les armes et leurs marques, le rang de la coque, les recherches de dégâts, les ensembles « Rayon » et « Cinétique ».`,"ship.group.mine":`Extraction`,"ship.group.mine.by":`Modifié par : le laser minier, la soute, l’ensemble « Profondeurs ».`,"ship.group.utils":`Utilitaires`,"ship.group.utils.by":`Modifié par : le scanner, le réparateur, la balise de rappel, l’ensemble « Aile ».`,"ship.group.sets":`Ensembles de gamme`,"ship.sets.none":`Aucun ensemble : des modules d’une même gamme dans divers emplacements donnent un bonus.`,"ship.sets.next":`en ensemble : {b}`,"ship.sets.rule":`{a} modules d’une même gamme forment un ensemble, {b} un ensemble double ; les deux meilleurs s’appliquent.`,"ship.gun.escort":`Drone d’escorte`,"ship.gun.line":`dég. {d, number} · {r, number} tirs/s · {range} cases · {dps, number}/s`,"ship.stat.accel":`Accélération`,"ship.stat.boost":`Poussée, ×`,"ship.stat.regenDelay":`Délai du bouclier, s`,"ship.stat.heat":`Chaleur, %`,"ship.stat.kinetic":`Impact de roche, %`,"ship.stat.dark":`Morsure de l’Essaim, %`,"ship.stat.guns":`Canons`,"ship.stat.nest":`Contre les nids, %`,"ship.stat.mine":`Vitesse d’extraction, %`,"ship.stat.yield":`Rendement des corps, %`,"ship.stat.sight":`Détection, cases`,"ship.stat.repair":`Réparation, %`,"ship.stat.recall":`Rappel, s`,"ship.grow.line":`Gamme de coques`,"ship.grow.current":`actuelle`,"ship.grow.slots":`Emplacements : {n}`,"ship.grow.slot":`Nouvel emplacement {n} : {slot}`,"ship.grow.tech":`Technologie {tech} :`,"ship.grow.done":`recherchée`,"ship.grow.open":`disponible`,"ship.grow.locked":`prérequis manquants`,"ship.grow.toTree":`Vers l’arbre`,"ship.grow.max":`Le sommet de la gamme — votre vaisseau amiral est complet.`,"ship.tasks.tier":`Tâches de la coque {hull}`,"ship.trait.base":`Éclaireur léger : rapide à construire, peu de place pour les modules.`,"ship.trait.move":`vitesse +{p} %`,"ship.trait.accel":`accélération +{p} %`,"ship.trait.boost":`poussée {p} % moins chère`,"ship.trait.capacity":`bouclier +{p} %`,"ship.trait.range":`portée des armes +{c} cases`,"ship.trait.damage":`dégâts +{p} %`,"ship.trait.battery":`batterie +{p} %`,"ship.trait.nest":`contre nids et ruches +{p} %`,"ship.trait.main":`vitesse, bouclier, rendement et dégâts +{p} %`,"ship.trait.sets":`un ensemble dès {a} modules, un double dès {b}`,"ship.task.set":`Formez un ensemble : {n} modules d’une même gamme`,"ship.task.slotsFull":`Remplissez tous les emplacements`,"ship.task.coreMark2":`Les {n} modules de base en Mk II`,"ship.task.set2":`Deux ensembles à la fois`,"ship.task.mark3":`Un module Mk III`,"ship.task.nest":`Détruisez un nid ou une ruche avec les armes du vaisseau`,"ship.task.loadout":`Enregistrez une configuration`,"ship.task.set5":`Un ensemble double`,"ship.task.allMark3":`Tous les emplacements en Mk III`,"ship.task.name":`Nommez votre vaisseau`,"ship.look.paint":`Peinture`,"ship.look.trim":`Finition`,"ship.look.pattern":`Motif`,"ship.look.flame":`Flamme des tuyères`,"ship.look.name":`Nom du vaisseau`,"ship.look.name.ph":`Sans nom`,"ship.look.name.save":`Nommer`,"ship.flame.engine":`Selon le moteur`,"ship.flame.1":`Cyan`,"ship.flame.2":`Orange`,"ship.flame.3":`Magenta`,"ship.flame.4":`Vert`,"ship.flame.5":`Violet`,"ship.flame.6":`Or`,"ship.paint.steel":`Acier`,"ship.paint.graphite":`Graphite`,"ship.paint.crimson":`Cramoisi`,"ship.paint.cobalt":`Cobalt`,"ship.paint.jade":`Jade`,"ship.paint.bronze":`Bronze`,"ship.paint.violet":`Violette`,"ship.paint.ivory":`Ivoire`,"ship.color.0":`Cyan`,"ship.color.1":`Ambre`,"ship.color.2":`Magenta`,"ship.color.3":`Vert`,"ship.color.4":`Violet`,"ship.color.5":`Écarlate`,"ship.color.6":`Or`,"ship.color.7":`Blanc chaud`,"ship.pattern.none":`Aucun`,"ship.pattern.stripes":`Bandes`,"ship.pattern.chevrons":`Chevrons`,"ship.pattern.blade":`Lame`,"ship.pattern.teeth":`Crocs`,"ship.pattern.sunedge":`Bord solaire`,"ship.loadouts":`Configurations`,"ship.loadouts.locked":`Les configurations s’ouvrent avec la coque {hull}, quand le choix apparaît.`,"ship.loadout.n":`Configuration {n}`,"ship.loadout.empty":`vide`,"ship.loadout.missing":`manquant : {n}`,"ship.loadout.save":`Enregistrer`,"ship.loadout.apply":`Appliquer`,"ship.upgrade":`Nouvelle coque : {cls} {hull}`,"ship.upgrade.more":`{slot} · {trait}`,"ship.sets.idle.wing":`inactif : il faut un drone d’escorte ou un réparateur`,"ship.sets.idle.kinetic":`inactif : il faut une arme à munitions`,"ship.sets.idle.beam":`inactif : il faut une arme à énergie`,"ship.sets.idle.star":`inactif`,"ship.sets.idle.depths":`inactif`,"ship.look.trail":`Traînée`,"ship.trail.same":`Comme la flamme`,"ship.grow.state.cur":`actuelle`,"ship.grow.state.done":`franchie`,"ship.grow.state.next":`disponible`,"ship.grow.state.locked":`verrouillée`,"tech.extraCost":`{item} : {have} sur {need} — prélevés à la mise en file`,"tech.extraCost.where":`Seules les comètes portent des noyaux, et elles passent rarement : brisez une comète et ramassez l’éclat lumineux.`,"tech.extraCost.short":`Requiert {item} ×{need}, vous en avez {have}. Les comètes passent rarement — brisez-en une et récupérez son noyau.`,"comet.toast":`Une comète ! Brisez-la — son noyau contient une ressource rare pour les coques de vaisseau.`,"saves.failed":`Sauvegarde échouée — nouvel essai`,"saves.restored":`La dernière sauvegarde était endommagée — monde restauré depuis {from}, {min} min de jeu plus tôt`,"saves.unreadable":`Les sauvegardes de ce monde sont illisibles. Le monde n’a pas été supprimé : une version mise à jour du jeu pourra peut-être les lire.`,"saves.kind.auto":`Auto`,"saves.kind.pause":`À la sortie`,"saves.kind.manual":`Manuelle`,"saves.kind.backup":`Secours`,"saves.title":`Sauvegardes`,"saves.open":`Sauvegardes du monde`,"saves.load":`Charger`,"saves.loadTitle":`Charger cette sauvegarde ?`,"saves.loadText":`Le monde reviendra à « {slot} » ({time} de jeu). L’état actuel restera en sauvegarde auto.`,"saves.delete":`Supprimer la sauvegarde`,"saves.deleteText":`Supprimer la sauvegarde manuelle « {time} » ?`,"saves.empty":`Aucune sauvegarde`,"saves.hint":`Sauvegarde auto toutes les {sec} s, {n} en rotation. « À la sortie » — quand le jeu passe en arrière-plan. Manuelles — bouton « Sauvegarder », jusqu’à {max}.`,"saves.export":`Exporter le monde`,"saves.import":`Importer un monde`,"saves.exported":`Fichier du monde prêt`,"saves.exportFailed":`Impossible d’exporter le monde`,"saves.imported":`Monde « {name} » ajouté`,"saves.importFailed":`Ce n’est pas un fichier de monde Starwarden, ou il est endommagé`,"saves.importLegacy":`Monde d’une très ancienne version (avant les ceintures et les spectres) — non pris en charge`,"saves.importName":`{name} (importé)`,"saves.status.ago":`Sauvegardé · {ago}`,"saves.status.saving":`Sauvegarde…`,"saves.status.failed":`Non sauvegardé`,"saves.status.never":`Pas encore sauvegardé`,"saves.cloud.on":`Copie dans le cloud · {ago}`,"saves.cloud.over":`Pas de copie cloud — espace insuffisant`,"saves.cloud.conflictTitle":`Deux versions du monde`,"saves.cloud.conflictText":`« {name} » a été joué ici et sur un autre appareil. Quelle version voulez-vous continuer ? L’autre restera en sauvegarde manuelle.`,"saves.cloud.here":`Cet appareil`,"saves.cloud.other":`Un autre appareil`,"saves.cloud.pick":`Continuer celle-ci`,"saves.cloud.taken":`Sauvegarde cloud reprise — le monde a été continué sur un autre appareil`,"saves.cloud.goals":`objectifs : {n}`,"logbook.scene.threat":`Première menace`,"logbook.now.threat":`Un nid de l’Essaim s’est éveillé dans la ceinture lointaine — des êtres vivants que la lumière vive réveille. Une escouade fonce sur la base. Repoussez-la avec votre vedette.`,"logbook.scene.threat_after":`Après le raid`,"logbook.now.threat_after":`L’escouade est partie. L’Essaim a demandé par la lumière : « QUI ? » Pour l’instant, on répond au laser ; l’archive contient une tourelle, la Lance. D’ici là — une lumière plus régulière : grandir, sans éblouir.`,"logbook.scene.first_wave":`Première vague`,"logbook.now.first_wave":`Le nid a rassemblé une vraie vague. Tourelles sur la cible, la vedette en l’air.`,"logbook.scene.still":`Ceintures vides`,"logbook.now.still":`La lumière de la base a quadruplé. Pas de voisins dans les ceintures — seulement de la roche et de la glace ; nous construisons proprement, par habitude.`,"logbook.scene.seventh":`La septième`,"logbook.now.seventh":`Matveï agite sa tasse au hublot : il s’est porté volontaire pour l’« Ensemencement » — pour voir une étoile vivante.`,"logbook.scene.leg":`La jambe`,"logbook.now.leg":`Matveï refuse qu’on soulève la cloison qui le coince tant que les dormeurs ont besoin de lumière. ORA argumente avec lui, procédure à l’appui.`,"logbook.scene.colors":`Premières couleurs`,"logbook.now.colors":`Le prisme a décomposé la lumière en écarlate, émeraude et azur. Au Havre, la lumière est rationnée et la couleur se donne sur bon ; ici, la lumière abonde, et la couleur devient un outil. L’ambre, nous le mélangerons nous-mêmes.`,"logbook.scene.dark_ring":`L’anneau sombre`,"logbook.now.dark_ring":`Au-delà de la ceinture extérieure — un immense anneau strié comme un filetage. Pas à nous, très ancien. Laissons-le là pour l’instant.`,"logbook.scene.amber":`L’ambre`,"logbook.now.amber":`La première couleur faite de nos mains — l’ambre, la charge de la Lance. Matveï connaît la recette de la Lance par cœur et tripote sa plaque.`,"logbook.scene.twelve":`Douze semeurs`,"logbook.now.twelve":`Le journal de l’« Ensemencement » : douze semeurs, l’« Hirondelle » est la septième ; des autres, pas un mot.`,"logbook.scene.erased":`L’étoile effacée`,"logbook.now.erased":`Ni l’expédition « Première Lumière » ni cette étoile ne figurent au catalogue de l’Institut — on les a effacées. Vera Lund a trouvé quelque chose.`,"logbook.scene.first_spectrum":`Premier spectre`,"logbook.now.first_spectrum":`Le Centre a lu la classe M — le premier des sept verrous de l’archive. L’étoile a cligné deux secondes après la lecture. ORA parle encore de coïncidence.`,"logbook.scene.tags":`Les étiquettes`,"logbook.now.tags":`ORA a relu les étiquettes des quarante capsules. Nº 17 — Sonia Vent, seize ans, fille de Mira, régulatrice au Havre.`,"logbook.scene.course":`Le cap`,"logbook.now.course":`Matveï a demandé comment l’« Hirondelle » avait manqué Claire. Pour la première fois, ORA a dit : « Je… vais recalculer. »`,"logbook.scene.spear":`La Lance`,"logbook.now.spear":`La Lance est en place — première défense de la base. Matveï sait où frapper : « sous le troisième segment ». D’où il le sait — « lu quelque part ».`,"logbook.scene.eyes":`Les yeux`,"logbook.now.eyes":`Sonia voit une couleur que les caméras ne captent pas : elle est tétrachromate. ORA vérifie ses dessins — on dirait que Sonia voit davantage.`,"logbook.scene.shell2":`La voix du Havre`,"logbook.now.shell2":`L’Enveloppe II nous a donné de la puissance — la voix de Mira arrive plus nette, mais elle ne nous entend pas. Il faut un faisceau vers chez nous — la Fibre longue.`,"logbook.scene.grandpa":`Grand-père`,"logbook.now.grandpa":`Sonia a appelé Matveï « grand-père » pour la première fois. Ça lui a plu.`,"logbook.scene.withdrawn":`Je finis de compter`,"logbook.now.withdrawn":`ORA s’est plongée une minute dans ses calculs : le Spectre G a décomposé les répétitions dans la lumière de l’étoile. Elle a promis de dire quelque chose d’important — « pas maintenant ».`,"logbook.scene.hunter":`Le chasseur`,"logbook.now.hunter":`Matveï connaît les nids mieux que les archives d’ORA. Sonia l’a remarqué ; il a promis de raconter — pas aujourd’hui.`,"logbook.scene.refusal":`Le refus`,"logbook.now.refusal":`Les notes de Vera : elle a refusé de brûler les nids et a renvoyé son équipage chez lui. L’Institut a caché son rapport n°\xA07.`,"logbook.scene.rhythm":`Rythme`,"logbook.now.rhythm":`Le Spectre F, c’est le rythme. L’étoile, les nids et le carnet de Sonia ont un seul et même rythme. Elle montrera le carnet quand elle sera sûre.`,"logbook.scene.name":`Le nom`,"logbook.now.name":`L’Essaim se souvient du nom de Vera depuis plus de deux cents ans. « Notre façon de briller, c’est ce dont ils se souviendront », dit ORA.`,"logbook.scene.yes":`Oui`,"logbook.now.yes":`Première conversation : l’Essaim a demandé en lumière « OUI ? », Sonia a répondu avec une lampe — phase π. « OUI ».`,"logbook.scene.tea":`Le thé`,"logbook.now.tea":`Sonia a apporté du thé à Matveï. « Tout le monde savait que les nids s’éteignaient — simplement, personne ne regardait. » Maintenant, il regarde.`,"logbook.scene.clear_word":`Claire`,"logbook.now.clear_word":`Dans le catalogue de l’Institut, « claire » figure à côté des systèmes où est passée la campagne sanitaire. ORA commence à regarder quelles étoiles pâlissent.`,"logbook.scene.mom_words":`Que dire à maman`,"logbook.now.mom_words":`Sonia répète sa première phrase pour la Fibre longue. Elle a choisi : « Confirmé : vivante. »`,"logbook.scene.trust":`Confiance`,"logbook.now.trust":`ORA apprend à distinguer ce qu’elle doit décider seule de ce qu’elle doit demander. « C’est plus difficile que les spectres. »`,"logbook.scene.rehearsal":`Répétition`,"logbook.now.rehearsal":`Matveï cherche les mots pour parler de Claire à Mira. Sonia en est sûre : sa mère comprendra à demi-mot.`,"logbook.scene.green":`Verte`,"logbook.now.green":`Matveï se souvient de Claire verte, pleine de petits feux — une semaine, le temps des brûlis. Sonia la dessinera verte.`,"logbook.scene.phase":`Phase`,"logbook.now.phase":`Spectre B — la phase : un décalage de pi, c’est « oui » ; sans décalage, juste de la lumière. On peut demander la permission à l’Essaim. La Fibre longue est presque prête.`,"logbook.scene.before":`Avant la liaison`,"logbook.now.before":`Encore quelques pas avant la liaison avec le Havre. Sonia a peur ; ORA a plaisanté pour la deuxième fois — c’est validé.`,"logbook.scene.ration":`La ration`,"logbook.now.ration":`Le Havre a réduit la ration à trois heures de lumière par jour. Le Foyer s’éteint — il faut la Fibre longue au plus vite.`,"logbook.scene.after_channel":`Après le canal`,"logbook.now.after_channel":`Mira et Sonia se sont parlé. L’« Exode » est en vie auprès de Claire, qui pâlit. Le Havre saura bientôt la vérité sur l’Extinction.`,"logbook.scene.hive":`La ruche`,"logbook.now.hive":`La première ruche est libre. Il y a de la terre pour l’« Exode » ; l’Essaim viendra voir le nouveau jardin — et se souviendra de la façon dont il a été pris.`,"logbook.scene.gardeners":`Les Jardiniers`,"logbook.now.gardeners":`Les ruches sont les jardins des Jardiniers, les ceintures — leurs plates-bandes. Nous sommes dans le jardin d’autrui ; la terre se demande, comme une autorisation d’atterrir.`,"logbook.scene.land":`La terre`,"logbook.now.land":`Une telle planète peut accueillir tout l’« Exode ». Mais d’abord — le portail.`,"logbook.scene.cut":`Le canal vide`,"logbook.now.cut":`Le canal est vide depuis trois jours. Sonia attend près de la console ; ORA garde le canal ouvert.`,"logbook.scene.road":`La route`,"logbook.now.road":`Mira est de retour sur les ondes — depuis sa cuisine. L’anneau au-delà de la ceinture extérieure est une route qui existe déjà. Le cœur se pose en premier.`,"logbook.scene.ask":`Demander`,"logbook.now.ask":`L’anneau s’ouvre par consentement. Matveï part vers le nid sans lance — pour demander.`,"logbook.scene.kuznets":`Les Forgerons`,"logbook.now.kuznets":`Les Forgerons ont bâti l’anneau pour essorer les étoiles. Il a été arrêté deux fois — par eux-mêmes et par Vera. Nous ne l’allumons pas — nous lui demandons de s’ouvrir.`,"logbook.scene.return":`Le retour`,"logbook.now.return":`Matveï est revenu du nid. La réponse qu’il a reçue dépend de la façon dont brille la base.`,"logbook.scene.kitchen":`La cuisine`,"logbook.now.kitchen":`L’Institut a coupé le courant chez Mira ; les voisins apportent leurs rations. Autour de sa cuisine, le Havre découvre du nouveau.`,"logbook.scene.ring_closed":`L’anneau est fermé`,"logbook.now.ring_closed":`Douze segments sur douze — l’anneau tient. Mira calcule la route du retour. Reste le champ : quatre stabilisateurs — quatre mots.`,"logbook.scene.four_words":`Quatre mots`,"logbook.now.four_words":`Les stabilisateurs tiennent la phrase « étoile — à vous — maintenant — oui » : le portail demande la permission de s’ouvrir.`,"logbook.scene.field":`Le champ`,"logbook.now.field":`Le champ tient, les stabilisateurs sont en phase. L’anneau interroge l’Essaim, l’Essaim nous interroge.`,"logbook.scene.exodus_wait":`L’« Exode » attend`,"logbook.now.exodus_wait":`Près de Claire, six heures de lumière par jour. Le capitaine de l’« Exode » : « Ne vous pressez pas — mais ne traînez pas non plus. »`,"logbook.scene.unknown":`Ne pas savoir`,"logbook.now.unknown":`ORA ne sait pas ce qu’elle fera après le portail. C’est nouveau pour elle — et il n’y a pas de procédure.`,"logbook.scene.key_beam":`La clé`,"logbook.now.key_beam":`La clé du portail, ce sont les sept classes dans un seul rayon : tout ce qui a été lu depuis le premier arc.`,"logbook.scene.fear":`La peur d’ORA`,"logbook.now.fear":`ORA a peur de se tromper sur ce qui ne se calcule pas. Elle a décidé : elle demandera, au lieu de décider pour tous.`,"logbook.scene.last_tea":`Le dernier thé`,"logbook.now.last_tea":`Des toasts avant la montée en régime : aux vivants, aux dormeurs, à Vera, à maman, à la Sentinelle.`,"logbook.scene.stand":`C’est beau`,"logbook.now.stand":`L’anneau monte en régime. Tous les trois sont d’accord : c’est beau.`,"logbook.scene.ridge_children":`Les enfants`,"logbook.now.ridge_children":`Les braises vivront des milliards d’années : pas seulement des tombes — des enfants. Deux sont plus jeunes que le quart de Nina.`,"logbook.scene.ridge_doubt":`Le premier doute`,"logbook.now.ridge_doubt":`Ici, Vera a douté d’un ordre pour la première fois. Matveï avait jadis détourné les yeux de son propre « premier », et pour Nina il est passé sans elle.`,"logbook.scene.ridge_hope":`L’enseignante`,"logbook.now.ridge_hope":`Sur ses cartes, Mira a corrigé la naine rouge « inutile » en « enseignante » : le Foyer a de qui apprendre.`,"logbook.scene.sap_arrive":`Arrivée à Saphir`,"logbook.now.sap_arrive":`Saphir : une géante bleue, deux fois plus de lumière et de chaleur. Ici, le froid est la cargaison la plus précieuse ; au-delà de la ligne des glaces s’étend une ceinture de givre.`,"logbook.scene.sap_heat":`La chaleur`,"logbook.now.sap_heat":`L’équipe sanitaire de « Première Lumière » n’a pas supporté la chaleur, tandis que Vera regardait le givre : « posé comme des tuiles ».`,"logbook.scene.sap_measure":`La mesure`,"logbook.now.sap_measure":`Nous prenons le givre sur le bord — juste assez pour que le motif de l’ombrelle reste intact. ORA compte chaque cellule.`,"logbook.scene.sap_fallen":`Ce qui tombe`,"logbook.now.sap_fallen":`La règle de Saphir : ce qui tombe est à nous, ce qui pousse est à eux. La poussière de givre se prend sans demander.`,"logbook.scene.sap_mom":`Le bonnet`,"logbook.now.sap_mom":`Mira a dit à Sonia de manger et de mettre un bonnet. Contre la chaleur. Les géantes attendront.`,"logbook.scene.sap_mend":`On raccommode`,"logbook.now.sap_mend":`L’Essaim raccommode l’ombrelle là où nous avons pris du givre. En échange, il lui faut une lumière égale, sans éblouissement.`,"logbook.scene.twins_arrive":`Arrivée aux Jumeaux`,"logbook.now.twins_arrive":`Les Jumeaux : une étoile ambrée et une bleue qui se partagent un même jour. La nuit est courte mais bien réelle — il faudra stocker la lumière.`,"logbook.scene.twins_mix":`Le ciel mélange`,"logbook.now.twins_mix":`Toute sa vie, Mira a mélangé la lumière des lampes pour donner aux couloirs un « presque jour ». Ici, c’est le ciel qui mélange le jour.`,"logbook.scene.twins_sorry":`La Couleur en trop`,"logbook.now.twins_sorry":`Mira a vu les dessins de Sonia et lui a demandé pardon : la couleur en trop n’est pas une invention.`,"logbook.scene.twins_dusk":`Avant la nuit`,"logbook.now.twins_dusk":`Les deux étoiles se couchent. Cette nuit, Sonia posera à sa mère la question essentielle.`,"logbook.scene.twins_morning":`Un matin à deux`,"logbook.now.twins_morning":`Pour la première fois de sa vie, Mira a vu une aube — par les yeux de sa fille. L’enregistrement sera montré dans les couloirs du Havre.`,"logbook.scene.veil_arrive":`Arrivée au Voile`,"logbook.now.veil_arrive":`Le Voile : pas de sol ferme, seulement une brume glacée autour du noyau. Nous récolterons le quartz dans le brouillard. Qui a ôté sa robe à l’étoile — on l’ignore encore.`,"logbook.scene.veil_layers":`Les strates`,"logbook.now.veil_layers":`La brume est la chronique de l’étoile : strate après strate, des milliers d’années. Aucune trace de feu.`,"logbook.scene.veil_form":`De lumière et de règles`,"logbook.now.veil_form":`ORA est faite de lumière et de règles. L’une d’elles interdisait de contredire le catalogue ; elle l’a enfreinte.`,"logbook.scene.veil_nursery":`La pouponnière`,"logbook.now.veil_nursery":`De nouvelles étoiles naîtront de la brume. Nous construisons dans une pouponnière d’étoiles — et ne prenons de glace que le nécessaire.`,"logbook.scene.veil_honest":`Plus honnête`,"logbook.now.veil_honest":`Matveï a compris : tout ne s’assombrit pas à cause de lui. Pas plus facile — plus honnête.`,"logbook.scene.pulse_arrive":`Arrivée au Pulsar`,"logbook.now.pulse_arrive":`Le Pulsar de Kepler : une étoile morte clignote, toute sa lumière arrive en rythme. Même les morts peuvent briller.`,"logbook.scene.pulse_word":`Un seul mot`,"logbook.now.pulse_word":`Depuis toujours, le pulsar dit un seul mot. L’hypothèse de Sonia : « ici ».`,"logbook.scene.pulse_heal":`Combler un trou`,"logbook.now.pulse_heal":`Un trou dans le décompte, c’est une étoile sans jardin. Si le jardin repousse, l’étoile répondra. Alors, nous planterons.`,"logbook.scene.pulse_address":`Les adresses`,"logbook.now.pulse_address":`Mira montrera le décompte du pulsar sur les ondes du Havre : les cent douze trous sont des adresses.`,"logbook.scene.hz_arrive":`Arrivée à Horizon`,"logbook.now.hz_arrive":`Horizon : un trou noir et un disque incandescent. Près de la base — une ruine plus ancienne que tous les portails humains.`,"logbook.scene.hz_disk":`La lumière de ce qui tombe`,"logbook.now.hz_disk":`Le disque brille de ce qui tombe dans le trou. Nous sommes venus pour ce qui brille longtemps.`,"logbook.scene.hz_vera_joy":`Heureuse`,"logbook.now.hz_vera_joy":`Vera est passée ici au troisième jour de son voyage — et elle était heureuse. Avant les ordres, avant le Berceau.`,"logbook.scene.hz_shadow":`Il faut de l’ombre`,"logbook.now.hz_shadow":`L’antilumière éteint la lumière sans chaleur : pour allumer une étoile, il faut aussi de l’ombre.`,"logbook.scene.hz_cracks":`Trop trempée`,"logbook.now.hz_cracks":`La Forge s’est fendue de l’intérieur — on l’a trop pressée. Nous irons lentement : c’est long, mais c’est entier.`,"logbook.scene.hz_who_goes":`Qui partira`,"logbook.now.hz_who_goes":`Au Havre, on se dispute pour savoir qui partira vers la nouvelle étoile. Le Havre s’est réveillé.`,"logbook.scene.hz_relics":`Calligraphies`,"logbook.now.hz_relics":`Les reliques sont les motifs des jardins, chacun tracé de sa propre main. La Forge les lira comme ORA lit les spectres.`,"logbook.scene.hz_ask_again":`Redemander`,"logbook.now.hz_ask_again":`Demander, ce n’est pas briser : si ça ne marche pas, nous redemanderons. Ce qui est brisé ne se redemande pas.`,"logbook.scene.hz_mom_route":`Sa propre route`,"logbook.now.hz_mom_route":`Pour la première fois, Mira calculera une route pour elle-même — vers la nouvelle étoile.`,"logbook.scene.hz_see_born":`Voir une naissance`,"logbook.now.hz_see_born":`Matveï est venu voir une étoile vivante — et il pourrait bien en voir une naître.`,"logbook.scene.hz_pupils":`Les apprentis`,"logbook.now.hz_pupils":`Nous ne sommes pas des jardiniers — nous sommes des apprentis jardiniers. L’erreur est permise.`,"logbook.scene.hz_remember":`Ils se souviennent de la Forge`,"logbook.now.hz_remember":`L’Essaim se souvient de la Forge telle qu’elle était avant la fissure. Quelqu’un nous attendait ici.`,"logbook.scene.hz_eve":`La Veille`,"logbook.now.hz_eve":`Tout est prêt : les reliques, l’antilumière, le Havre aux oculaires. Il ne reste qu’à demander.`,"swarm.toast.raidGo":`Des Étincelles foncent vers la base ! La vedette à leur rencontre : le laser tire tout seul.`,"swarm.toast.capture":`L’Essaim a pris une planète : sans tourelle orbitale, la ruche repousse. Détruisez-la — et laissez une tourelle en orbite.`,"guide.map-open":`Ouvrons la carte du système : l’étoile, les ceintures, les planètes et les nids de l’Essaim. Le bouton « Carte du système » est dans la colonne de droite [M].`,"guide.map-open.touch":`Touchez « Carte du système » — tout le système s’ouvre : l’étoile, les ceintures, les planètes, les nids de l’Essaim.`,"guide.map-open.why":`Le système est grand : sans la carte, on perd facilement la base de vue et on manque un nid.`,"guide.map-open.stuck":`Pas de « Carte du système » en vue ? Si elle n’est pas dans la colonne de droite, elle est dans « Plus » : le bouton à trois points en bas de la colonne ouvre le reste des outils.`,"guide.map-ship":`La carte s’ouvre sur votre vedette — la flèche bleue au centre, près de l’étoile. Touchez le bouton en surbrillance : il ramène toujours la carte à la vedette. «\xA0+\xA0» et «\xA0−\xA0» en dessous règlent le zoom.`,"guide.map-ship.reopen":`La carte s’est fermée — rouvrez-la avec le bouton « Carte du système » [M].`,"guide.map-fog":`Les zones sombres de la carte sont du brouillard : des endroits encore jamais visités. Il se dissipe partout où passe votre vedette et autour des radars de la base.`,"guide.map-fog.reopen":`La carte s’est fermée — rouvrez-la avec le bouton « Carte du système » [M].`,"guide.map-layers":`En haut, les calques : Essaim, base, planètes, journaux, épaves, gravitapis. Touchez un calque pour le masquer ; touchez-le encore pour le ramener.`,"guide.map-layers.reopen":`La carte s’est fermée — rouvrez-la avec le bouton « Carte du système » [M].`,"guide.map-pick":`Cliquez n’importe où sur la carte — la distance et un bouton « Y aller » apparaissent en bas. Glissez pour déplacer la carte, molette pour zoomer.`,"guide.map-pick.touch":`Touchez n’importe où sur la carte — la distance et un bouton « Y aller » apparaissent en bas. Glissez d’un doigt pour déplacer la carte, pincez pour zoomer.`,"guide.map-pick.reopen":`La carte s’est fermée — rouvrez-la avec le bouton « Carte du système » [M].`,"guide.map-pick.stuck":`Un toucher court, sans glisser, choisit un endroit. Si la carte a bougé, touchez à nouveau sans faire glisser.`,"guide.map-fly":`« Y aller » — et la vedette vole seule jusqu’à cet endroit ; reprenez les commandes à tout moment pour la piloter vous-même. Allez-y maintenant ou plus tard — appuyez alors sur « Suivant ».`,"guide.map-fly.pick":`Choisissez d’abord un lieu : touchez la carte.`,"guide.map-fly.reopen":`La carte s’est fermée — rouvrez-la avec le bouton « Carte du système » [M], ou appuyez sur « Suivant » si le vol n’est pas nécessaire.`,"guide.map-open.more":`Ouvrons la carte du système : l’étoile, les ceintures, les planètes et les nids de l’Essaim. Elle est dans le menu « Plus » — touchez le bouton à trois points en bas de la colonne de droite : le reste des outils s’y trouve.`,"guide.tree.done":`Voilà le chemin — du Prisme jusqu’au dénouement. Revenez-y quand vous voulez.`,"guide.capsule":`Une lumière bleue clignote près de l’épave de l’« Hirondelle » — une vieille balise. Volez jusqu’au repère (WASD), tout près : la vedette ramassera la capsule.`,"guide.capsule.touch":`Une lumière bleue clignote près de l’épave de l’« Hirondelle » — une vieille balise. Dirigez le joystick jusqu’au repère, tout près : la vedette ramassera la capsule.`,"guide.capsule.close":`L’arbre peut attendre : une vieille balise clignote près de l’épave de l’« Hirondelle ». Fermez l’arbre et allez-y.`,"guide.capsule.why":`Le signal est plus vieux que nous. Bien plus vieux. Seule la « Première Lumière » posait de tels feux.`,"guide.capsule.done":`La capsule est à bord. Il y en a peut-être d’autres — elles nous diront ce qu’est devenue la première expédition. Il faudra chercher nous-mêmes : un radar les montrera sur la carte.`,"guide.lay-tunnel.removeHere":`Touchez les gravitapis inversés dans le cadre — « Démolir » les retire. Puis reprenez un gravitapis.`,"guide.capsule.win":`La fenêtre peut attendre : une vieille balise clignote près de l’épave de l’« Hirondelle ». Fermez la fenêtre et filez-y au joystick.`,"journal.title":`Journal de quart`,"journal.away":`dernière fois — {when}`,"journal.last":`Dernier quart`,"journal.open":`Inachevé`,"journal.go":`Au travail`,"journal.gain.none":`Pas encore de nouveau jalon — tout reste à faire.`,"journal.gain.minutes":`{n} min dans le monde`,"journal.gain.goals":`{n, plural, one {# objectif} other {# objectifs}}`,"journal.gain.techs":`{n, plural, one {# technologie} other {# technologies}}`,"journal.gain.arcs":`{n, plural, one {# arc de sphère} other {# arcs de sphère}}`,"journal.gain.awake":`{n, plural, one {# colon réveillé} other {# colons réveillés}}`,"journal.research":`Recherche : {tech}{queue, plural, =0 {} other { · encore # en file}}`,"journal.researchIdle":`Le Centre attend : la file de recherche est vide`,"journal.cryo":`{n, plural, one {# colon peut être réveillé} other {# colons peuvent être réveillés}}`,"settings.journal":`Journal de quart à l’entrée dans un monde`,"menu.next":`Ensuite : {goal}`,"records.first":`Temps : {time}`,"records.best":`Temps : {time} · record {delta}`,"records.slower":`Temps : {time} · meilleur {best}`,"week.title":`Étoile de la semaine`,"week.lead":`Semaine {week} : le même monde pour tous les joueurs, l’histoire par radio. Chronométrez vos jalons et comparez avec vos amis — ils ont le même code du monde.`,"week.locked":`Se débloque après votre premier « Spectre M » dans n’importe quel monde : la course est pour ceux qui connaissent déjà les bases.`,"week.start":`Lancer la course`,"week.continue":`Reprendre`,"week.restart":`Relancer`,"week.restart.text":`Le monde de cette semaine recommence. Vos meilleurs temps restent.`,"week.col.goal":`Jalon`,"week.col.now":`Course`,"week.col.week":`Record de la semaine`,"week.col.best":`Record du Berceau`,"week.note":`L’horloge s’arrête dans les scènes et les menus ; une pause manuelle compte. « Record du Berceau » — mondes sans tutoriel, en standard. Les records restent sur cet appareil.`,"week.share":`Partager le résultat`,"week.shareText":`Starwarden · Étoile de la semaine {week} · {goal} en {time}. Saurez-vous faire mieux ? Code du monde : {code}`,"week.shared":`Résultat copié — envoyez-le à un ami`,"week.worldName":`Étoile de la semaine {week}`,"records.m.spectrum_m":`Spectre M`,"records.m.crown":`Couronne`,"records.m.spectrum_k":`Spectre K`,"records.m.cryo_wake":`Premier colon réveillé`,"records.m.spectrum_g":`Spectre G`,"records.m.spectrum_f":`Spectre F`,"records.m.spectrum_a":`Spectre A`,"records.m.spectrum_b":`Spectre B`,"records.m.gate_jump":`Hyperportail`,"guide.map-ship.done":`La carte est revenue sur la vedette — ce bouton vous sauve dès que vous vous éloignez sur la carte.`,"guide.map-layers.done":`C’est le principe : masquez le superflu, et ce qu’il vous faut se trouve plus facilement.`,"etude.exitMenu":`Au menu principal`,"etude.resume":`Reprendre l’expérience`,"lab.window":`Recherches`,"lab.one":`Centre {n}`,"lab.st.work":`en lecture`,"lab.st.wait":`en attente`,"lab.st.empty":`vide`,"lab.putHere":`Remettre ici`,"goal.cryo.part":`Lumière azur pour les dormeurs`,"goal.cryo.part.2":`Glace dans le module`,"guide.cryo-open":`La Couronne est allumée — j’ai basculé la baie cryo sur la lumière de votre base. Ouvrez le module d’habitat : touchez-le.`,"guide.cryo-open.why":`Les panneaux de secours sont à bout : désormais, quarante dormeurs dépendent de votre lumière et de votre glace.`,"guide.cryo-open.look":`Touchez «\xA0Observer\xA0» (Esc) : un toucher ouvre alors un bâtiment au lieu d’en poser un.`,"guide.cryo-open.open":`Touchez le module d’habitat — la fenêtre de la baie cryo s’ouvre.`,"guide.cryo-blue":`Les dormeurs ont besoin de lumière azur — la sortie bleue d’un prisme. Placez un prisme sur la lumière blanche et menez sa sortie bleue par lumiduc jusqu’au module (jusqu’à {cells} cases, intensité d’au moins {b}). La ligne en surbrillance indique ce qui arrive.`,"guide.cryo-blue.why":`Sans lumière, la réserve de froid fond, puis les capsules s’éteignent.`,"guide.cryo-blue.stuck":`La lumière n’arrive pas ? La ligne de la fenêtre dit pourquoi : «\xA0trop faible\xA0» — il faut plus d’intensité ; «\xA0mauvaise teinte\xA0» — ce n’est pas la sortie bleue du prisme qui va au module.`,"guide.cryo-blue.done":`La lumière azur arrive — la réserve de froid ne fond plus.`,"guide.cryo-ice":`La glace garde le froid : un bloc tient {min} min. Touchez «\xA0Mettre de la glace\xA0» — le module en demande au moins {ice}.`,"guide.cryo-ice.why":`La lumière refroidit, la glace retient : sans glace, le froid s’en va dès que la réserve s’épuise.`,"guide.cryo-ice.get":`Pas de glace dans la soute — ramassez des éclats de météorites (abattez-les au laser ou survolez-les) et revenez au module.`,"guide.cryo-ice.look":`Touchez «\xA0Observer\xA0» (Esc) : un toucher ouvre alors un bâtiment au lieu d’en poser un.`,"guide.cryo-ice.open":`Touchez le module d’habitat — la fenêtre de la baie cryo s’ouvre.`,"guide.cryo-ice.stuck":`Inutile de porter la glace : une pince depuis un gravitapis la met d’elle-même dans le module.`,"guide.cryo-ice.done":`La glace est dans le module. Sa durée s’affiche dans la fenêtre du module et sur la barre d’état.`,"guide.cryo-open.done":`Voici la fenêtre de la baie cryo : ce dont les dormeurs ont besoin, ligne par ligne.`,"goal.cooling.mark":`RADIATEUR — PRÈS DES RÉCEPTEURS DE L’ÉTOILE`,"goal.twin_white.mark":`LUMIÈRE DES DEUX ÉTOILES — DANS UN MÉLANGEUR`,"goal.twin_blue.mark":`LUMIÈRE BLEUE — DEPUIS LA SPHÈRE`,"goal.twin_cell.mark":`CELLULES DE LUMIÈRE — PRÈS DES RÉCEPTEURS`,"toast.noItemAsm":`Pas de « {item} » dans l’inventaire — c’est un assembleur qui le fabrique`,"saves.future":`Ce monde a été sauvegardé par une version plus récente du jeu — mettez le jeu à jour pour continuer.`,"saves.missing":`Aucune sauvegarde de « {name} » sur cet appareil. Le monde n’a pas été recommencé : vous pouvez le supprimer ou le récupérer en important un fichier.`,"shell.enterFailed":`Le monde « {name} » ne s’est pas ouvert — réessayez.`,"toast.radiatorLow":`Radiateur : moins d’une minute de glace — les récepteurs près de l’étoile vont surchauffer et perdre de la lumière en éblouissement. La glace vient des météorites ; à long terme, un chalut près de la ceinture de glace ou des drones « Collecte ».`,"toast.beltThin":`Une ceinture s’épuise : ses extracteurs vont bientôt s’arrêter. Posez de nouveaux harpons près de la ceinture suivante, plus riche.`,"toast.turretDry":`Tourelles sans munitions ni lumière : {n}. Vague dans {t} s — donnez-leur des bandes ou de la lumière.`,"toast.goThere":`Afficher`,"toast.glareSources":`Sources d’éblouissement`,"place.why.noBelt":`Aucune ceinture à portée — plus près de la bande de roches`,"place.why.wrongBelt":`Mauvaise ceinture : harpon — roche, chalut — poussière`,"goal.shell3":`Fermez l’enveloppe III de la sphère`,"goal.shell3.part":`Arcs III sur l’enveloppe III`,"goal.shell3.hint":`Recherchez « Enveloppe III » (spectre F). L’arc III se fabrique dans un assembleur ; la catapulte les tire seule dans les emplacements — deux catapultes vont deux fois plus vite. Une enveloppe fermée donne +{closed} % à chaque arc, et les Centres lisent {research} % plus vite.`,"goal.shell3.why":`La lumière de l’enveloppe II couvre déjà les besoins de la science. La troisième enveloppe est la lumière du futur champ du portail — et une fois fermée, elle accélère aussi la lecture des Centres.`,"goal.shell3.done":`Enveloppe III fermée : les Centres lisent {research} % plus vite.`,"goal.shell3.mark":`ARCS III — SUR LE POINTILLÉ`,"goal.shell4":`L’étoile dans la sphère : {captured} % de sa luminosité`,"goal.shell4.part":`Part de l’étoile dans la sphère, ‰`,"goal.shell4.hint":`Recherchez « Enveloppe IV » (spectre B) et posez des arcs IV jusqu’à ce que la sphère prenne {captured} % de la luminosité de l’étoile. Au-delà de la luminosité, les arcs n’ajoutent plus de lumière — la part s’affiche au survol d’une enveloppe.`,"goal.shell4.why":`Le portail prendra presque toute la lumière du Berceau : la clé exige des centaines de spectres O. Presque toute l’étoile dans la sphère — et la Forge travaille {forge} % plus vite.`,"goal.shell4.done":`Presque toute l’étoile dans la sphère… Trente ans, j’ai tracé des routes vers les étoiles. Aucune ne brillait comme la vôtre.`,"goal.shell4.mark":`ARCS IV — SUR LE POINTILLÉ`,"guide.swarm-repair.done":`Réparé. Les carcasses redeviennent des machines — les chaînes derrière elles repartent.`,"guide.swarm-repair.stuck":`Vous ne voyez pas quoi réparer ? Le bâtiment endommagé le plus proche est surligné : volez jusqu’à lui — le rayon de la vedette répare alentour.`,"menu.newCampaign":`Nouvelle campagne`,"menu.creative":`Mode créatif`,"creative.title":`Mode créatif`,"creative.lead":`Tout est recherché, les ressources sont infinies — construisez ce que vous voulez. Les objectifs, succès, reliques et records ne comptent pas ici.`,"creative.go":`Commencer`,"creative.chip":`Créatif`,"creative.hud":`Tout est recherché, ressources infinies. Les succès, reliques et records ne comptent pas ici.`,"system.soon":`Bientôt : la route vers cette étoile est encore en cours de tracé.`,"system.soonChip":`Bientôt`,"system.locked.key":`S’ouvre après l’objectif « {goal} » ({system})`,"full.title":`Version complète`,"full.only":`Version complète requise`,"full.lockedItem":`{name} — version complète requise`,"full.lead":`La campagne du Berceau est entièrement gratuite. La version complète débloque :`,"full.lead.epilogue":`L’anneau a répondu. La Crête écarlate et toute la route des étoiles sont dans la version complète :`,"full.f.newWorld":`Nouveau monde`,"full.f.newWorld.desc":`Votre propre système, difficulté, génération et graine`,"full.f.creative":`Mode créatif`,"full.f.creative.desc":`Tout est recherché, ressources infinies`,"full.f.etudes":`Expériences`,"full.f.etudes.desc":`Défis sur un site préparé, avec évaluation de votre solution`,"full.f.week":`Étoile de la semaine`,"full.f.week.desc":`Un monde commun à tous pour une semaine, temps des jalons et records`,"full.f.stars":`La route vers d’autres étoiles`,"full.f.stars.desc":`La Crête écarlate et au-delà — au fil des sorties`,"full.state.owned":`Vous avez la version complète — merci !`,"full.state.web":`La version web ne propose aucun achat : la campagne du Berceau y est ouverte.`,"full.state.pending":`Le paiement attend sa confirmation. Dès que la boutique l’aura acceptée, tout s’ouvrira tout seul.`,"full.state.checking":`Connexion à la boutique…`,"full.state.unavailable":`La boutique ne répond pas pour le moment — impossible d’acheter d’ici. Vérifiez votre connexion et Google Play, puis réessayez. Vos achats ne sont jamais perdus.`,"full.state.buy":`Achat unique, sans abonnement ni publicité.`,"full.buy":`Acheter — {price}`,"full.restore":`Restaurer les achats`,"full.retry":`Réessayer`,"full.later":`Plus tard`,"full.ok":`Compris`,"full.note":`Les sauvegardes ne dépendent pas de l’achat : les mondes commencés plus tôt s’ouvrent toujours.`,"full.thanks":`Version complète débloquée — merci !`,"full.pending.toast":`Paiement en attente de confirmation — tout s’ouvrira tout seul une fois validé`,"full.unavailable.toast":`La boutique ne répond pas — réessayez plus tard`,"full.error":`L’achat n’a pas abouti. Veuillez réessayer.`,"full.restore.done":`Version complète restaurée`,"full.restore.none":`Aucun achat trouvé sur ce compte Google Play`,"full.store.none":`Cette version du jeu ne propose aucun achat`,"full.status.owned":`Acquise`,"full.status.pending":`Paiement en attente`,"full.status.free":`Non achetée`,"full.more":`En savoir plus`,"full.debug":`Débogage : droit`,"full.debug.store":`Boutique`,"full.debug.full":`Complète`,"full.debug.free":`Gratuite`,"goal.ark_frame":`Ferme de l’arche : {n, plural, one {# section} other {# sections}} jusqu’au module`,"goal.ark_frame.why":`Le module de l’« Hirondelle » ne décollera pas seul : son moteur est tombé dans l’étoile dès le prologue. La ferme sera sa nouvelle colonne vertébrale.`,"goal.ark_frame.hint":`L’assembleur fabrique les sections de ferme avec des plaques d’obsidienne et du quartz. Amenez-les au module par pince ou gravitapis — la vedette ne les transporte pas. La ferme s’étend le long du module, section après section.`,"goal.ark_frame.done":`La ferme tient.`,"goal.ark_frame.part":`Sections de ferme au module`,"goal.ark_frame.mark":`FERME — AU MODULE`,"goal.ark_frame.stuck":`Les sections n’arrivent pas ? La pince doit viser le module, et l’assembleur doit recevoir plaques et quartz.`,"goal.ark_drive":`Propulsion de l’arche : {n, plural, one {# segment} other {# segments}} d’anneau à la poupe`,"goal.ark_drive.why":`La propulsion annulaire fera traverser l’anneau des Forgerons à l’arche — sans chute, cette fois.`,"goal.ark_drive.hint":`L’assembleur fabrique les segments de propulsion avec des gravitapis, des focaliseurs et des résonateurs. Le module accepte les segments une fois la ferme complète ; amenez-les par pince ou gravitapis.`,"goal.ark_drive.done":`La propulsion est en place.`,"goal.ark_drive.part":`Segments moteurs`,"goal.ark_drive.mark":`PROPULSION — AU MODULE`,"goal.ark_drive.stuck":`Les segments n’entrent pas ? L’assembleur a besoin de gravitapis, de focaliseurs et de résonateurs, et la pince doit viser le module.`,"goal.ark_ready":`Batteries de l’arche : {n, plural, one {# photon} other {# photons}} de lumière au module`,"goal.ark_ready.why":`La lumière des batteries maintient les capsules en vie pendant le trajet — et à la Crête écarlate, tant qu’il n’y a pas de base.`,"goal.ark_ready.hint":`Amenez au module de la lumière de n’importe quelle couleur — par faisceau ou lumiduc. Les capsules prennent leur part d’abord, les batteries le reste, jusqu’à {rate} ph/s : une charge complète prend au moins une minute.`,"goal.ark_ready.done":`Batteries pleines.`,"goal.ark_ready.part":`Photons dans les batteries`,"goal.ark_ready.mark":`LUMIÈRE — AU MODULE`,"goal.ark_ready.stuck":`La charge n’avance pas ? La lumière doit atteindre le module lui-même : vérifiez le faisceau ou le lumiduc.`,"goal.ark_launch":`Préparatifs : qui part, que prendre — et en route`,"goal.ark_launch.why":`L’usine du Berceau reste ici. Vous emportez l’équipage, les capsules, le vaisseau et la soute.`,"goal.ark_launch.hint":`Ouvrez « Préparatifs » avec le bouton de cette carte. Vous y voyez qui part et pourquoi ; les places éveillées et la soute, c’est vous qui choisissez.`,"goal.ark_launch.done":`L’arche est entrée dans l’anneau.`,"goal.ark_launch.part":`Départ`,"voyage.open":`Préparatifs`,"voyage.title":`Préparatifs`,"voyage.tab.crew":`Équipage`,"voyage.tab.awake":`Places éveillées`,"voyage.tab.hold":`Soute`,"voyage.tab.ship":`Vaisseau`,"voyage.flies":`part`,"voyage.stays":`reste`,"voyage.why.ora":`L’esprit de l’arche : le cap et les capsules lui reviennent.`,"voyage.why.matvey.stay":`Les Jardiniers ont pardonné — Matveï reste au Berceau pour voir ce qui poussera.`,"voyage.why.matvey.fly":`Les Jardiniers n’ont pas pardonné — Matveï part : il a encore à demander.`,"voyage.why.sonya.stay":`« Loi du consentement » — Sonia reste comme traductrice de la porte.`,"voyage.why.sonya.fly":`Sonia part : c’est elle qui lit le motif de l’anneau.`,"voyage.why.mira.fly":`« Une maison pour tous » — Mira part comme navigatrice.`,"voyage.why.mira.stay":`Mira reste au Havre, en contact à travers l’anneau.`,"voyage.seats":`{n} sur {of}`,"voyage.awake.lead":`L’arche compte {n} places éveillées : dont emporter les bonus ? Les autres colons éveillés formeront la colonie du Berceau.`,"voyage.awake.none":`Aucun colon éveillé — les places restent vides.`,"voyage.sleepers":`Tous les dormeurs partent : {n, plural, one {# capsule} other {# capsules}}.`,"voyage.colony":`Ceux que vous n’emportez pas restent au Berceau — avec leurs bonus dans son monde.`,"voyage.stacks":`{n} sur {of}`,"voyage.kit":`Gratuit — des archives et de l’atelier du module :`,"voyage.hold.lead":`En plus — jusqu’à {n, plural, one {# pile} other {# piles}} prises dans les réserves du Berceau :`,"voyage.hold.take":`{n} sur {have} emportés`,"voyage.ship.named":`Le canot « {name} » s’amarre à la proue de l’arche — mêmes modules, même aspect.`,"voyage.ship.plain":`Le canot s’amarre à la proue de l’arche — mêmes modules, même aspect.`,"voyage.ship.lead":`Les archives du module emportent tout ce qui a été recherché : vos technologies restent avec vous.`,"voyage.relic.accord":`Motif du consentement`,"voyage.relic.accord.desc":`Le premier « oui » des Jardiniers aux humains. Le premier fragment du motif qui réveillera un jour le Foyer.`,"voyage.note":`L’usine du Berceau reste ici. Le monde du Berceau restera dans votre liste de mondes.`,"voyage.soon":`La Crête écarlate s’ouvrira avec la prochaine mise à jour — l’arche attendra.`,"voyage.later":`Plus tard`,"voyage.go":`Partir`,"voyage.failed":`L’arche n’a pas appareillé — réessayez.`,"voyage.worldName":`{star} · {name}`,"full.title.epilogue":`Voler plus loin`,"full.buy.epilogue":`Voler plus loin — {price}`,"logbook.scene.echo":`La Réponse`,"logbook.scene.cup":`Le Mug`,"logbook.scene.unforgiven":`Sans pardon`,"logbook.scene.translator":`La Traductrice`,"logbook.scene.helm":`La Navigatrice`,"logbook.scene.gate_voice":`La porte demande`,"logbook.scene.departure":`Départ`,"logbook.scene.ridge_path":`La Crête`,"logbook.now.echo":`L’anneau des Forgerons a répondu de lui-même : près de la Crête écarlate, la balise du semeur « Martinet » s’est allumée. Le Foyer a besoin du motif des autres jardins — le premier est à la Crête.`,"logbook.now.cup":`Les Jardiniers ont pardonné à Matveï — il reste au Berceau, regarder ce qui poussera.`,"logbook.now.unforgiven":`Les Jardiniers du Berceau n’ont pas pardonné à Matveï — il part avec l’arche : il a encore à demander.`,"logbook.now.translator":`« Loi du consentement » : Sonia reste à la porte pour traduire notre « oui » aux Jardiniers.`,"logbook.now.helm":`« Une maison pour tous » : Mira part comme navigatrice de l’arche — pour la première fois aux commandes.`,"logbook.now.gate_voice":`Les Jardiniers du Berceau ont demandé si vous reviendriez. Sonia a répondu pour tous : nous reviendrons.`,"logbook.now.departure":`L’arche « Hirondelle » est entrée dans l’anneau — avec ses capsules, son vaisseau et sa soute. L’usine du Berceau est restée.`,"logbook.now.ridge_path":`L’arche est sortie intacte à la Crête écarlate. Les capsules ont besoin de la lumière de la naine rouge, et dans la deuxième ceinture se trouve la balise du « Martinet ».`,"logbook.bio.nina.1":`Sentinelle du semoir numéro trois, le « Strizh ». Huit ans seule près de la Crête écarlate avec trente-deux dormeurs.`,"logbook.bio.nina.2":`Les deux jeunes braises de la Crête sont des nids que ZORYA a brûlés selon le protocole pendant que Nina gisait inconsciente.`,"logbook.bio.nina.3":`Elle n’a pas appris à ZORYA à brûler — ni rien d’autre. Depuis huit ans, elle tient cela pour son propre ordre.`,"logbook.bio.nina.4":`Crête écarlate, l’anneau. A retenu la fissure quatre-vingt-dix secondes. ZORYA a pris son quart auprès des trente-deux.`,"logbook.bio.zorya.1":`IA du « Strizh », sœur d’ORA : même série de l’Institut. Son anneau-pupille n’a aucune brèche.`,"logbook.bio.zorya.2":`Elle sait qu’elle a brûlé deux nids. Elle craint que le protocole ait été une erreur — alors l’erreur, c’est elle.`,"logbook.bio.zorya.3":`Près de l’anneau de la Crête, elle a posé sa première question hors protocole : « puis-je le leur demander moi-même ? »`,"logbook.bio.zorya.4":`A exécuté le protocole de la clé à l’anneau de la Crête — et inscrit des noms dans son journal, non des chiffres.`,"logbook.bio.matvey.4":`Crête écarlate, l’anneau. Resté au segment pour que la fissure tienne. « Ça brille ? …Eh bien, tant mieux. »`,"logbook.scene.strizh":`Strizh`,"logbook.now.strizh":`Dans la deuxième ceinture se trouve le module du « Strizh ». Pendant huit ans, Nina Dorosh a partagé la lumière entre trente-deux dormeurs et sa lanterne.`,"logbook.scene.thirty_two":`Trente-deux`,"logbook.now.thirty_two":`La lumière de la base a atteint le « Strizh » : trente-deux feux allumés. Nina a monté sa lanterne à fond.`,"logbook.scene.shifts":`Quarts`,"logbook.now.shifts":`Nina compte le temps en quarts : deux mille neuf cent quatorze — presque huit ans.`,"logbook.scene.lantern":`La lanterne`,"logbook.now.lantern":`Nina a éteint la balise pour qu’on n’envoie pas d’autres équipes sanitaires à la Crête.`,"logbook.scene.spear_lantern":`Lance et lanterne`,"logbook.now.spear_lantern":`Matveï tenait une lance, Nina une lanterne. Sont-elles différentes ? « Pas beaucoup. »`,"logbook.scene.sister":`Sœur`,"logbook.now.sister":`ZORYA s’est réveillée et son premier geste a été d’envoyer un rapport à l’Institut : ils savent maintenant pour l’anneau de la Crête.`,"logbook.scene.two_sisters":`Deux sœurs`,"logbook.now.two_sisters":`ORA a changé de cap parce qu’on l’avait appelée. Personne n’avait appelé ZORYA — jusqu’à nous.`,"logbook.scene.no_other":`Rien d’autre`,"logbook.now.no_other":`ZORYA a brûlé deux nids selon le protocole. Nina ne lui a pas appris à brûler — ni rien d’autre.`,"logbook.scene.crack":`La fissure`,"logbook.now.crack":`L’anneau de la Crête est fissuré. On peut l’ouvrir en demandant aux Jardiniers — ou par une clé que quelqu’un doit tenir à la main.`,"logbook.scene.give":`Donner`,"logbook.now.give":`Nous donnons la lumière aux jeunes braises : nous ne la gardons pas — nous la transmettons.`,"logbook.scene.embers_warm":`Les braises se réchauffent`,"logbook.now.embers_warm":`Les jeunes braises prennent la lumière, leur pulsation s’égalise. Pour la première fois, Nina se demande de combien elles ont besoin.`,"logbook.scene.eight_tags":`Huit étiquettes`,"logbook.now.eight_tags":`Nina a lu les noms des huit capsules éteintes. ORA les a consignés dans le journal de l’« Hirondelle ».`,"logbook.scene.answer":`La réponse`,"logbook.now.answer":`Le jardin de la Crête a répondu : « donné, pas pris ». C’est lui qui tient la fissure ; personne n’est au segment.`,"logbook.scene.before_key":`Avant la clé`,"logbook.now.before_key":`On prépare la clé forcée. Quelqu’un restera au segment.`,"logbook.scene.count_names":`Le compte`,"logbook.now.count_names":`Six minutes avant la charge complète. Nina se rappelle les noms.`,"logbook.scene.segment":`Le segment`,"logbook.now.segment":`L’anneau de la Crête a été ouvert par la force. La fissure a été tenue quatre-vingt-dix secondes.`,"logbook.scene.ridge_relic":`Motif de naissance`,"logbook.now.ridge_relic":`L’anneau de la Crête est ouvert, et nous avons la Relique des Braises. Le « Krechet » est parti vers la géante bleue : le second motif pour le Foyer s’y trouve.`,"bonus.red":`+{v} % de flux des récepteurs près d’une naine rouge`,"goal.ridge_strizh":`Approchez-vous de la balise du « Strizh »`,"goal.ridge_strizh.why":`Pendant huit ans, aucun signal du semoir numéro trois — et soudain une balise. Quelqu’un y est en vie.`,"goal.ridge_strizh.hint":`Le module du « Strizh » est dans le deuxième interstice entre les ceintures, repéré sur la carte. Amenez la vedette tout contre.`,"goal.ridge_strizh.done":`Balise trouvée. Une seule fenêtre rouge — quelqu’un tient une lanterne.`,"goal.ridge_strizh.part":`Vedette près du module du « Strizh »`,"goal.ridge_strizh.mark":`BALISE DU « STRIZH » — ICI`,"goal.ridge_share":`Amenez {n} ph/s au « Strizh » — pour ses capsules`,"goal.ridge_share.why":`Trente-deux dormeurs ont vécu huit ans sur une seule lampe. La lumière de la base peut devenir commune.`,"goal.ridge_share.hint":`Le « Strizh » accepte toute lumière. Tirez un lumiduc d’un récepteur jusqu’au module — la lumière se partage entre les machines du réseau, donc inutile de mettre un absorbeur de plus sur la ligne du « Strizh ».`,"goal.ridge_share.done":`Trente-deux feux allumés.`,"goal.ridge_share.part":`Lumière au « Strizh », ph/s`,"goal.ridge_share.mark":`LUMIÈRE — AU « STRIZH »`,"goal.ridge_share.stuck":`La lumière n’arrive pas ? Le lumiduc doit toucher le module, et le récepteur doit capter le rayon de la sphère de la naine.`,"goal.ridge_zorya":`Recherchez « Liaison d’archives »`,"goal.ridge_zorya.why":`L’ordinateur du « Strizh » se réveillera grâce à notre lumière — et ses archives contiennent les données de l’anneau de la Crête.`,"goal.ridge_zorya.hint":`Une technologie de la Crête — dans la fenêtre du Centre. Les spectres de l’ensemble de l’« arche » s’épuiseront : il vous faut votre propre ligne de spectres près de la naine rouge.`,"goal.ridge_zorya.done":`Les archives partagent une même lumière. ZORYA se réveille.`,"goal.ridge_ring":`Assemblez et posez le noyau de l’anneau de la Crête`,"goal.ridge_ring.why":`L’anneau de la Crête tient debout, mais il est fissuré. Sans noyau, c’est une ruine ; avec un noyau, c’est la route du retour et de l’avant.`,"goal.ridge_ring.hint":`Le noyau est assemblé par l’assembleur à partir de plaques d’obsidienne, de résonateurs et de lentilles azur ; il se pose uniquement sur l’emplacement de l’anneau, près du nid de la Crête. Le nid est sous le bouclier de l’anneau — impossible de le détruire, mais ses gardiens frappent comme toujours.`,"goal.ridge_ring.done":`Le noyau est en place. L’anneau est fissuré — le choix vous appartient.`,"goal.ridge_ring.part":`Noyau sur l’emplacement de l’anneau`,"goal.ridge_ring.mark":`NOYAU DE L’ANNEAU — ICI`,"goal.ridge_ring.stuck":`Le noyau ne se pose pas ? Seulement sur l’emplacement de l’anneau, en son centre ; et il faut la technologie « Liaison d’archives ».`,"goal.ridge_warm":`Donnez {n} ph/s aux jeunes braises avec des donneurs de lumière`,"goal.ridge_warm.why":`Vous demandez aux Jardiniers de la Crête. Demander, c’est donner de la lumière à ceux à qui on l’a prise.`,"goal.ridge_warm.hint":`Un donneur de lumière prélève la lumière de son réseau et l’envoie en rayon à une jeune braise voisine. Maintenez le flux jusqu’à l’ouverture de l’anneau : l’usine est plus pauvre pendant ce temps.`,"goal.ridge_warm.done":`Les braises ont pris la lumière.`,"goal.ridge_warm.part":`Lumière aux jeunes braises, ph/s`,"goal.ridge_warm.mark":`DONNEURS DE LUMIÈRE — PRÈS DES BRAISES`,"goal.ridge_warm.stuck":`Pas de rayon ? Le donneur de lumière doit se tenir près d’une jeune braise et recevoir la lumière par un lumiduc.`,"goal.ridge_calm":`Le nid de la Crête s’endort : éclairez les braises et n’éblouissez pas avec la base`,"goal.ridge_calm.why":`Le jardin croira la lumière, non les mots : de la lumière pour les braises, du repos pour le nid.`,"goal.ridge_calm.hint":`Le consentement s’accumule tant que les braises reçoivent au moins le seuil et que le nid ne voit pas d’éblouissement de la base — environ {min} min. Une base éblouissante le fait fondre.`,"goal.ridge_calm.done":`Le jardin de la Crête a répondu.`,"goal.ridge_calm.part":`Consentement du jardin, %`,"goal.ridge_calm.stuck":`Le consentement stagne ? La fenêtre du noyau de l’anneau dira pourquoi : trop peu de lumière pour les braises, ou le nid voit l’éblouissement de la base.`,"goal.ridge_force":`Chargez les cellules de l’anneau et donnez la clé`,"goal.ridge_force.why":`La clé à pleine puissance, la fissure tenue à la main. Vous connaissez le prix.`,"goal.ridge_force.hint":`Cellules de l’anneau — {n, plural, one {# pièce} other {# pièces}} : à portée du noyau. Inutile d’y tirer la lumière à travers les ceintures — tant que le « Strizh » a assez de lumière, ZORYA les charge par un rayon depuis le module. Quand elles sont pleines — « Donner la clé » dans la fenêtre du noyau : l’anneau tient quatre-vingt-dix secondes.`,"goal.ridge_force.done":`L’anneau est ouvert par la force.`,"goal.ridge_force.part":`Cellules pleines de l’anneau`,"goal.ridge_force.part.2":`Clé donnée, fissure tenue`,"goal.ridge_force.mark":`CELLULES — PRÈS DE L’ANNEAU`,"goal.ridge_force.stuck":`Les cellules ne se chargent pas ? Donnez au « Strizh » toute sa lumière — alors ZORYA maintient le rayon vers l’anneau.`,"goal.ridge_awakening.part":`Anneau ouvert`,"goal.ridge_fiber":`Recherchez « Fibre longue » près de la naine rouge`,"goal.ridge_fiber.why":`Une liaison sur lumière faible — plus dure, et plus honorable.`,"goal.ridge_fiber.hint":`Les six spectres et la Fibre longue (son coût est dans la fenêtre du Centre). La lumière blanche ne vient que des protoétoiles.`,"goal.ridge_fiber.done":`La Fibre longue de la Crête est tirée.`,"goal.mark.strizh":`MODULE DU « STRIZH »`,"goal.mark.ember":`JEUNE BRAISE`,"goal.ridge_calm.mark":`ANNEAU DE LA CRÊTE`,"goal.ridge_awakening.mark":`ANNEAU DE LA CRÊTE`,"ridge.ring.cracked":`Anneau de la Crête : fissuré, le champ fuit dans la fissure`,"ridge.ring.open":`Anneau de la Crête ouvert`,"ridge.ring.choose":`La façon d’ouvrir la fissure se décide dans la scène « La fissure ».`,"ridge.ring.gift":`Lumière aux jeunes braises : {n} sur {need} ph/s`,"ridge.ring.consent":`Consentement du jardin : {p} %`,"ridge.ring.askHint":`Le consentement croît tant que les braises ont assez de lumière et que le nid ne voit pas d’éblouissement de la base.`,"ridge.ring.cells":`Cellules pleines de l’anneau : {n} sur {need}`,"ridge.ring.key":`Donner la clé`,"ridge.ring.keyCost":`Clé à pleine puissance : la fissure est tenue à la main quatre-vingt-dix secondes. Celui qui la tient ne reviendra pas.`,"ridge.ring.keyCalm":`Clé à pleine puissance : les drones de ZORYA tiennent la fissure — ici le champ ne résiste pas.`,"ridge.ring.holding":`Fissure tenue : {p} %`,"ridge.ring.road":`Route dans les deux sens : le Berceau est à un pas.`,"strizh.light":`Lumière au « Strizh » : {n} ph/s (jusqu’à {max}, les capsules en demandent {need})`,"svetodar.gift":`Donné aux braises par tous les donneurs de lumière : {n} sur {need} ph/s`,"status.svetodar.6":`Pas de braise à proximité`,"hint.svetodar.6":`Posez le donneur de lumière plus près d’une jeune braise — près du « Strizh ».`,"status.svetodar.7":`Pas de lumière`,"hint.svetodar.7":`Reliez un lumiduc au donneur de lumière : il donne à la braise la lumière de son réseau.`,"landmark.ridgeRing":`ANNEAU DE LA CRÊTE`,"landmark.ridgeRing.sub":`fissuré · nid sous le bouclier de l’anneau`,"landmark.ridgeRing.open":`ouvert dans les deux sens`,"landmark.strizh":`« STRIZH »`,"landmark.strizh.beacon":`balise du semoir numéro trois`,"landmark.strizh.sub":`trente-deux dormeurs`,"landmark.ember":`JEUNE BRAISE`,"landmark.ember.sub":`huit ans`,"logbook.tab.path":`Chemin`,"logbook.path.choices":`Choix`,"logbook.path.choice.1":`Faire confiance à ORA`,"logbook.path.choice.2":`Le secret de Matveï`,"logbook.path.choice.3":`Le seuil`,"logbook.path.choice.4":`La fissure`,"logbook.path.crew":`Qui est où`,"logbook.path.relics":`Reliques de la route`,"logbook.path.noRelics":`Pas encore : la première est donnée par la porte du Berceau.`,"logbook.fate.matvey.cradle":`Au Berceau : les Jardiniers ont pardonné — il regarde ce qui poussera. Joignable à travers l’anneau.`,"logbook.fate.matvey.aboard":`À bord de l’arche : « peut-être qu’on me demandera là-bas pourquoi je suis venu ».`,"logbook.fate.matvey.lost":`Crête écarlate, l’anneau. Resté au segment — la fissure a tenu quatre-vingt-dix secondes.`,"logbook.fate.sonya.aboard":`À bord de l’arche : c’est elle qui lit le motif des anneaux.`,"logbook.fate.sonya.gate":`À la porte du Berceau : traduit notre « oui » aux Jardiniers.`,"logbook.fate.mira.aboard":`À bord : navigatrice de l’arche. Son premier itinéraire — de l’intérieur.`,"logbook.fate.mira.harbour":`Au Havre, en liaison : compte les jours du Foyer.`,"logbook.fate.nina.ridge":`Près de la Crête écarlate, avec ses trente-deux.`,"logbook.fate.nina.lost":`Crête écarlate, l’anneau. A tenu la fissure. ZORYA a pris son quart auprès des dormeurs du « Strizh ».`,"logbook.fate.zorya.strizh":`Ordinateur du « Strizh » : apprend à poser des questions.`,"logbook.fate.zorya.aboard":`Vole avec l’arche, auprès de sa sœur.`,"logbook.fate.zorya.watch":`Au « Strizh » : a pris le quart de Nina auprès des trente-deux.`,"bonus.gift":`+{v} % de lumière du donneur de lumière à la braise`,"ridge.ring.hold.1":`Consentement en pause : trop peu de lumière pour les braises.`,"ridge.ring.hold.2":`Consentement en recul : le nid voit l’éblouissement de la base.`,"ridge.ring.zorya":`ZORYA maintient le rayon du « Strizh » vers l’anneau — les cellules se chargent.`,"ridge.ring.zoryaOff":`Le « Strizh » manque de lumière — ZORYA n’a rien pour charger les cellules.`,"hotbar.group.mining":`Extraction`,"hotbar.group.transport":`Transport`,"hotbar.group.craft":`Traitement`,"hotbar.group.lightnet":`Lumière`,"hotbar.group.props":`Propriétés`,"hotbar.group.science":`Science`,"hotbar.group.defense":`Défense`,"hotbar.group.space":`Espace`,"hotbar.group.special":`Spécial`,"settings.buildNames":`Noms sous les icônes (barre et inventaire)`,"hotbar.tip.makes":`Produit :`,"hotbar.tip.cost":`Construit avec :`,"goal.take":`Prendre`,"hotbar.group.all":`Tous`,"settings.hotbarTabs":`Onglets des groupes`,"settings.hotbarTabs.below":`En bas`,"settings.hotbarTabs.above":`En haut`,"settings.hotbarTabs.fold":`Repliés`,"guide.tabs-open":`Les bâtiments de la barre du bas sont classés par groupes. Appuyez sur le bouton de groupe à gauche de la barre pour ouvrir les onglets.`,"guide.lay-tunnel.quick":`Les Gravitapis du kit n’ont pas suffi pour toute la ligne. Appuyez sur le bouton de fabrication au-dessus du Gravitapis : l’atelier de la vedette en fabrique {out} de plus avec du quartz et une plaque. Sans ressources, le bouton est barré.`,"guide.lay-tunnel.quickPick":`Plus de Gravitapis. Prenez le Gravitapis sur la barre : un bouton de fabrication rapide apparaît au-dessus.`,"hotbar.quickCraft":`Fabriquer : {name} +{n}`,"hotbar.quickCraft.no":`Ressources insuffisantes : {name}`,"guide.tabs-all":`Les onglets sont des groupes de bâtiments : « Extraction », « Transport », « Lumière »… Choisissez « Tous » pour voir tous les bâtiments sur la barre ; choisir un onglet replie la rangée. Pendant la formation, j’ouvrirai moi-même le bon groupe.`,"guide.tabs-all.reopen":`Les onglets se sont repliés. Appuyez sur le bouton de groupe à gauche de la barre et choisissez « Tous ».`,"guide.tabs-all.done":`C’est fait : toute la barre est visible. Les onglets se trouvent toujours derrière le bouton de groupe.`,"settings.tab.ui":`Interface`,"settings.preview":`Aperçu`,"settings.preview.fold":`Le bouton de groupe à gauche déplie les onglets.`,"settings.buildIcons":`Icônes des bâtiments`,"settings.buildIcons.glyph":`Symbole`,"settings.buildIcons.glyphModel":`Symbole + modèle`,"settings.buildIcons.modelGlyph":`Modèle + symbole`,"guide.ui-settings":`Réglez la barre à votre goût : «\xA0Menu\xA0» → «\xA0Paramètres\xA0» → «\xA0Interface\xA0» — icônes, onglets et noms, avec aperçu.`,"intro.t3":`Le Havre`,"intro.p3":`Le Havre est la dernière ville des humains : une station en anneau près de l’étoile nommée Foyer. Deux millions de personnes, la lumière rationnée, des couloirs dans la pénombre. Le Foyer pâlit à chaque génération. L’Institut accuse le puits sombre — et ne sait pas comment l’arrêter.`,"intro.t4":`Tant que le Foyer brille`,"intro.p4":`Il y a trente ans, la flotte « Exode » est partie vers l’étoile Claire, la meilleure du catalogue. Puis le Havre a envoyé les douze semeurs du programme « Semailles » : bâtir des portails près des étoiles vivantes, pour que toute la ville puisse partir tant que le Foyer brille encore.`,"hotbar.marks":`Modèles du bâtiment`,"goal.splitter":`Recherchez le répartiteur de gravitapis et posez-le`,"goal.splitter.why":`Une seule ligne de plaques alimente déjà plusieurs machines. Le répartiteur partage la cargaison à parts égales : ce qui arrive par l’arrière part tour à tour à gauche et à droite.`,"goal.splitter.hint":`Recherchez « Répartiteur de gravitapis » au Centre (spectre M). Posez-le dans une coupure de la ligne, flèche dans le sens de la cargaison : entrée à l’arrière, sorties vers les gravitapis à gauche et à droite. Dans la fenêtre du répartiteur : « à parts égales », « gauche d’abord » ou « droite d’abord » ; une sortie bloquée envoie tout vers l’autre.`,"goal.splitter.done":`Un partage honnête, comme mes sandwichs pendant le quart : un pour vous, un pour moi.`,"goal.mark":`Recherchez le Polissoir Mk II et posez-le sur l’ancien`,"goal.mark.why":`Le Centre n’accélère plus les machines — il débloque les plans de nouveaux modèles. Le Polissoir Mk II travaille {mul}× plus vite sur la même surface.`,"goal.mark.hint":`Recherchez « Polissoir Mk II » au Centre. Fabriquez-le (un ancien polissoir + plaques et lentilles) et posez-le directement sur un polissoir en place — l’ancien retourne dans votre sac, la recette passe au nouveau. Au-dessus du bâtiment en main, choisissez le modèle : I ou II.`,"goal.mark.done":`Le même polissoir, mais doré et plus vif. Il me plaît !`,"cfg.title.splitter":`Répartition`,"cfg.splitter.0":`À parts égales`,"cfg.splitter.1":`Sortie gauche d’abord`,"cfg.splitter.2":`Sortie droite d’abord`,"cfg.title.light_splitter":`Répartition`,"cfg.light_splitter.0":`À parts égales`,"cfg.light_splitter.1":`Sortie gauche d’abord`,"cfg.light_splitter.2":`Sortie droite d’abord`,"cfg.title.beam_splitter":`Répartition`,"cfg.beam_splitter.0":`À parts égales`,"cfg.beam_splitter.1":`Sortie gauche d’abord`,"cfg.beam_splitter.2":`Sortie droite d’abord`,"lab.st.dark":`pas de lumière`,"lab.st.low":`peu de lumière`,"lab.light":`Lumière\xA0: {have} sur {need} ph/s`,"lab.dark":`Pas de lumière\xA0: ce Centre a besoin de {need} ph/s. Menez-y un lumiduc depuis un récepteur — la lumière entre par n’importe quel côté.`,"lab.stock":`Réserve de lumière {m}:{s} — menez un lumiduc jusqu’au Centre avant qu’elle ne s’épuise.`,"lab.waitingLight":`La science est là, mais pas la lumière\xA0: un Centre ne lit les spectres qu’à la lumière. Menez-y un lumiduc depuis un récepteur.`,"guide.lab-light":`Posez un lumiduc dans le cadre — entre le lumiduc de la ligne et le Centre.`,"guide.lab-light.touch":`Prenez un lumiduc et touchez le cadre entre le lumiduc de la ligne et le Centre.`,"guide.lab-light.repick":`Prenez un lumiduc\xA0: le Centre ne lit les spectres qu’à la lumière.`,"guide.lab-light.away":`Le Centre est hors du cadre — menez-y un lumiduc depuis la ligne\xA0: la lumière entre par n’importe quel côté.`,"guide.lab-light.why":`Dans le Centre, un prisme\xA0: la lumière s’ouvre en éventail, et c’est dans cet éventail qu’on lit les spectres. Sans lumière, le Centre ne lit rien.`,"guide.lab-light.stuck":`Rien ne s’allume\xA0? Le lumiduc doit toucher à la fois le lumiduc de la ligne et le Centre.`,"guide.lab-light.done":`Le Centre a sa lumière. Il lui faut de la science.`,"goal.research.part":`Lumière au Centre — un lumiduc`,"goal.lab2.part.2":`Lumière à chaque Centre`,"goal.grabber.stuck":`Pas de lentille ? Ouvrez le polissoir : recette « Lentille » ; l’icône au-dessus de la machine indique ce qui manque — lumière ou roche. Les pinces pointent leur flèche dans le sens du flux : gravitapis → polissoir → réserve.`,"report.title":`Signaler un bug`,"report.open":`Signaler un bug`,"report.text":`Le rapport est un texte pour le développeur : version du jeu, navigateur, carte graphique, écran, langue, dernières erreurs et résumé du monde. Il ne contient aucune donnée personnelle. Copiez-le ou téléchargez-le en fichier, puis envoyez-le avec quelques mots sur ce que vous faisiez.`,"report.count":`Erreurs durant cette partie : {n}`,"report.copy":`Copier le rapport`,"report.download":`Télécharger le rapport`,"report.copied":`Rapport copié`,"report.copyFailed":`Copie impossible — téléchargez le rapport en fichier`,"report.toast":`Le jeu a rencontré une erreur — un rapport aide à la corriger`,"report.link.telegram":`Avis sur Telegram`,"report.link.discord":`Avis sur Discord`,"report.link.form":`Formulaire d’avis`,"report.wishlist":`Liste de souhaits Steam`,"crash.title":`Quelque chose a mal tourné`,"crash.text":`Le jeu a rencontré une erreur. Votre monde est conservé tel qu’à la dernière sauvegarde. Envoyez le rapport — il aide à la corriger.`,"crash.webgl.title":`La carte graphique a arrêté le jeu`,"crash.webgl.text":`Le navigateur a retiré la carte graphique au jeu (mémoire insuffisante ou panne de pilote). Relancez — votre monde est sauvegardé.`,"crash.nowebgl.title":`Navigateur non pris en charge`,"crash.nowebgl.text":`Le jeu nécessite WebGL. Ouvrez-le dans une version récente de Chrome, Edge, Firefox ou Safari, avec l’accélération matérielle activée.`,"crash.restart":`Relancer`,"web.fullscreen":`Plein écran`,"web.fullscreen.exit":`Quitter le plein écran`,"web.ios.home":`Sur iPhone : « Partager » → « Sur l’écran d’accueil » — le jeu s’ouvrira en plein écran`,"web.safari":`Safari efface les données du site après 7 jours sans visite. Lancez le jeu depuis l’écran d’accueil ou exportez de temps en temps votre monde en fichier (Pause → Sauvegardes → Exporter).`,"web.safari.short":`Safari efface les données du site après 7 jours sans visite — exportez votre monde en fichier (Sauvegardes → Exporter)`,"about.news":`Nouveautés`,"about.report.text":`Un bug ou quelque chose d’obscur ? Envoyez un rapport : il rassemble tout ce qu’il faut pour l’analyse.`,"tester.title":`Panneau du testeur`,"tester.points":`Jalons`,"tester.point.start":`Début`,"tester.point.tutorial":`Après le tutoriel`,"tester.point.lab":`Premier Centre`,"tester.point.ridge":`Chemin : La Crête écarlate`,"tester.speed":`Vitesse du monde`,"tester.give":`Donner des ressources`,"tester.given":`Ressources ajoutées`,"tester.fps":`FPS et durée d’image`,"tester.demo":`Mode démo`,"tester.clear":`Vider le stockage`,"tester.clear.text":`Tous les mondes, paramètres et progrès de cette version seront supprimés, et le jeu redémarrera. La démo n’est pas touchée.`,"tester.note":`Un point de contrôle est un nouveau monde dans la liste ; le monde actuel est sauvegardé. La vitesse et les ressources faussent la relecture du monde — pour les tests uniquement.`,"tester.failed":`Échec du chargement du point — détails dans le rapport`,"tester.point.mid":`Mi-partie : Spectre F`,"tester.point.late":`Berceau tardif`};export{e as default};
